select x.name, x.name_ja, x.city, x.area, x.category, x.lat, x.lng, x.coord_precision, x.hype, x.reality, x.verdict, x.tabelog_score, x.google_score, x.price, x.tip, x.sources, x.audience, x.baby_notes, x.local_pick, x.maps_url, x.website_url, x.serves, x.dishes, x.todo, x.special, x.highlights, x.time_needed, x.kosher, x.kosher_note, x.address, x.opens, x.closes, x.closed_weekdays, x.closed_dates, x.open_dates, x.best_time, x.visit_mins, x.booking, x.plan_line, x.baby_block, x.tags, x.en, x.facts_at, x.facts_sure, false from jsonb_populate_recordset(null::place_library, $cards$[{"name":"Okonomiyaki Micchan Sohonten Hatchobori","name_ja":"お好み焼 みっちゃん総本店 八丁堀本店","city":"hiroshima","area":"Downtown Hiroshima","category":"food","lat":34.3946,"lng":132.4632,"coord_precision":"approx","hype":"הבית שטוען שהמציא את האוקונומיאקי בסגנון הירושימה, פועל מ-1950.","reality":"אוקונומיאקי קלאסי ופריך עם הרוטב המקורי, טוב ולא יותר מזה מול החנויות הקטנות. נוח, גדול ועם תור שזז מהר.","verdict":"worth_it","tabelog_score":3.49,"google_score":null,"price":"¥1,000-2,500 לסועד","tip":"בעונה כדאי להוסיף צדפות לאוקונומיאקי או להזמין צדפות על הפלנצ׳ה בצד.","sources":["https://tabelog.com/en/hiroshima/A3401/A340108/34000256/","https://www.okonomi.co.jp/hatchobori.html"],"audience":"baby","baby_notes":"יש כיסאות לילדים, תפריט ילדים ומקום לעגלה. 47 מקומות, ללא עישון.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Micchan%20Sohonten%20Hatchobori%20Hiroshima","website_url":"https://www.okonomi.co.jp/","serves":"אוקונומיאקי בסגנון הירושימה (שכבות של בצק דק, כרוב, אטריות וביצה על הפלנצ׳ה) עם הרוטב של הבית.","dishes":["אוקונומיאקי סובה עם ביצה","אוקונומיאקי עם צדפות","צדפות על הפלנצ׳ה"],"todo":null,"special":null,"highlights":[],"time_needed":"כשעה","kosher":"options","kosher_note":"לבקש בלי חזיר (בוטה נאשי) או עם ביצה וירקות בלבד; המשטח משותף.","address":"6-7 Hatchobori, Naka-ku, Hiroshima","opens":"11:30","closes":"21:00","closed_weekdays":[],"closed_dates":[],"open_