select x.name, x.name_ja, x.city, x.area, x.category, x.lat, x.lng, x.coord_precision, x.hype, x.reality, x.verdict, x.tabelog_score, x.google_score, x.price, x.tip, x.sources, x.audience, x.baby_notes, x.local_pick, x.maps_url, x.website_url, x.serves, x.dishes, x.todo, x.special, x.highlights, x.time_needed, x.kosher, x.kosher_note, x.address, x.opens, x.closes, x.closed_weekdays, x.closed_dates, x.open_dates, x.best_time, x.visit_mins, x.booking, x.plan_line, x.baby_block, x.tags, x.en, x.facts_at, x.facts_sure, false from jsonb_populate_recordset(null::place_library, $cards$[{"name":"Komatsu Yasuke","name_ja":"小松 弥助","city":"kanazawa","area":"Station & Omicho","category":"food","lat":36.5765,"lng":136.6505,"coord_precision":"approx","hype":"סושייה אגדית של השף מורי איצ'ירו, עם הציון הגבוה ביותר לסושי בקנאזאווה בטאבלוג.","reality":"סושי ברמה הכי גבוהה בעיר, ובצהריים. מקום אחד ברשימה ששווה לתכנן סביבו טיול, אבל ההזמנה קשה מאוד.","verdict":"gem","tabelog_score":4.3,"google_score":null,"price":"¥20,000-40,000 לסועד","tip":"פתוח רק עד 16:30, כלומר זו ארוחת צהריים.","sources":["https://tabelog.com/en/ishikawa/A1701/A170101/17010524/","https://hamoni.jp/en/area/ishikawa/kanazawa/shops"],"audience":"adults","baby_notes":"דלפק סושי שקט ורשמי, לא מתאים לתינוק.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Komatsu%20Yasuke%20Kanazawa","website_url":null,"serves":"אומקסה סושי (סדרת סושי לפי בחירת השף) מדגי הים של הוקוריקו.","dishes":["אומקסה סושי","סושי נודוגורו"],"todo":null,"special":null,"highlights":[],"time_needed":null,"kosher":"options","kosher_note":"אפשר לבקש מראש סדרה בלי רכיכות ופירות ים, רק דגים.","address":"2-17-21 Honmachi, Kanazawa Chaya Bekkan 1F, Kanazawa","opens":"11:00","closes":"16:30","closed_weekdays":[3,4],"closed_dates":[],"open_dates":[],"best_time":"midday","visit_mins":90,"booking":"required","plan_line":"רק בהזמנה, בצהריים; סגור ברביעי וחמישי","baby_block":"דלפק רשמי, לא לתינוקות","tags":["sushi","omakase","fine dining","nodoguro","edomae","counter sushi","lunch","michelin level","סושי","אומקסה","מסעדת יוקרה","נודוגורו","צהריים","דלפק"],"en":{"hype":"The legendary sushi counter of chef Mori Ichiro, Kanazawa's top-rated sushi on Tabelog.","reality":"The best sushi in the city, at lunch. One of the few places worth planning a trip around, but very hard to book.","tip":"Open only until 16:30, so this is a lunch.","baby_notes":"Quiet, formal sushi counter, not for a baby.","price":"¥20,000-40,000 per person","serves":"Omakase sushi (chef's choice series) from Hokuriku fish.","dishes":["Omakase sushi","Nodoguro sushi"],"todo":null,"special":null,"highlights":[],"time_needed":null,"kosher_note":"Ask ahead for a fish-only series without shellfish.","plan_line":"Booking only, lunch hours; closed Wednesday and Thursday","baby_block":"Formal counter, not for babies"},"facts_at":"2026-11-09","facts_sure":true},{"name":"Benkei","name_ja":"弁慶","city":"kanazawa","area":"Station & Omicho","category":"food","lat":36.5768,"lng":136.6496,"coord_precision":"approx","hype":"מסעדה יפנית בקומה השישית של מלון ניקו, ליד התחנה, עם דלפקי סושי, קאיסקי וגריל.","reality":"פחות אווירה מקומית, אבל נוח מאוד: מקבלים ילדים ועגלות, יש תפריט באנגלית וחדרים פרטיים.","verdict":"worth_it","tabelog_score":3.6,"google_score":null,"price":"צהריים ¥4,000-8,000, ערב ¥10,000-20,000","tip":"סושי נודוגורו מאודה הוא המנה שבגללה מגיעים.","sources":["https://tabelog.com/en/ishikawa/A1701/A170101/17000101/"],"audience":"baby","baby_notes":"מקבלים ילדים ועגלות, ויש חדרים פרטיים בתשלום.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Benkei%20Kanazawa","website_url":null,"serves":"סושי, קאיסקי (ארוחה יפנית ברצף מנות) וטמפורה, וגם קורס בקר.","dishes":["סושי נודוגורו מאודה","סט צהריים","טמפורה"],"todo":null,"special":null,"highlights":[],"time_needed":null,"kosher":"options","kosher_note":"קל לבקש מנות דגים בלבד; לציין מראש בלי פירות ים.","address":"2-15-1 Honmachi, Hotel Nikko Kanazawa 6F, Kanazawa","opens":"11:30","closes":"21:00","closed_weekdays":[3],"closed_dates":[],"open_dates":[],"best_time":"midday","visit_mins":90,"booking":"recommended","plan_line":"סט צהריים ב-¥4,000-8,000 שווה יותר מהערב","baby_block":null,"tags":["sushi","kaiseki","tempura","nodoguro","hotel restaurant","japanese cuisine","lunch set","station","private room","סושי","קאיסקי","טמפורה","נודוגורו","מסעדת מלון","צהריים","חדר פרטי"],"en":{"hype":"A Japanese restaurant on the 6th floor of Hotel Nikko by the station, with sushi, kaiseki and grill counters.","reality":"Less local feel, but very easy: kids and strollers welcome, English menu and private rooms.","tip":"Steamed nodoguro sushi is the dish to come for.","baby_notes":"Kids and strollers welcome; private rooms for a fee.","price":"Lunch ¥4,000-8,000, dinner ¥10,000-20,000","serves":"Sushi, kaiseki (Japanese multi-course) and tempura, plus a beef course.","dishes":["Steamed nodoguro sushi","Lunch set","Tempura"],"todo":null,"special":null,"highlights":[],"time_needed":null,"kosher_note":"Easy to ask for fish only; say no seafood ahead.","plan_line":"Lunch sets at ¥4,000-8,000 are better value than dinner","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Shusui Daigo","name_ja":"酒粋 醍醐","city":"kanazawa","area":"Station & Omicho","category":"food","lat":36.573,"lng":136.6528,"coord_precision":"approx","hype":"איזקאיה (פאב יפני) בין התחנה לשוק, עם כ-500 סוגי סאקה ודגים טריים.","reality":"בחירת הסאקה מטורפת והאוכל טוב, במיוחד צלחת הסשימי. מחירים של ערב בחוץ, לא של פאב שכונתי.","verdict":"gem","tabelog_score":3.71,"google_score":null,"price":"¥6,000-8,000 לסועד","tip":"נפתח כבר ב-15:00, טוב לשתייה מוקדמת.","sources":["https://tabelog.com/en/ishikawa/A1701/A170101/17009374/"],"audience":"baby","baby_notes":"מקבלים ילדים ועגלות, יש חדרי טטאמי וחדר פרטי.","local_pick":true,"maps_url":"https://www.google.com/maps/search/?api=1&query=Shusui%20Daigo%20Kanazawa","website_url":null,"serves":"סשימי מדגי מפרץ טויאמה, ירקות קאגה וכמות עצומה של סאקה.","dishes":["צלחת סשימי","ירקות קאגה","טעימות סאקה"],"todo":null,"special":null,"highlights":[],"time_needed":null,"kosher":"options","kosher_note":"יש הרבה דגים רגילים; לוותר על רכיכות ושרימפס.","address":"19-4 Yasuemachi, Kanazawa","opens":"15:00","closes":"23:00","closed_weekdays":[0],"closed_dates":[],"open_dates":[],"best_time":"evening","visit_mins":120,"booking":"recommended","plan_line":"תוספת מנה פותחת ¥600; כדאי להזמין בערב","baby_block":null,"tags":["izakaya","sake","sake bar","sashimi","kaga vegetables","seafood","dinner","drinks","איזקאיה","סאקה","בר סאקה","סשימי","ירקות קאגה","דגים","ארוחת ערב"],"en":{"hype":"An izakaya (Japanese pub) between the station and the market with about 500 kinds of sake and fresh fish.","reality":"The sake list is wild and the food is good, especially the sashimi platter. Night-out prices, not a corner pub.","tip":"Opens at 15:00, good for an early drink.","baby_notes":"Kids and strollers welcome; tatami rooms and a private room.","price":"¥6,000-8,000 per person","serves":"Sashimi from Toyama Bay, Kaga vegetables and a huge sake list.","dishes":["Sashimi platter","Kaga vegetables","Sake tasting"],"todo":null,"special":null,"highlights":[],"time_needed":null,"kosher_note":"Plenty of plain fish; skip shellfish and shrimp.","plan_line":"¥600 starter charge; book for dinner","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Kanazawa Maimon Sushi Honten","name_ja":"金沢まいもん寿司 本店","city":"kanazawa","area":"Station & Omicho","category":"food","lat":36.577,"lng":136.6385,"coord_precision":"approx","hype":"סושי על מסוע מקומי, עם דגי הוקוריקו, בסניף הראשי מערבית לתחנה.","reality":"סושי מסוע ברמה גבוהה מהרגיל ובמחיר סביר, אבל זו רשת עם תורים ארוכים בסופי שבוע.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"¥2,000-5,000 לסועד","tip":null,"sources":["https://www.maimon-susi.com/","https://www.gltjp.com/en/article/item/21235/"],"audience":"baby","baby_notes":"סושי מ