select x.name, x.name_ja, x.city, x.area, x.category, x.lat, x.lng, x.coord_precision, x.hype, x.reality, x.verdict, x.tabelog_score, x.google_score, x.price, x.tip, x.sources, x.audience, x.baby_notes, x.local_pick, x.maps_url, x.website_url, x.serves, x.dishes, x.todo, x.special, x.highlights, x.time_needed, x.kosher, x.kosher_note, x.address, x.opens, x.closes, x.closed_weekdays, x.closed_dates, x.open_dates, x.best_time, x.visit_mins, x.booking, x.plan_line, x.baby_block, x.tags, x.en, x.facts_at, x.facts_sure, false from jsonb_populate_recordset(null::place_library, $cards$[{"name":"Oden Kikuichi","name_ja":"おでん 菊一","city":"kanazawa","area":"Nagamachi & Katamachi","category":"food","lat":36.5592,"lng":136.6505,"coord_precision":"approx","hype":"דלפק אודן בקטמאצ'י מ-1934, שנחשב בעיר לאחד המקומות שבהם נולד אודן קנאזאווה.","reality":"ציר זהוב ובהיר ואווירה של פעם, ובמחיר נמוך. 14 מקומות בלבד ותור בסופ\"ש.","verdict":"gem","tabelog_score":3.53,"google_score":null,"price":"¥1,000-3,000 לסועד","tip":"בחורף יש קאני-מן, קונכיית סרטן ממולאת, המנה המפורסמת.","sources":["https://tabelog.com/en/ishikawa/A1701/A170101/17000082/","https://visitkanazawa.jp/en/feature/detail_490.html"],"audience":"adults","baby_notes":"14 מקומות, בעיקר דלפק.","local_pick":true,"maps_url":"https://www.google.com/maps/search/?api=1&query=Oden%20Kikuichi%20Kanazawa","website_url":null,"serves":"אודן בציר בהיר, ובחורף קאני-מן (קונכיית סרטן ממולאת בבשר וביצים).","dishes":["קאני-מן (בחורף)","צנונית","קורומה-פו"],"todo":null,"special":null,"highlights":[],"time_needed":null,"kosher":"options","kosher_note":"הקאני-מן הוא סרטן; צנונית, ביצה ועוגות דגים בסדר.","address":"2-1-23 Katamachi, Kanazawa","opens":"17:30","closes":"21:30","closed_weekdays":[2,3],"closed_dates":[],"open_dates":[],"best_time":"evening","visit_mins":75,"booking":"no","plan_line":"סגור בשלישי ורביעי; נסגר כשהאודן נגמר","baby_block":"דלפק קטן","tags":["oden","kanazawa oden","daikon","fish cake","sake","dinner","local","katamachi","אודן","אודן קנאזאווה","צנונית","עוגות דגים","סאקה","ארוחת ערב","מקומי","crab","kanimen","סרטן"],"en":{"hype":"A Katamachi oden counter since 1934, seen in the city as one of the birthplaces of Kanazawa oden.","reality":"A clear golden broth, an old-time feel and low prices. Only 14 seats and a weekend queue.","tip":"In winter there is kani-men, a stuffed crab shell, the famous dish.","baby_notes":"14 seats, mostly counter.","price":"¥1,000-3,000 per person","serves":"Oden in a light broth, and in winter kani-men (crab shell stuffed with meat and roe).","dishes":["Kani-men (winter)","Daikon","Kuruma-fu"],"todo":null,"special":null,"highlights":[],"time_needed":null,"kosher_note":"Kani-men is crab; daikon, egg and fish cakes are fine.","plan_line":"Closed Tuesday and Wednesday; closes when the oden runs out","baby_block":"Small counter"},"facts_at":"2026-11-09","facts_sure":true},{"name":"Oden Takasago","name_ja":"おでん高砂","city":"kanazawa","area":"Nagamachi & Katamachi","category":"food","lat":36.5598,"lng":136.652,"coord_precision":"approx","hype":"אודן בקטמאצ'י מ-1936, דור שלישי, עם ציר בסגנון קאנטו (טוקיו) שנדיר בקנאזאווה.","reality":"ציר כהה ומתוק יותר מהמקובל בעיר ואווירה רטרו. טוב מאוד למי שכבר טעם אודן מקומי ורוצה להשוות.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"¥2,000-4,000 לסועד","tip":"קארי אודן ודוטה-יאקי הם המנות המיוחדות.","sources":["https://visitkanazawa.jp/en/feature/detail_490.html","https://www.magical-trip.com/media/best-kanazawa-oden-restaurants-2025-11-authentic-local-favorites-by-area/"],"audience":"adults","baby_notes":"דלפק בלבד.","local_pick":true,"maps_url":"https://www.google.com/maps/search/?api=1&query=Oden%20Takasago%20Kanazawa","website_url":"http://oden-takasago.com/","serves":"אודן בציר קאנטו עם חומרים של קנאזאווה, קארי אודן ודוטה-יאקי.","dishes":["קארי אודן","דוטה-יאקי","צנונית"],"todo":null,"special":null,"highlights":[],"time_needed":null,"kosher":"options","kosher_note":"הציר מדגים; לוותר על פירות ים ועל הדוטה-יאקי.","address":"Katamachi, Kanazawa","opens":"16:00","closes":"21:00","closed_weekdays":[0],"closed_dates":[],"open_dates":[],"best_time":"evening","visit_mins":75,"booking":"no","plan_line":"סגור בראשון ובחגים; נסגר כשהאודן נגמר","baby_block":"דלפק בלבד","tags":["oden","kanazawa oden","daikon","fish cake","sake","dinner","local","katamachi","אודן","אודן קנאזאווה","צנונית","עוגות דגים","סאקה","ארוחת ערב","מקומי","curry oden","kanto style","קארי"],"en":{"hype":"Katamachi oden since 1936, third generation, with a Kanto (Tokyo) style broth that is rare in Kanazawa.","reality":"Darker, sweeter broth than usual here and a retro feel. Great for comparing once you have had local oden.","tip":"Curry oden and dote-yaki are the special dishes.","baby_notes":"Counter only.","price":"¥2,000-4,000 per person","serves":"Kanto-style oden with Kanazawa ingredients, curry oden and dote-yaki.","dishes":["Curry oden","Dote-yaki","Daikon"],"todo":null,"special":null,"highlights":[],"time_needed":null,"kosher_note":"Fish broth; skip the seafood and the dote-yaki.","plan_line":"Closed Sundays and holidays; closes when sold out","baby_block":"Counter only"},"facts_at":"2026-11-09","facts_sure":true},{"name":"Zeniya","name_ja":"銭屋","city":"kanazawa","area":"Nagamachi & Katamachi","category":"food","lat":36.5585,"lng":136.6505,"coord_precision":"approx","hype":"ריוטיי (בית אוכל יפני מסורתי) של קאיסקי קאגה בקטמאצ'י, מהמקומות היוקרתיים בעיר.","reality":"קאיסקי ברמה הגבוהה ביותר, לארוחה חגיגית אחת בטיול. המחירים והשעות מתקבלים רק בהזמנה.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":null,"tip":null,"sources":["https://www.zeniya.co.jp/"],"audience":"adults","baby_notes":"ארוחה רשמית וארוכה בחדרים שקטים.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Zeniya%20Kanazawa","website_url":"https://www.zeniya.co.jp/","serves":"קאיסקי (ארוחה יפנית ברצף מנות) בסגנון קאגה, עם דגים וירקות עונתיים.","dishes":["קאיסקי קאגה"],"todo":null,"special":null,"highlights":[],"time_needed":null,"kosher":"options","kosher_note":"לציין בהזמנה בלי פירות ים וחזיר; ריוטיי רגיל להתאים.","address":"2-29-7 Katamachi, Kanazawa","opens":null,"closes":null,"closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"evening","visit_mins":150,"booking":"required","plan_line":"רק בהזמנה דרך Pocket Concierge, יש אנגלית","baby_block":"ארוחה רשמית, לא לתינוקות","tags":["kaiseki","kaga cuisine","ryotei","fine dining","japanese cuisine","katamachi","dinner","special occasion","קאיסקי","מטבח קאגה","ריוטיי","מסעדת יוקרה","מטבח יפני","ארוחת ערב"],"en":{"hype":"A ryotei (traditional Japanese dining house) serving Kaga kaiseki in Katamachi, one of the city's top places.","reality":"Kaiseki at the highest level, for one special meal on a trip. Prices and hours come only with a booking.","tip":null,"baby_notes":"A long, formal meal in quiet rooms.","price":null,"serves":"Kaga-style kaiseki (Japanese multi-course) with seasonal fish and vegetables.","dishes":["Kaga kaiseki"],"todo":null,"special":null,"highlights":[],"time_needed":null,"kosher_note":"Say no seafood or pork when booking; a ryotei is used to adjusting.","plan_line":"Booking only via Pocket Concierge, in English","baby_block":"Formal meal, not for babies"},"facts_at":"2026-11-09","facts_sure":true},{"name":"Otome Zushi","name_ja":"乙女寿司","city":"kanazawa","area":"Nagamachi & Katamachi","category":"food","lat":36.5595,"lng":136.6502,"coord_precision":"approx","hype":"הסושייה הקלאסית של קנאזאווה בקיגורה-מאצ'י, עם דגי הוקוריקו עונתיים.","reality":"מהטובות בעיר ובמחיר של סושי עילית. לקוחות חדשים יכולים להזמין חודשיים מראש, וזה נתפס מהר.","verdict":"gem","tabelog_score":4.05,"google_score":null,"price":"¥20,000-30,000 לסועד","tip":"פתוח גם בצהריים, 12:00-14:00.","sources":["https://tabelog.com/en/ishikawa/A1701/A170101/17000107/","https://www.magical-trip.com/media/top-9-must-visit-izakayas-in-kanazawa-for-2025-savor-local-flavors-hidden-gems/"],"audience":"adults","baby_notes":"מקבלים ילדים, אבל זה דלפק של 9 מקומות ושקט מאוד.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Otome%20Zushi%20Kanazawa","website_url":null,"serves":"אומקסה סושי מדגי הוקוריקו העונתיים, כולל נודוגורו.","dishes":["אומקסה סושי","נודוגורו"],"todo":null,"special":null,"highlights":[],"time_needed":null,"kosher":"options","kosher_note":"לבקש מראש סדרה רק מדגים, בלי סרטן, אוני ורכיכות.","address":"4-10 Kiguramachi, Kanazawa","opens":"12:00","closes":"21:00","closed_weekdays":[0,3],"closed_dates":[],"open_dates":[],"best_time":"evening","visit_mins":120,"booking":"required","plan_line":"להזמין חודשיים מראש; אשראי בלבד, סגור ברביעי וראשון","baby_block":"דלפק שקט ורשמי","tags":["sushi","omakase","fine dining","nodoguro","counter sushi","kiguramachi","dinner","lunch","סושי","אומקסה","מסעדת יוקרה","נודוגורו","דלפק","ארוחת ערב"],"en":{"hype":"Kanazawa's classic sushi counter in Kiguramachi, with seasonal Hokuriku fish.","reality":"Among the best in the city, at top-sushi prices. New guests can book two months ahead, and it goes fast.","tip":"It is open for lunch too, 12:00-14:00.","baby_notes":"Children welcome, but it is a 9-seat, very quiet counter.","price":"¥20,000-30,000 per person","serves":"Omakase sushi from seasonal Hokuriku fish, including nodoguro.","dishes":["Omakase sushi","Nodoguro"],"todo":null,"special":null,"highlights":[],"time_needed":null,"kosher_note":"Ask ahead for a fish-only series without crab, urchin or shellfish.","plan_line":"Book two months ahead; cards only, closed Wed and Sun","baby_block":"Quiet, formal counter"},"facts_at":"2026-11-09","facts_sure":true},{"name":"Tsubajin","name_ja":"つば甚","city":"kanazawa","area":"Nagamachi & Katamachi","category":"food","lat":36.5505,"lng":136.649,"coord_precision":"approx","hype":"הריוטיי הוותיק ביותר בקנאזאווה, מ-1752, בטראמאצ'י מעל נהר סאי.","reality":"קאיסקי בבית היסטורי עם נוף, ארוחה של פעם בטיול. יקר, ובשבילו בעיקר מגיעים לאווירה.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":null,"tip":"יש גם ארוחת בוקר של קאני-גאיו (דייסת אורז עם סרטן) בהזמנה נפרדת.","sources":["https://www.tsubajin.co.jp/","https://www.magical-trip.com/media/top-9-must-visit-izakayas-in-kanazawa-for-2025-savor-local-flavors-hidden-gems/"],"audience":"adults","baby_notes":"ארוחה רשמית בחדרי טטאמי.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Tsubajin%20Kanazawa","website_url":"https://www.tsubajin.co.jp/","serves":"קאיסקי קאגה, נודוגורו מאודה ושורש לוטוס מאודה.","dishes":["קאיסקי","נודוגורו מאודה","לוטוס מאודה"],"todo":null,"special":null,"highlights":[],"time_needed":null,"kosher":"options","kosher_note":"לציין בהזמנה בלי פירות ים; הקאני-גאיו של הבוקר הוא סרטן.","address":"5-1-8 Teramachi, Kanazawa","opens":"11:00","closes":"21:00","closed_weekdays":[3],"closed_dates":[],"open_dates":[],"best_time":"midday","visit_mins":150,"booking":"required","plan_line":"להזמין ב-TableCheck; ארוחת הצהריים זולה יותר מהערב","baby_block":"ארוחה רשמית, לא לתינוקות","tags":["kaiseki","ryotei","kaga cuisine","historic","fine dining","teramachi","nodoguro","river view","קאיסקי","ריוטיי","מטבח קאגה","היסטורי","מסעדת יוקרה","טראמאצ'י","נודוגורו"],"en":{"hype":"Kanazawa's oldest ryotei, since 1752, in Teramachi above the Sai River.","reality":"Kaiseki in a historic house with a view, a once-a-trip meal. Pricey, and mostly about the setting.","tip":"There is also a kani-gayu (crab rice porridge) breakfast, booked separately.","baby_notes":"Formal meal in tatami rooms.","price":null,"serves":"Kaga kaiseki, steamed nodoguro and steamed lotus root.","dishes":["Kaiseki","Steamed nodoguro","Steamed lotus"],"todo":null,"special":null,"highlights":[],"time_needed":null,"kosher_note":"Say no seafood when booking; the breakfast kani-gayu is crab.","plan_line":"Book via TableCheck; lunch costs less than dinner","baby_block":"Formal meal, not for babies"},"facts_at":"2026-11-09","facts_sure":true},{"name":"Kanazawa Hirayama","name