select x.name, x.name_ja, x.city, x.area, x.category, x.lat, x.lng, x.coord_precision, x.hype, x.reality, x.verdict, x.tabelog_score, x.google_score, x.price, x.tip, x.sources, x.audience, x.baby_notes, x.local_pick, x.maps_url, x.website_url, x.serves, x.dishes, x.todo, x.special, x.highlights, x.time_needed, x.kosher, x.kosher_note, x.address, x.opens, x.closes, x.closed_weekdays, x.closed_dates, x.open_dates, x.best_time, x.visit_mins, x.booking, x.plan_line, x.baby_block, x.tags, x.en, x.facts_at, x.facts_sure, false from jsonb_populate_recordset(null::place_library, $cards$[{"name":"Rakugan Moroeya Nishichaya Karyo Ajiwai","name_ja":"落雁諸江屋 西茶屋菓寮 味和以","city":"kanazawa","area":"Nagamachi & Katamachi","category":"cafe","lat":36.553,"lng":136.6475,"coord_precision":"approx","hype":"בית התה של מורואיה, יצרני רקוגאן (ממתק סוכר יבש), ברובע נישי צ'איה.","reality":"רובע שקט בהרבה מהיגאשי צ'איה, וממתקים מעולים. מקום רגוע לשבת אחרי טראמאצ'י.","verdict":"gem","tabelog_score":3.67,"google_score":null,"price":"¥1,000-2,000 לאדם","tip":"בקיץ (יוני-ספטמבר) יש קאקיגורי אוג'י קינטוקי.","sources":["https://tabelog.com/en/ishikawa/A1701/A170101/17007462/","https://www.magical-trip.com/media/kanazawa-sweets-snacks-2025-top-local-delights-must-try-treats-insta-worthy-desserts/"],"audience":"baby","baby_notes":"מקבלים ילדים, שולחנות.","local_pick":true,"maps_url":"https://www.google.com/maps/search/?api=1&query=Rakugan%20Moroeya%20Nishichaya%20Karyo%20Ajiwai%20Kanazawa","website_url":null,"serves":"ממתקים יפניים, מאצ'ה ורקוגאן, וקאקיגורי בקיץ.","dishes":["סט מאצ'ה ווואגאשי","קאקיגורי אוג'י קינטוקי (בקיץ)"],"todo":null,"special":null,"highlights":[],"time_needed":null,"kosher":"friendly","kosher_note":"תה וממתקים.","address":"2-26-1 Nomachi, Kanazawa","opens":"10:00","closes":"17:00","closed_weekdays":[2],"closed_dates":[],"open_dates":[],"best_time":"afternoon","visit_mins":40,"booking":"no","plan_line":"סגור בשלישי; אפשר להזמין אונליין","baby_block":null,"tags":["cafe","coffee","sweets","dessert","קפה","בית קפה","קינוח","מתוקים","wagashi","rakugan","japanese sweets","matcha","tea house","nishi chaya","kakigori","ממתקים יפניים","מאצ'ה","בית תה","נישי צ'איה"],"en":{"hype":"The tearoom of Moroeya, rakugan (dry sugar sweet) makers, in the Nishi Chaya district.","reality":"A much quieter district than Higashi Chaya, and excellent sweets. A calm sit-down after Teramachi.","tip":"In summer (June-September) there is Uji kintoki kakigori.","baby_notes":"Kids welcome, tables.","price":"¥1,000-2,000 per person","serves":"Japanese sweets, matcha and rakugan, and kakigori in summer.","dishes":["Matcha and wagashi set","Uji kintoki kakigori (summer)"],"todo":null,"special":null,"highlights":[],"time_needed":null,"kosher_note":"Tea and sweets.","plan_line":"Closed Tuesdays; can be booked online","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Salon de The Kawamura","name_ja":"サロン・ド・テ・カワムラ","city":"kanazawa","area":"Nagamachi & Katamachi","category":"cafe","lat":36.5532,"lng":136.6478,"coord_precision":"approx","hype":"בית התה של אמאנאטו קוואמורה (שעועית מסוכרת) בנישי צ'איה, בקומה השנייה מעל החנות.","reality":"קינוחים יפים ושקט אמיתי, אבל לא נכנסים מתחת לגיל 6 ויש הזמנה אחת לאדם.","verdict":"worth_it","tabelog_score":3.52,"google_score":null,"price":"¥1,000-2,000 לאדם","tip":"צלחת קוואמורה (¥1,850) עם תה שעועית בשלושה צבעים היא ההזמנה הטובה.","sources":["https://tabelog.com/en/ishikawa/A1701/A170101/17011103/","https://www.magical-trip.com/media/discover-kanazawas-hidden-gems-11-traditional-kissaten-traditional-cafes-to-experience-in-2025-local-guide/"],"audience":"adults","baby_notes":"כניסה רק מגיל 6.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Salon%20de%20The%20Kawamura%20Kanazawa","website_url":null,"serves":"אמאנאטו (שעועית מבושלת בסוכר), פרפה שעועית אדומה ופרפה פירות עונתיים.","dishes":["צלחת קוואמורה","פרפה שעועית אדומה"],"todo":null,"special":null,"highlights":[],"time_needed":null,"kosher":"friendly","kosher_note":"ממתקים ותה בלבד.","address":"2-24-7 Nomachi 2F, Kanazawa","opens":"10:00","closes":"17:30","closed_weekdays":[],"closed_dates":["2026-12-22","2026-12-23","2026-12-24","2026-12-25","2026-12-26","2026-12-27","2026-12-28","2026-12-29","2026-12-30","2026-12-31"],"open_dates":[],"best_time":"afternoon","visit_mins":45,"booking":"no","plan_line":"סגור 22.12-4.1 ובשלישי הראשון בחודש","baby_block":"רק מגיל 6","tags":["cafe","coffee","sweets","dessert","קפה","בית קפה","קינוח","מתוקים","amanatto","sweet beans","parfait","wagashi","tea","nishi chaya","שעועית מתוקה","פרפה","ממתקים יפניים","נישי צ'איה"],"en":{"hype":"The tearoom of Amanatto Kawamura (sugared beans) in Nishi Chaya, upstairs from the shop.","reality":"Pretty desserts and real quiet, but no entry under age 6 and one order per person.","tip":"The Kawamura plate (¥1,850) with three-colour bean tea is the good order.","baby_notes":"Entry from age 6 only.","price":"¥1,000-2,000 per person","serves":"Amanatto (beans simmered in sugar), red bean parfait and seasonal fruit parfaits.","dishes":["Kawamura plate","Red bean parfait"],"todo":null,"special":null,"highlights":[],"time_needed":null,"kosher_note":"Sweets and tea only.","plan_line":"Closed 22 Dec to 4 Jan and the first Tuesday of the month","baby_block":"Age 6 and up only"},"facts_at":"2026-11-09","facts_sure":true},{"name":"Bar Spoon","name_ja":"バー スプーン","city":"kanazawa","area":"Nagamachi & Katamachi","category":"nightlife","lat":36.5603,"lng":136.6528,"coord_precision":"approx","hype":"בר קוקטיילים קטן וותיק בקטמאצ'י, פתוח מ-1986.","reality":"קוקטיילים קלאסיים ומקוריים מעולים וברמן שיודע מה הוא עושה. 13 מקומות, ומותר לעשן.","verdict":"gem","tabelog_score":3.65,"google_score":null,"price":"¥4,000-5,000 לאדם","tip":"סאקורה סאקורה הוא קוקטייל קינוח של הבית.","sources":["https://tabelog.com/en/ishikawa/A1701/A170101/17000079/","https://www.magical-trip.com/media/top-10-bars-in-kanazawa-for-2025-where-to-drink-like-a-local/"],"audience":"adults","baby_notes":"מעשנים בפנים.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Bar%20Spoon%20Kanazawa","website_url":null,"serves":"קוקטיילים קלאסיים ומקוריים, וגם אוכל קטן כמו קארי ואודן.","dishes":["סאקורה סאקורה","קוקטייל קלאסי"],"todo":null,"special":null,"highlights":[],"time_needed":null,"kosher":"friendly","kosher_note":"בעיקר משקאות.","address":"1-5-8 Katamachi, Chateau Bldg 1F, Kanazawa","opens":"17:00","closes":"00:00","closed_weekdays":[1],"closed_dates":[],"open_dates":[],"best_time":"night","visit_mins":90,"booking":"recommended","plan_line":"סגור בשני; 13 מקומות, כדאי להזמין","baby_block":"מעשנים בפנים","tags":["bar","drinks","nightlife","בר","משקאות","חיי לילה","cocktail","cocktail bar","whisky","katamachi","קוקטייל","בר קוקטיילים","וויסקי","קטמאצ'י"],"en":{"hype":"A small, long-running cocktail bar in Katamachi, open since 1986.","reality":"Excellent classic and original cocktails and a bartender who knows his craft. 13 seats, and smoking is allowed.","tip":"Sakura Sakura is the house dessert cocktail.","baby_notes":"Smoking allowed inside.","price":"¥4,000-5,000 per person","serves":"Classic and original cocktails, plus small food like curry and oden.","dishes":["Sakura Sakura","Classic cocktail"],"todo":null,"special":null,"highlights":[],"time_needed":null,"kosher_note":"Mostly drinks.","plan_line":"Closed Mondays; 13 seats, book ahead","baby_block":"Smoky inside"},"facts_at":"2026-11-09","facts_sure":true},{"name":"Soryu","name_ja":"漱流","city":"kanazawa","area":"Nagamachi & Katamachi","category":"nightlife","lat":36.5598,"lng":136.6533,"coord_precision":"approx","hype":"בר קוקטיילים מעוצב בטאטה-מאצ'י, עם כניסה מכוסה צמחים ופתוח עד 03:00.","reality":"מהברים היפים בעיר, עם קוקטיילי פירות עונתיים. יש תשלום כניסה ומותר לעשן.","verdict":"worth_it","tabelog_score":3.62,"google_score":null,"price":"¥4,000-5,000 לאדם","tip":"לבקש מהברמן את קוקטייל הפירות של העונה.","sources":["https://tabelog.com/en/ishikawa/A1701/A170101/17000898/","https://www.machiya-inn-japan.com/blog/izakaya-bars-katamachi-kanazawa/"],"audience":"adults","baby_notes":"מעשנים בפנים.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Soryu%20Kanazawa","website_url":null,"serves":"קוקטיילים, וויסקי, ג'ין ויין.","dishes":["קוקטייל פירות עונתי"],"todo":null,"special":null,"highlights":[],"time_needed":null,"kosher":"friendly","kosher_note":"משקאות בעיקר.","address":"12-2 Tatemachi, Kanazawa","opens":"18:00","closes":"03:00","closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"night","visit_mins":90,"booking":"no","plan_line":"תשלום כניסה ¥1,500 כולל נשנוש; פתוח עד 03:00","baby_block":"מעשנים בפנים","tags":["bar","drinks","nightlife","בר","משקאות","חיי לילה","cocktail","cocktail bar","fruit cocktail","late night","tatemachi","קוקטייל","בר קוקטיילים","לילה","קטמאצ'י"],"en":{"hype":"A designer cocktail bar in Tatemachi with a vine-covered entrance, open until 3:00.","reality":"One of the best-looking bars in the city, with seasonal fruit cocktails. Cover charge, and smoking allowed.","tip":"Ask the bartender for the fruit cocktail of the season.","baby_notes":"Smoking allowed inside.","price":"¥4,000-5,000 per person","serves":"Cocktails, whisky, gin and wine.","dishes":["Seasonal fruit cocktail"],"todo":null,"special":null,"highlights":[],"time_needed":null,"kosher_note":"Mostly drinks.","plan_line":"¥1,500 cover with snacks; open until 3:00","baby_block":"Smoky inside"},"facts_at":"2026-11-09","facts_sure":true},{"name":"Londonya Bar","name_ja":"倫敦屋酒場","city":"kanazawa","area":"Nagamachi & Katamachi","category":"nightlife","lat":36.5604,"lng":136.6532,"coord_precision":"approx","hype":"פאב בסגנון בריטי בקטמאצ'י מ-1969, עם קיר של בקבוקי מיניאטורה ויותר מ-150 משקאות.","reality":"מוסד ותיק עם וויסקי מהחבית ואוכל של פאב, ומקבלים בו גם ילדים. יש דמי שולחן.","verdict":"worth_it","tabelog_score":3.6,"google_score":null,"price":"¥5,000-10,000 לאדם","tip":"יש סינגל מאלט שמוזג ישר מה