 המזכרות נוח","baby_block":null,"tags":["department store","depachika","food hall","souvenirs","sweets","rainy day","shopping","כלבו","מרתף אוכל","דפאצ'יקה","מזכרות","ממתקים","יום גשום","קניות"],"en":{"hype":"The local department store in Korinbo, with a basement of Kanazawa sweets and souvenirs.","reality":"A regular department store, but the basement is good for packaged food gifts, and the 8th-floor restaurants stay open until 21:00.","tip":"A warm, covered spot for a rainy or snowy day, with good toilets.","baby_notes":"Lifts and a nursing and changing room, as in any big Japanese department store.","price":"Varies","serves":null,"dishes":[],"todo":"Go down to the basement for packaged sweets from old confectioners, and up to the 8th floor to eat.","special":null,"highlights":["Food basement","8th-floor restaurants"],"time_needed":"30-60 minutes","kosher_note":null,"plan_line":"Good on a rainy day; easy souvenir basement","baby_block":null},"facts_at":"2026-11-09","facts_sure":true}]$cards$::jsonb) x
where not exists (select 1 from place_library p where p.city = x.city and lower(p.name) = lower(x.name));
