select x.name, x.name_ja, x.city, x.area, x.category, x.lat, x.lng, x.coord_precision, x.hype, x.reality, x.verdict, x.tabelog_score, x.google_score, x.price, x.tip, x.sources, x.audience, x.baby_notes, x.local_pick, x.maps_url, x.website_url, x.serves, x.dishes, x.todo, x.special, x.highlights, x.time_needed, x.kosher, x.kosher_note, x.address, x.opens, x.closes, x.closed_weekdays, x.closed_dates, x.open_dates, x.best_time, x.visit_mins, x.booking, x.plan_line, x.baby_block, x.tags, x.en, x.facts_at, x.facts_sure, false from jsonb_populate_recordset(null::place_library, $cards$[{"name":"Kanazawa M'ZA","name_ja":"めいてつ・エムザ","city":"kanazawa","area":"Station & Omicho","category":"shopping","lat":36.5706,"lng":136.6553,"coord_precision":"approx","hype":"חנות כלבו בצומת מוסאשיגאצוג'י, ליד שוק אומיצ'ו, עם קומה שלמה של מזכרות מקומיות 'קורומון קוג'י'.","reality":"קורומון קוג'י בקומה הראשונה מרכז ממתקים, סאקה, יוזן, קוטאני ולכה במקום אחד. נוח לחבר לביקור בשוק.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"משתנה","tip":"עלי זהב קטנים וכלי שולחן הם הקנייה הפופולרית שם.","sources":["https://visitkanazawa.jp/en/shops/detail_50024.html"],"audience":"baby","baby_notes":"מעליות ושירותים נוחים, הפסקה טובה אחרי אומיצ'ו.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Kanazawa%20M%27ZA%20Kanazawa","website_url":null,"serves":null,"dishes":[],"todo":"עוברים בקורומון קוג'י בין ממתקים מבתים ותיקים, סאקה מקומי ומלאכות כמו קאגה יוזן וקוטאני.","special":null,"highlights":["קורומון קוג'י","מלאכות קאגה","סאקה מקומי"],"time_needed":"30-45 דקות","kosher":null,"kosher_note":null,"address":"15-1 Musashi-machi, Kanazawa, Ishikawa","opens":"10:00","closes":"19:30","closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"any","visit_mins":40,"booking":"no","plan_line":"שתי דקות מאומיצ'ו, לחבר לביקור בשוק","baby_block":null,"tags":["department store","souvenirs","crafts","sweets","sake","kutani","yuzen","כלבו","מזכרות","מלאכות יד","ממתקים","סאקה","קוטאני","יוזן"],"en":{"hype":"A department store at the Musashigatsuji crossing by Omicho market, with a whole floor of local souvenirs, 'Kuromon Koji'.","reality":"Kuromon Koji on the ground floor puts sweets, sake, Yuzen, Kutani and lacquer in one place. Easy to combine with the market.","tip":"Small gold leaf items and tableware are the popular buys.","baby_notes":"Lifts and good toilets, a good break after Omicho.","price":"Varies","serves":null,"dishes":[],"todo":"Walk Kuromon Koji among sweets from old houses, local sake and crafts like Kaga Yuzen and Kutani.","special":null,"highlights":["Kuromon Koji","Kaga crafts","Local sake"],"time_needed":"30-45 minutes","kosher_note":null,"plan_line":"Two minutes from Omicho, pair it with the market","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Tatemachi Street","name_ja":"竪町商店街","city":"kanazawa","area":"Nagamachi & Katamachi","category":"shopping","lat":36.5598,"lng":136.6528,"coord_precision":"approx","hype":"רחוב הקניות הצעיר של קנאזאווה, בין קורינבו לקאטאמאצ'י, עם בוטיקים, חנויות יד שנייה ובתי קפה.","reality":"רחוב קניות רגיל של אופנה צעירה, נעים לטיול קצר אבל לא יעד בפני עצמו.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"משתנה","tip":"מחבר בין קורינבו לסאיגאווה, טוב בדרך לנישי צ'איה.","sources":["https://visitkanazawa.jp/en/attractions/detail_51999.html"],"audience":"baby","baby_notes":"רחוב להולכי רגל, שטוח ונוח לעגלה.","local_pick":true,"maps_url":"https://www.google.com/maps/search/?api=1&query=Tatemachi%20Street%20Kanazawa","website_url":null,"serves":null,"dishes":[],"todo":"הולכים לאורך הרחוב, נכנסים לבוטיקים ולחנויות יד שנייה, וממשיכים לכיוון נהר סאיגאווה.","special":null,"highlights":["בוטיקים","חנויות יד שנייה"],"time_needed":"30-60 דקות","kosher":null,"kosher_note":null,"address":"Tatemachi, Kanazawa, Ishikawa","opens":null,"closes":null,"closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"afternoon","visit_mins":40,"booking":"no","plan_line":"בדרך מקורינבו לנישי צ'איה","baby_block":null,"tags":["shopping street","fashion","boutiques","vintage","second hand","clothes","רחוב קניות","אופנה","בוטיקים","וינטג'","יד שנייה","בגדים"],"en":{"hype":"Kanazawa's young shopping street between Korinbo and Katamachi, with boutiques, second-hand shops and cafes.","reality":"An ordinary young fashion street, nice for a short stroll but not a destination on its own.","tip":"It links Korinbo to the Saigawa river, handy on the way to Nishi Chaya.","baby_notes":"Pedestrian street, flat and easy with a stroller.","price":"Varies","serves":null,"dishes":[],"todo":"Walk the street, pop into boutiques and second-hand shops, and carry on toward the Saigawa river.","special":null,"highlights":["Boutiques","Second-hand shops"],"time_needed":"30-60 minutes","kosher_note":null,"plan_line":"On the way from Korinbo to Nishi Chaya","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Yamato Soy Sauce & Miso","name_ja":"ヤマト醤油味噌","city":"kanazawa","area":"Around Kanazawa","category":"shopping","lat":36.619,"lng":136.601,"coord_precision":"approx","hype":"יצרן סויה ומיסו ותיק ברובע הנמל אונו, עם סיור חינם, טעימות, חנות וגלידת סויה.","reality":"מעניין לחובבי אוכל ומתאים לחצי יום עם רובע אונו הישן. 20 דקות ברכב מהמרכז, קשה יותר באוטובוס.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"כניסה וסיור חינם","tip":"לנסות את גלידת הסויה ואת האמאזאקה.","sources":["https://visitkanazawa.jp/en/attractions/detail_10253.html"],"audience":"baby","baby_notes":"יש חניה ומקום שטוח, נוח עם עגלה.","local_pick":true,"maps_url":"https://www.google.com/maps/search/?api=1&query=Yamato%20Soy%20Sauce%20%26%20Miso","website_url":null,"serves":null,"dishes":[],"todo":"מצטרפים לסיור חינם בפארק הקוג'י, טועמים סויה, מיסו ואמאזאקה, וקונים בחנות. אפשר לאכול ארוחה של אוכל מותסס במסעדה שבמקום.","special":"רובע אונו הוא אחד ממרכזי ייצור הסויה הגדולים ביפן, עם מסורת של 400 שנה.","highlights":["סיור חינם","גלידת סויה","טעימות מיסו"],"time_needed":"שעה","kosher":null,"kosher_note":null,"address":"4 E-170 Ono-machi, Kanazawa, Ishikawa","opens":"10:00","closes":"17:00","closed_weekdays":[3],"closed_dates":[],"open_dates":[],"best_time":"midday","visit_mins":60,"booking":"no","plan_line":"סגור בימי רביעי, 20 דקות ברכב מהתחנה","baby_block":null,"tags":["soy sauce","miso","fermentation","koji","tasting","factory tour","soft serve","סויה","רוטב סויה","מיסו","תסיסה","קוג'י","טעימות","סיור במפעל","גלידה"],"en":{"hype":"An old soy sauce and miso maker in the Ono port district, with a free tour, tastings, a shop and soy sauce ice cream.","reality":"Interesting for food lovers and good for a half day with old Ono. 20 minutes by car from the centre, harder by bus.","tip":"Try the soy sauce ice cream and the amazake.","baby_notes":"Parking and flat ground, fine with a stroller.","price":"Free entry and tour","serves":null,"dishes":[],"todo":"Join the free tour of Koji Park, taste soy sauce, miso and amazake, and shop. You can have a fermented-food lunch at the on-site restaurant.","special":"Ono is one of Japan's big soy sauce centres, with 400 years of brewing.","highlights":["Free tour","Soy sauce ice cream","Miso tasting"],"time_needed":"1 hour","kosher_note":null,"plan_line":"Closed Wednesdays; 20 minutes by car from the station","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Gold Leaf Sakuda","name_ja":"金銀箔工芸さくだ","city":"kanazawa","area":"Higashi Chaya & Kazuemachi","category":"experience","lat":36.5718,"lng":136.665,"coord_precision":"approx","hype":"יצרן עלי זהב ותיק ליד היגאשי צ'איה, עם סדנה להדבקת זהב על קופסה או צלחת, ושירותים מצופים זהב.","reality":"סדנה מסודרת של שעה מ-¥1,760, מתאימה גם למי שאין לו ידיים טובות. בשעות העומס מגיעות קבוצות גדולות.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"מ-¥1,760 לאדם","tip":"כדאי להציץ בשירותים המצופים זהב ופלטינה.","sources":["https://visitkanazawa.jp/en/shops/detail_10090.html"],"audienc