select x.name, x.name_ja, x.city, x.area, x.category, x.lat, x.lng, x.coord_precision, x.hype, x.reality, x.verdict, x.tabelog_score, x.google_score, x.price, x.tip, x.sources, x.audience, x.baby_notes, x.local_pick, x.maps_url, x.website_url, x.serves, x.dishes, x.todo, x.special, x.highlights, x.time_needed, x.kosher, x.kosher_note, x.address, x.opens, x.closes, x.closed_weekdays, x.closed_dates, x.open_dates, x.best_time, x.visit_mins, x.booking, x.plan_line, x.baby_block, x.tags, x.en, x.facts_at, x.facts_sure, false from jsonb_populate_recordset(null::place_library, $cards$[{"name":"umie","name_ja":"umie","city":"kobe","area":"Harborland & Meriken","category":"shopping","lat":34.6795,"lng":135.1835,"coord_precision":"approx","hype":"קניון הענק של הארבורלנד, שני מבנים סגורים עם מאות חנויות ועוד מוזאיקה לאורך המים.","reality":"קניון יפני גדול ונוח עם הרבה רשתות. טוב לקניות שימושיות ולערב גשום, לא משהו מיוחד לקובה.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"חינם להסתובב","tip":"יש בו חנויות של יוניקלו, מוג׳י וחנויות תינוקות. מחוברים בגשר מקורה לתחנת קובה.","sources":["https://www.japan-guide.com/e/e3553.html","https://umie.jp/"],"audience":"baby","baby_notes":"חדרי הנקה והחתלה, מעליות ושירותים נוחים בכל קומה כמעט.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=umie%20Kobe","website_url":"https://umie.jp/","serves":null,"dishes":[],"todo":"נכנסים מתחנת JR קובה בגשר המקורה, עוברים בין הצפוני לדרומי, ויוצאים לטיילת של מוזאיקה בערב.","special":null,"highlights":["מאות חנויות","חנויות תינוקות","חיבור ישיר לתחנה"],"time_needed":"שעה-שעתיים","kosher":null,"kosher_note":null,"address":"1-7-2 Higashikawasakicho, Chuo-ku, Kobe","opens":"10:00","closes":"20:00","closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"afternoon","visit_mins":90,"booking":"no","plan_line":"מחובר בגשר מקורה לתחנת JR קובה, טוב ליום גשום","baby_block":null,"tags":["mall","shopping mall","shopping","fashion","uniqlo","קניון","קניות","אופנה","יוניקלו","מוג׳י","muji","baby shop","חנות תינוקות","rainy day","יום גשום"],"en":{"hype":"Harborland's huge mall: two enclosed buildings with hundreds of shops, plus Mosaic along the water.","reality":"A big, convenient Japanese mall with lots of chains. Good for practical shopping and a rainy evening, nothing particularly Kobe.","tip":"Has Uniqlo, Muji and baby shops. Linked by a covered bridge to Kobe Station.","baby_notes":"Nursing and changing rooms, lifts and good toilets on most floors.","price":"Free to browse","serves":null,"dishes":[],"todo":"Walk in from JR Kobe Station over the covered bridge, cross between North and South Malls, then out to the Mosaic boardwalk in the evening.","special":null,"highlights":["Hundreds of shops","Baby shops","Direct station link"],"time_needed":"1-2 hours","kosher_note":null,"plan_line":"Covered bridge from JR Kobe Station; good on a rainy day","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Kobe Harborland Mosaic","name_ja":"神戸ハーバーランド モザイク","city":"kobe","area":"Harborland & Meriken","category":"shopping","lat":34.679,"lng":135.182,"coord_precision":"approx","hype":"מתחם חנויות ומסעדות פתוח על המים מול מגדל הנמל, עם הגלגל הענק, והמקום הכי יפה לנוף הלילה של הנמל.","reality":"החנויות עצמן תיירותיות, אבל הטיילת בערב, עם המגדל והמוזיאון מוארים ממול, היא מהנופים היפים בקובה.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"חינם להסתובב","tip":"הנוף הכי טוב מהמרפסות בקומה השנייה והשלישית, בשעה הכחולה אחרי השקיעה.","sources":["https://www.japan-guide.com/e/e3553.html","https://umie.jp/"],"audience":"baby","baby_notes":"טיילת שטוחה ומעליות לקומות, נוח לעגלה.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Kobe%20Harborland%20Mosaic%20Kobe","website_url":null,"serves":null,"dishes":[],"todo":"מסתובבים בטיילת, עולים למרפסות לנוף על המגדל, ואפשר לעלות לגלגל הענק בקצה הדרומי.","special":"ממול נמצאים מגדל הנמל וגג המפרש של מוזיאון הים, מוארים בלילה.","highlights":["נוף לילה למגדל הנמל","הגלגל הענק","מרפסות על המים"],"time_needed":"שעה","kosher":null,"kosher_note":null,"address":"1-6-1 Higashikawasakicho, Chuo-ku, Kobe","opens":"10:00","closes":"20:00","closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"evening","visit_mins":60,"booking":"no","plan_line":"להגיע אחרי השקיעה ולעלות למרפסות בקומה השנייה","baby_block":null,"tags":["waterfront","shopping","night view","ferris wheel","harbor","טיילת","קניות","נוף לילה","גלגל ענק","נמל","souvenirs","מזכרות","sunset","שקיעה","port tower view"],"en":{"hype":"An open-air shop and restaurant complex on the water facing Port Tower, with the big Ferris wheel and the best night view of the port.","reality":"The shops are touristy, but the evening boardwalk with the tower and museum lit up across the water is one of Kobe's best views.","tip":"Best view from the 2nd and 3rd floor terraces in the blue hour after sunset.","baby_notes":"Flat boardwalk and lifts to the floors, fine with a stroller.","price":"Free to browse","serves":null,"dishes":[],"todo":"Stroll the boardwalk, go up to the terraces for the tower view, and ride the Ferris wheel at the south end if you like.","special":"Port Tower and the Maritime Museum's sail roof sit right across the water, lit at night.","highlights":["Night view of Port Tower","The Ferris wheel","Waterside terraces"],"time_needed":"1 hour","kosher_note":null,"plan_line":"Come after sunset and head up to the 2nd floor terraces","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Kobe Anpanman Children's Museum & Mall","name_ja":"神戸アンパンマンこどもミュージアム＆モール","city":"kobe","area":"Harborland & Meriken","category":"experience","lat":34.677,"lng":135.1832,"coord_precision":"approx","hype":"מוזיאון משחק של אנפנמן, הדמות הכי אהובה על פעוטות ביפן, עם קניון חנויות וחנות לחם בצורת הדמויות.","reality":"לפעוטות זה גן עדן, למבוגרים זה רועש ויקר. עם תינוק בן כמה חודשים הקומה החינמית עם החנויות והמאפייה מספיקה.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"¥2,000-2,500 לאדם לפי היום, הקניון בקומה הראשונה חינם","tip":"בקומה הראשונה, בלי כרטיס, יש את חנויות אנפנמן ואת המאפייה עם לחמניות בצורת הדמויות.","sources":["https://www.japan-guide.com/e/e3553.html","https://www.kobe-anpanman.jp/"],"audience":"baby","baby_notes":"בנוי למשפחות: חניית עגלות, חדרי הנקה, החתלה ומים חמים לבקבוקים.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Kobe%20Anpanman%20Children%27s%20Museum%20%26%20Mall%20Kobe","website_url":"https://www.kobe-anpanman.jp/","serves":null,"dishes":[],"todo":"בקומה הראשונה קונים לחמניות אנפנמן ומסתובבים בחנויות. עם כרטיס עולים לקומה השנייה לאזורי משחק, הופעות שירה ופינות צילום.","special":"הכל בגובה של פעוטות, כולל הופעות קצרות של הדמויות כמה פעמים ביום.","highlights":["מאפיית ג׳אם וחנות הלחם","הופעות הדמויות","אזורי משחק"],"time_needed":"שעה-שעתיים","kosher":null,"kosher_note":null,"address":"1-6-2 Higashikawasakicho, Chuo-ku, Kobe","opens":"10:00","closes":"18:00","closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"morning","visit_mins":90,"booking":"recommended","plan_line":"לתינוק צעיר מספיקה הקומה החינמית עם החנויות והמאפייה","baby_block":null,"tags":["anpanman","kids museum","playground","toddlers","bakery","אנפנמן","מוזיאון ילדים","משחקייה","פעוטות","מאפייה","family","משפחה","indoor","בפנים","characters","דמויות","rainy day","יום גשום"],"en":{"hype":"A play museum for Anpanman, the favourite character of Japanese toddlers, with a shopping mall and a bakery making buns shaped like the characters.","reality":"Toddler heaven, loud and pricey for adults. With a baby of a few months, the free ground floor with the shops and bakery is enough.","tip":"The ground floor needs no ticket and has the Anpanman shops and the character bun bakery.","baby_notes":"Built for families: stroller parking, nursing rooms, changing and hot water for bottles.","price":"¥2,000-2,500 per person by day; ground-floor mall free","serves":null,"dishes":[],"todo":"Downstairs, buy Anpanman buns and browse. With a ticket, go up to the play areas, sing-along shows and photo spots.","special":"Everything is at toddler height, including short character shows several times a day.","highlights":["Jam's bakery","Character shows","Play areas"],"time_needed":"1-2 hours","kosher_note":null,"plan_line":"For a young baby, the free ground floor shops and bakery are enough","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"AQUARIUM x ART átoa","name_ja":"átoa","city":"kobe","area":"Harborland & Meriken","category":"experience","lat":34.6865,"lng":135.196,"coord_precision":"approx","hype":"אקווריום ״תיאטרלי״ בבניין מוזיאון הנמל, שמשלב מיכלי דגים עם הקרנות, אורות ומוזיקה.","reality":"יפה ומצטלם, אבל קטן ויקר ביחס לאקווריום רגיל. מתאים לשעה וחצי ביום גשום, לא בשביל מי שמחפשים כמות של חיות.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"¥2,600 למבוגר, ¥500 לפעוטות","tip":"בגג יש גן עם מים קטנים ופינגווינים, ואפשר לעשות את המקום לאט בשעה וחצי.","sources":["https://www.gltjp.com/en/directory/item/16100/","https://atoa-kobe.jp/"],"audience":"baby","baby_notes":"מעליות ומסלול נגיש. חשוך ורועש בחלק מהחדרים, תינוקות רגישים עלולים להיבהל.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=AQUARIUM%20x%20ART%20%C3%A1toa%20Kobe","website_url":"https://atoa-kobe.jp/","serves":null,"dishes":[],"todo":"עוברים בין החדרים עם המיכלים המוארים ומסיימים בגן על הגג עם הפינגווינים.","special":"כל חדר מעוצב כמו מיצג אמנות, עם הקרנות על הקירות סביב המיכלים.","highlights":["מיכלים עם הקרנות","פינגווינים על הגג","חדרים מעוצבים כמו מיצגים"],"time_needed":"שעה וחצי","kosher":null,"kosher_note":null,"address":"7-2 Shinkocho, Chuo-ku, Kobe","opens":"10:00","closes":"19:00","closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"any","visit_mins":90,"booking":"recommended","plan_line":"לקנות אונליין, יום גשום טוב, כניסה אחרונה 18:30","baby_block":null,"tags":["aquarium","fish","art","projection mapping","penguins","אקווריום","דגים","אמנות","הקרנות","פינגווינים","indoor","בפנים","rainy day","יום גשום","kids","ילדים"],"en":{"hype":"A 'theatrical' aquarium in the Kobe Port Museum building, mixing fish tanks with projections, lights and music.","reality":"Pretty and photogenic, but small and pricey for an aquarium. Good for 90 minutes on a rainy day, not if you want lots of animals.","tip":"There's a roof garden with small pools and penguins; take it slowly in about 90 minutes.","baby_notes":"Lifts and an accessible route. Some rooms are dark and loud, which may startle sensitive babies.","price":"¥2,600 adult, ¥500 toddlers","serves":null,"dishes":[],"todo":"Walk through the lit tank rooms and finish at the roof garden with the penguins.","special":"Each room is designed like an art installation, with projections on the walls around the tanks.","highlights":["Tanks with projections","Rooftop penguins","Rooms designed like installations"],"time_needed":"1.5 hours","kosher_note":null,"plan_line":"Book online; a good rainy-day pick, last entry 18:30","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Kin no Yu","name_ja":"金の湯","city":"kobe","area":"Arima Onsen","category":"experience","lat":34.7968,"lng":135.2475,"coord_precision":"approx","hype":"המרחץ הציבורי המפורסם של ארימה, עם מי ״הזהב״ החומים-אדומים העשירים בברזל ומלח.","reality":"המים מיוחדים באמת, אבל המבנה קטן, רק מקלחות ושתי בריכות פנימיות, ובצהריים ובסופ״ש צפוף מאוד. כדאי, רק בשעה הנכונה.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"¥800, ¥650 בימי חול. משולב עם גין נו יו ¥1,200","tip":"להגיע בפתיחה ב-8:00 או אחרי 19:00. אמבט הרגליים החינמי בחוץ מספיק למי שלא רוצים להתפשט.","sources":["https://www.japan-guide.com/e/e3558.html","https://arimaspa-kingin.jp/en-01.htm"],"audience":"adults","baby_notes":"תינוקות בחיתולים לא נכנסים לבריכות. אמבט הרגליים בחוץ מתאים כשמחזיקים את התינוק.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Kin%20no%20Yu%20Kobe","website_url":"https://arimaspa-kingin.jp/","serves":null,"dishes":[],"todo":"מתקלחים, טובלים בשתי הבריכות החומות, החמה והחמה מאוד, ובסוף טובלים רגליים באמבט החינמי מחוץ לבניין.","special":"מים חומים מחלידים שיוצאים מהאדמה, מהמעיינות החמים העתיקים ביפן.","highlights":["מי הזהב החומים","אמבט רגליים חינמי בחוץ","ברז מים מינרליים לשתייה"],"time_needed":"שעה","kosher":null,"kosher_note":null,"address":"833 Arimacho, Kita-ku, Kobe","opens":"08:00","closes":"22:00","closed_weekdays":[],"closed_dates":["2026-12-22"],"open_dates":[],"best_time":"morning","visit_mins":60,"booking":"no","plan_line":"להגיע ב-8:00 או אחרי 19:00, בצהריים צפוף מאוד","baby_block":"תינוקות בחיתולים לא נכנסים לבריכות","tags":["onsen","hot spring","public bath","bath","kinsen","אונסן","מעיין חם","מרחץ","אמבט","מרחץ ציבורי","foot bath","אמבט רגליים","iron","gold water","מי זהב","sento"],"en":{"hype":"Arima's famous public bath, with reddish-brown 'gold' water rich in iron and salt.","reality":"The water really is special, but the building is small, just showers and two indoor pools, and middays and weekends are packed. Worth it at the right time.","tip":"Come at the 8:00 opening or after 19:00. The free foot bath outside is enough if you don't want to undress.","baby_notes":"Babies in nappies can't go in the pools. The outdoor foot bath works while holding the baby.","price":"¥800, ¥650 on weekdays; combo with Gin no Yu ¥1,200","serves":null,"dishes":[],"todo":"Shower, soak in the two brown pools, hot and very hot, then dip your feet in the free bath outside.","special":"Rust-brown water from one of Japan's oldest hot springs.","highlights":["Brown gold water","Free outdoor foot bath","Mineral drinking tap"],"time_needed":"1 hour","kosher_note":null,"plan_line":"Go at 8:00 or after 19:00; midday is packed","baby_block":"Babies in nappies can't use the pools"},"facts_at":"2026-11-09","facts_sure":true},{"name":"Gin no Yu","name_ja":"銀の湯","city":"kobe","area":"Arima Onsen","category":"experience","lat":34.7983,"lng":135.2468,"coord_precision":"approx","hype":"המרחץ הציבורי השני של ארימה, עם מי ״הכסף״ השקופים, מוגזים ועם ראדון.","reality":"שקט יותר מקין נו יו וכמעט בלי תורים. המים פחות מרשימים לעין, אבל זה מקום נעים לטבול בלי צפיפות.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"¥700, ¥550 בימי חול","tip":"הכרטיס המשולב עם קין נו יו ב-¥1,200 שווה רק אם באמת רוצים שני מרחצאות באותו יום.","sources":["https://www.japan-guide.com/e/e3558.html","https://arimaspa-kingin.jp/en-02.htm"],"audience":"adults","baby_notes":"תינוקות בחיתולים לא נכנסים לבריכה.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Gin%20no%20Yu%20Kobe","website_url":"https://arimaspa-kingin.jp/","serves":null,"dishes":[],"todo":"עולים ברחוב הקטן אל המבנה, מתקלחים וטובלים בבריכה הגדולה עם המים השקופים.","special":"שני סוגי המים של ארימה, זהב וכסף, יוצאים מאותה עיירה במרחק דקות.","highlights":["מים שקופים מוגזים","פחות צפוף","בריכה גדולה אחת"],"time_needed":"45 דקות","kosher":null,"kosher_note":null,"address":"1039-1 Arimacho, Kita-ku, Kobe","opens":"09:00","closes":"21:00","closed_weekdays":[],"closed_dates":["2026-12-15"],"open_dates":[],"best_time":"afternoon","visit_mins":45,"booking":"no","plan_line":"פחות צפוף מקין נו יו, טוב כשבקין נו יו יש תור","baby_block":"תינוקות בחיתולים לא נכנסים לבריכה","tags":["onsen","hot spring","public bath","ginsen","silver water","אונסן","מעיין חם","מרחץ","מרחץ ציבורי","מי כסף","carbonated","radon","bath","אמבט","sento"],"en":{"hype":"Arima's second public bath, with clear 'silver' water that's carbonated and contains radon.","reality":"Quieter than Kin no Yu and almost no queue. The water looks less dramatic, but it's a nice soak without the crowd.","tip":"The ¥1,200 combo with Kin no Yu is only worth it if you really want two baths in one day.","baby_notes":"Babies in nappies can't go in the pool.","price":"¥700, ¥550 on weekdays","serves":null,"dishes":[],"todo":"Walk up the little street to the building, shower and soak in the big clear-water pool.","special":"Arima's two kinds of water, gold and silver, come out of the same small town minutes apart.","highlights":["Clear carbonated water","Less crowded","One big pool"],"time_needed":"45 minutes","kosher_note":null,"plan_line":"Less crowded than Kin no Yu; go here when that has a queue","baby_block":"Babies in nappies can't use the pool"},"facts_at":"2026-11-09","facts_sure":true},{"name":"Taiko no Yu","name_ja":"太閤の湯","city":"kobe","area":"Arima Onsen","category":"experience","lat":34.796,"lng":135.244,"coord_precision":"approx","hype":"מתחם מעיינות חמים גדול ומודרני עם בריכות פנימיות וחיצוניות של מי זהב וכסף, סאונות ואזורי מנוחה.","reality":"יקר בהרבה מהמרחצאות הציבוריים, אבל מקבלים חצי יום שלם: עשרות בריכות, יוקאטה, מגבות ומסעדות. בסופ״ש עמוס.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"¥2,750, ¥2,970 בסופ״ש. כולל יוקאטה ומגבות","tip":"מתכננים 3-4 שעות כדי שיהיה שווה. יש אזורים משותפים לבני זוג עם יוקאטה.","sources":["https://www.japan-guide.com/e/e3558.html","https://www.taikounoyu.com/"],"audience":"adults","baby_notes":"ילדים קטנים בחיתולים לא נכנסים לבריכות. אזורי המנוחה והמסעדות פתוחים לכולם.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Taiko%20no%20Yu%20Kobe","website_url":"https://www.taikounoyu.com/","serves":null,"dishes":[],"todo":"מקבלים יוקאטה ומגבות, עוברים בין הבריכות הפנימיות והחיצוניות של שני סוגי המים, נחים באזורי המנוחה ואוכלים במסעדה.","special":"יש בו שחזור של אמבט היסטורי מימי הידיושי, שאהב את ארימה.","highlights":["בריכות חיצוניות של מי זהב","שחזור אמבט הידיושי","סאונות ואזורי מנוחה"],"time_needed":"3-4 שעות","kosher":null,"kosher_note":null,"address":"292-2 Arimacho, Kita-ku, Kobe","opens":"10:00","closes":"22:00","closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"afternoon","visit_mins":210,"booking":"no","plan_line":"לתכנן 3-4 שעות כדי שהכניסה תשתלם","baby_block":"תינוקות בחיתולים לא נכנסים לבריכות","tags":["onsen","hot spring","spa","outdoor bath","rotenburo","אונסן","מעיין חם","ספא","אמבט חיצוני","רוטנבורו","sauna","סאונה","yukata","יוקאטה","kinsen","ginsen"],"en":{"hype":"A big modern hot spring complex with indoor and outdoor pools of gold and silver water, saunas and rest areas.","reality":"Much pricier than the public baths, but you get a full half day: lots of pools, yukata, towels and restaurants. Busy on weekends.","tip":"Plan 3-4 hours to make it worth it. There are shared areas couples can use in yukata.","baby_notes":"Toddlers in nappies can't use the pools. Rest areas and restaurants are open to all.","price":"¥2,750, ¥2,970 on weekends; yukata and towels included","serves":null,"dishes":[],"todo":"Get your yukata and towels, move between indoor and outdoor pools of both waters, rest in the lounges and eat in the restaurant.","special":"It has a replica of a historic bath from the days of Hideyoshi, who loved Arima.","highlights":["Outdoor gold-water pools","Hideyoshi bath replica","Saunas and lounges"],"time_needed":"3-4 hours","kosher_note":null,"plan_line":"Plan 3-4 hours so the entry is worth it","baby_block":"Babies in nappies can't use the pools"},"facts_at":"2026-11-09","facts_sure":true},{"name":"Tosen Goshobo","name_ja":"陶泉 御所坊","city":"kobe","area":"Arima Onsen","category":"experience","lat":34.7973,"lng":135.2468,"coord_precision":"approx","hype":"אחד הריוקנים הוותיקים בארימה, שפותח את אמבטיות האבן שלו עם מי הזהב גם למבקרים ביום.","reality":"הרבה יותר אווירה מהמרחצאות הציבוריים ופחות אנשים, אבל רק שלוש שעות ביום ויקר יחסית לטבילה.","verdict":"gem","tabelog_score":null,"google_score":null,"price":"¥2,250 לטבילת יום","tip":"טבילת היום רק בין 11:00 ל-14:00. כדאי להתקשר לוודא שפתוח באותו יום.","sources":["https://www.japan-guide.com/e/e3558.html","https://goshoboh.com/"],"audience":"adults","baby_notes":null,"local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Tosen%20Goshobo%20Kobe","website_url":"https://goshoboh.com/","serves":null,"dishes":[],"todo":"נכנסים לריוקן העץ הישן, טובלים בבריכות האבן הפנימיות עם המים החומים, ונחים בחדר ההמתנה.","special":"בית מרחץ שפועל מאות שנים, עם בריכות אבן חשוכות ותקרות עץ.","highlights":["בריכות אבן עם מי זהב","מבנה עץ היסטורי","שקט"],"time_needed":"שעה","kosher":null,"kosher_note":null,"address":"858 Arimacho, Kita-ku, Kobe","opens":"11:00","closes":"14:00","closed_weekdays":[1],"closed_dates":[],"open_dates":[],"best_time":"midday","visit_mins":60,"booking":"recommended","plan_line":"טבילת יום רק 11:00-14:00, סגור בימי שני","baby_block":null,"tags":["onsen","ryokan","hot spring","day bath","kinsen","אונסן","ריוקן","מעיין חם","טבילת יום","מי זהב","traditional","מסורתי","historic","היסטורי","bath","אמבט"],"en":{"hype":"One of Arima's oldest ryokan, opening its stone baths of gold water to day visitors.","reality":"Far more atmosphere than the public baths and fewer people, but only three hours a day and pricey for a soak.","tip":"Day bathing is only 11:00-14:00. Call to check it's open that day.","baby_notes":null,"price":"¥2,250 for a day bath","serves":null,"dishes":[],"todo":"Step into the old wooden ryokan, soak in the indoor stone pools of brown water, rest in the waiting room.","special":"A bathhouse running for centuries, with dark stone pools and wooden ceilings.","highlights":["Stone pools of gold water","Historic wooden building","Quiet"],"time_needed":"1 hour","kosher_note":null,"plan_line":"Day bath only 11:00-14:00; closed Mondays","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Arima Onsen Yumoto-zaka","name_ja":"湯本坂","city":"kobe","area":"Arima Onsen","category":"sight","lat":34.7975,"lng":135.2475,"coord_precision":"approx","hype":"הרחוב הראשי והמשופע של ארימה, סמטה צרה עם בתי עץ ישנים, חנויות מזכרות ונשנושים.","reality":"יפה ומלא אווירה, אבל קצר. בסופ״ש מלא מבקרים מאוסקה. בימי חול בבוקר הכי נעים.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"חינם","tip":"מנסים את ״טנסאן סנבאי״, וופלים דקים שנאפים עם מי המעיין המוגזים, ולחמניות מאודות בקיטור.","sources":["https://visit.arima-onsen.com/","https://www.japan-guide.com/e/e3558.html"],"audience":"baby","baby_notes":"עלייה תלולה וצרה, עם עגלה אפשרי אבל מעייף. מנשא נוח יותר.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Arima%20Onsen%20Yumoto-zaka%20Kobe","website_url":"https://visit.arima-onsen.com/","serves":null,"dishes":[],"todo":"עולים לאט מקין נו יו במעלה הסמטה, נכנסים לחנויות, וממשיכים למעיין טנג׳ין ולגין נו יו.","special":"עיירת מעיינות בת יותר מאלף שנה, שבה הרחוב שומר על בתי עץ ישנים.","highlights":["בתי עץ ישנים","טנסאן סנבאי","חנויות מזכרות"],"time_needed":"45 דקות","kosher":null,"kosher_note":null,"address":"Arimacho, Kita-ku, Kobe","opens":null,"closes":null,"closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"morning","visit_mins":45,"booking":"no","plan_line":"להגיע בבוקר ביום חול, בסופ״ש הסמטה צפופה","baby_block":null,"tags":["old street","onsen town","souvenirs","snacks","wooden houses","רחוב ישן","עיירת אונסן","מזכרות","נשנושים","בתי עץ","tansan senbei","טנסאן סנבאי","walk","טיול רגלי","hot spring town"],"en":{"hype":"Arima's main sloping street: a narrow lane of old wooden houses, souvenir shops and snacks.","reality":"Pretty and atmospheric, but short. Weekends are full of day-trippers from Osaka; weekday mornings are nicest.","tip":"Try tansan senbei, thin wafers baked with the carbonated spring water, and steamed buns.","baby_notes":"Steep narrow climb; doable with a stroller but tiring. A carrier is easier.","price":"Free","serves":null,"dishes":[],"todo":"Walk slowly up from Kin no Yu, pop into the shops, carry on to Tenjin source and Gin no Yu.","special":"A hot spring town over a thousand years old whose main street keeps its old wooden houses.","highlights":["Old wooden houses","Tansan senbei","Souvenir shops"],"time_needed":"45 minutes","kosher_note":null,"plan_line":"Go on a weekday morning; weekends the lane is packed","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Tenjin Gensen","name_ja":"天神泉源","city":"kobe","area":"Arima Onsen","category":"sight","lat":34.7978,"lng":135.249,"coord_precision":"approx","hype":"אחד ממקורות מי הזהב של ארימה, בחצר של מקדש קטן, שמהבאר שלו עולים אדים כל הזמן.","reality":"עצירה של חמש דקות, אבל רואים את המים יוצאים מהאדמה רותחים, וזה מגניב. חינם.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"חינם","tip":"בבקרים קרים של דצמבר האדים הכי חזקים.","sources":["https://visit.arima-onsen.com/","https://www.feel-kobe.jp/en/"],"audience":"baby","baby_notes":"סמטאות תלולות בדרך, מנשא נוח יותר.","local_pick":true,"maps_url":"https://www.google.com/maps/search/?api=1&query=Tenjin%20Gensen%20Kobe","website_url":"https://visit.arima-onsen.com/","serves":null,"dishes":[],"todo":"עולים לחצר המקדש הקטן, מסתכלים על באר האבן המהבילה וקוראים את השלט על מקור המים.","special":"מים שיוצאים בטמפרטורה של כמעט 100 מעלות.","highlights":["באר מהבילה","מקדש טנג׳ין הקטן","ריח הברזל"],"time_needed":"10 דקות","kosher":null,"kosher_note":null,"address":"1018 Arimacho, Kita-ku, Kobe","opens":null,"closes":null,"closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"morning","visit_mins":10,"booking":"no","plan_line":"לשלב בעלייה ברחוב יומוטו-זאקה, עדיף בבוקר קר","baby_block":null,"tags":["hot spring source","steam","onsen","shrine","מקור מעיין","אדים","אונסן","מקדש","free","חינם","gensen","boiling water","מים רותחים","arima","spring"],"en":{"hype":"One of Arima's gold-water sources, in the yard of a small shrine, with steam rising from its well all the time.","reality":"A five-minute stop, but seeing near-boiling water come out of the ground is cool. Free.","tip":"On cold December mornings the steam is strongest.","baby_notes":"Steep lanes on the way; a carrier is easier.","price":"Free","serves":null,"dishes":[],"todo":"Climb into the little shrine yard, look at the steaming stone well and read the sign about the source.","special":"Water coming out at close to 100°C.","highlights":["Steaming well","Small Tenjin shrine","Iron smell"],"time_needed":"10 minutes","kosher_note":null,"plan_line":"Fold into the Yumoto-zaka walk; best on a cold morning","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Arima Tansan Gensen Park","name_ja":"炭酸泉源公園","city":"kobe","area":"Arima Onsen","category":"sight","lat":34.7955,"lng":135.249,"coord_precision":"approx","hype":"פארק קטן סביב מעיין מים מוגזים טבעיים, שבימים עברו השתמשו בהם לסודה ולוופלים של ארימה.","reality":"מקום קטן ושקט, ואפשר לטעום מהברז את המים המוגזים, שיש להם טעם ברזל חזק. מעניין לחמש דקות.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"חינם","tip":"המים בברז טעימים למי שאוהבים מים מינרליים. לשתות לגימה ולא בקבוק.","sources":["https://visit.arima-onsen.com/","https://www.feel-kobe.jp/en/"],"audience":"baby","baby_notes":"עלייה קצרה מהעיירה, אפשרי עם עגלה.","local_pick":true,"maps_url":"https://www.google.com/maps/search/?api=1&query=Arima%20Tansan%20Gensen%20Park%20Kobe","website_url":"https://visit.arima-onsen.com/","serves":null,"dishes":[],"todo":"הולכים כמה דקות מהמרכז, טועמים מהברז ומסתכלים על אבן המעיין המקורה.","special":"מכאן התחיל ייצור המשקה המוגז והוופלים שארימה מפורסמת בהם.","highlights":["ברז מים מוגזים","ביתן המעיין","שקט מהמרכז"],"time_needed":"15 דקות","kosher":null,"kosher_note":null,"address":"Arimacho, Kita-ku, Kobe","opens":null,"closes":null,"closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"any","visit_mins":15,"booking":"no","plan_line":"לטעום מהברז, 5 דקות הליכה מקין נו יו","baby_block":null,"tags":["spring","carbonated water","soda","park","free","מעיין","מים מוגזים","סודה","פארק","חינם","tansan","טנסאן","mineral water","מים מינרליים","arima"],"en":{"hype":"A small park around a natural carbonated spring, once used for Arima's soda and wafers.","reality":"Small and quiet, and you can taste the fizzy water from the tap; it tastes strongly of iron. Interesting for five minutes.","tip":"Good if you like mineral water. A sip, not a bottle.","baby_notes":"Short climb from town; doable with a stroller.","price":"Free","serves":null,"dishes":[],"todo":"Walk a few minutes from the centre, taste from the tap and look at the covered spring stone.","special":"Where the fizzy drink and wafers Arima is known for started.","highlights":["Fizzy water tap","Spring pavilion","Quiet away from the centre"],"time_needed":"15 minutes","kosher_note":null,"plan_line":"Taste from the tap; 5 min walk from Kin no Yu","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Zuihoji Park","name_ja":"瑞宝寺公園","city":"kobe","area":"Arima Onsen","category":"sight","lat":34.8005,"lng":135.249,"coord_precision":"approx","hype":"פארק על הגבעה מעל ארימה, ממקומות השלכת המפורסמים בקנסאי, במקום מקדש בודהיסטי ישן.","reality":"בשיא השלכת, בתחילת עד אמצע נובמבר, הוא מהמם. בדצמבר רוב העלים כבר נשרו, ונשאר פארק שקט ונחמד.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"חינם","tip":"בתחילת דצמבר שווה לבדוק אם נשארו עלים אדומים לפני שעולים.","sources":["https://visit.arima-onsen.com/","https://www.japan-guide.com/e/e3558.html"],"audience":"adults","baby_notes":"עלייה תלולה מהעיירה ושבילי אבן, עם מנשא בלבד.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Zuihoji%20Park%20Kobe","website_url":"https://visit.arima-onsen.com/","serves":null,"dishes":[],"todo":"עולים כ-15 דקות מהעיירה, מסתובבים בשבילים בין עצי האדר ומגיעים לשער המקדש הישן.","special":"הידיושי ישב כאן לשחק גו, ולוח האבן שלו עדיין בפארק.","highlights":["עצי אדר","לוח הגו של הידיושי","השער הישן"],"time_needed":"45 דקות","kosher":null,"kosher_note":null,"address":"Arimacho, Kita-ku, Kobe","opens":null,"closes":null,"closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"morning","visit_mins":45,"booking":"no","plan_line":"בדצמבר רוב העלים כבר נשרו, לבדוק לפני שעולים","baby_block":"עלייה תלולה ושבילי אבן, מנשא בלבד","tags":["park","autumn leaves","maple","momiji","nature","פארק","שלכת","עלים אדומים","אדר","מומיג׳י","טבע","temple","מקדש","quiet","שקט"],"en":{"hype":"A hillside park above Arima on the grounds of an old Buddhist temple, one of Kansai's famous autumn leaf spots.","reality":"At peak colour in early to mid November it's stunning. By December most leaves are down and it's a quiet, pleasant park.","tip":"In early December check whether any red leaves remain before climbing.","baby_notes":"Steep climb from town and stone paths; carrier only.","price":"Free","serves":null,"dishes":[],"todo":"Walk up about 15 minutes from town, wander the paths under the maples and reach the old temple gate.","special":"Hideyoshi played go here, and his stone board is still in the park.","highlights":["Maple trees","Hideyoshi's go board","The old gate"],"time_needed":"45 minutes","kosher_note":null,"plan_line":"By December most leaves are down; check before climbing","baby_block":"Steep climb and stone paths, carrier only"},"facts_at":"2026-11-09","facts_sure":true},{"name":"Onsenji Temple","name_ja":"温泉寺","city":"kobe","area":"Arima Onsen","category":"sight","lat":34.7977,"lng":135.2483,"coord_precision":"approx","hype":"מקדש בודהיסטי קטן בלב ארימה, שלפי המסורת נוסד על ידי הנזיר שחידש את המעיינות לפני אלף שנה.","reality":"מקדש קטן וצנוע, עצירה של עשר דקות ליד הסמטאות. נחמד אבל לא סיבה לבוא.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"חינם","tip":"ממש מעליו נמצא מקדש יוזן, שהוא מקדש השינטו של המעיינות. אפשר לעשות את שניהם ברבע שעה.","sources":["https://visit.arima-onsen.com/"],"audience":"adults","baby_notes":"מדרגות אבן בכניסה.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Onsenji%20Temple%20Kobe","website_url":"https://visit.arima-onsen.com/","serves":null,"dishes":[],"todo":"עולים במדרגות, מסתכלים באולם הראשי וממשיכים למקדש יוזן הסמוך.","special":"המקדש קשור לנזיר גיוקי ולנזיר נינסאי, שלפי האגדה הקימו את העיירה מחדש.","highlights":["האולם הראשי","מקדש יוזן הסמוך","נוף לגגות העיירה"],"time_needed":"15 דקות","kosher":null,"kosher_note":null,"address":"1643 Arimacho, Kita-ku, Kobe","opens":null,"closes":null,"closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"morning","visit_mins":15,"booking":"no","plan_line":"לשלב עם מקדש יוזן שמעליו, רבע שעה לשניהם","baby_block":"מדרגות אבן בכניסה","tags":["temple","buddhist","shrine","history","מקדש","בודהיסטי","היסטוריה","yuzen shrine","stairs","מדרגות","arima","onsen town","עיירת אונסן","quiet","שקט"],"en":{"hype":"A small Buddhist temple in the heart of Arima, said to be founded by the monk who revived the springs a thousand years ago.","reality":"A small modest temple, a ten-minute stop by the lanes. Nice, but not a reason to come.","tip":"Right above it is Yuzen Shrine, the Shinto shrine of the springs. Both take 15 minutes.","baby_notes":"Stone steps at the entrance.","price":"Free","serves":null,"dishes":[],"todo":"Climb the steps, look into the main hall and continue to Yuzen Shrine next door.","special":"Linked to the monks Gyoki and Ninsai, who by legend rebuilt the town.","highlights":["Main hall","Yuzen Shrine next door","View over the town roofs"],"time_needed":"15 minutes","kosher_note":null,"plan_line":"Pair with Yuzen Shrine above it; 15 minutes for both","baby_block":"Stone steps at the entrance"},"facts_at":"2026-11-09","facts_sure":true},{"name":"Arima Toys and Automata Museum","name_ja":"有馬玩具博物館","city":"kobe","area":"Arima Onsen","category":"sight","lat":34.7975,"lng":135.247,"coord_precision":"approx","hype":"מוזיאון צעצועים קטן בכמה קומות, עם אוטומטים מכניים, רכבות צעצוע וצעצועי עץ מאירופה.","reality":"מפתיע וחמוד, בעיקר האוטומטים שזזים כשמסובבים ידית. טוב לשעה כשיורד גשם בארימה.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":null,"tip":"בקומה התחתונה יש חנות צעצועי עץ טובה למתנות לתינוקות.","sources":["https://www.japan-guide.com/e/e3558.html","https://visit.arima-onsen.com/"],"audience":"baby","baby_notes":"מעלית בבניין, אבל חלק מהקומות צפופות עם עגלה.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Arima%20Toys%20and%20Automata%20Museum%20Kobe","website_url":"https://visit.arima-onsen.com/","serves":null,"dishes":[],"todo":"עולים לקומה העליונה ויורדים קומה אחרי קומה: אוטומטים, רכבות צעצוע וצעצועי עץ שמותר לגעת בהם.","special":"אוסף אוטומטים מכניים שנדיר לראות ביפן, חלקם מופעלים כמה פעמים ביום.","highlights":["אוטומטים מכניים","רכבות צעצוע","חנות צעצועי עץ"],"time_needed":"שעה","kosher":null,"kosher_note":null,"address":"797 Arimacho, Kita-ku, Kobe","opens":null,"closes":null,"closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"any","visit_mins":60,"booking":"no","plan_line":"תוכנית גשם טובה בארימה, החנות למטה טובה למתנות","baby_block":null,"tags":["toy museum","toys","automata","wooden toys","museum","מוזיאון צעצועים","צעצועים","אוטומטים","צעצועי עץ","מוזיאון","kids","ילדים","rainy day","יום גשום","toy trains","רכבות צעצוע"],"en":{"hype":"A small multi-floor toy museum with mechanical automata, toy trains and European wooden toys.","reality":"Surprisingly charming, especially the automata that move when you turn a crank. Good for an hour when it rains in Arima.","tip":"The ground-floor shop has good wooden toys for baby gifts.","baby_notes":"Lift in the building, but some floors are tight with a stroller.","price":null,"serves":null,"dishes":[],"todo":"Go to the top floor and work your way down: automata, toy trains and wooden toys you can touch.","special":"A collection of mechanical automata rare in Japan, some demonstrated several times a day.","highlights":["Mechanical automata","Toy trains","Wooden toy shop"],"time_needed":"1 hour","kosher_note":null,"plan_line":"A good rain plan in Arima; the shop downstairs is good for gifts","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Mitsumori Honpo","name_ja":"三津森本舗","city":"kobe","area":"Arima Onsen","category":"shopping","lat":34.7973,"lng":135.2477,"coord_precision":"approx","hype":"חנות ותיקה שאופה את ״טנסאן סנבאי״, וופלים דקים ופריכים עם מי המעיין המוגזים של ארימה.","reality":"המזכרת הכי מוכרת מארימה, זולה, קלה וטעימה. רואים אותם אופים מאחורי הזכוכית.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"קופסאות מ-¥500 בערך","tip":"כדאי לקנות חתיכה חמה מהמגש ליד הקופה, הם הכי טובים טריים.","sources":["https://visit.arima-onsen.com/","https://www.feel-kobe.jp/en/"],"audience":"baby","baby_notes":null,"local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Mitsumori%20Honpo%20Kobe","website_url":"https://visit.arima-onsen.com/","serves":null,"dishes":[],"todo":"מסתכלים על האפייה מבעד לחלון, טועמים חתיכה טרייה וקונים קופסה למתנה.","special":"מתכון שבו מי המעיין המוגזים נותנים לוופל את הקלילות.","highlights":["טנסאן סנבאי טרי","אפייה מאחורי הזכוכית","קופסאות מתנה"],"time_needed":"10 דקות","kosher":null,"kosher_note":null,"address":"809 Arimacho, Kita-ku, Kobe","opens":null,"closes":null,"closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"any","visit_mins":10,"booking":"no","plan_line":"לקנות חתיכה חמה ישר מהאפייה, ממש ליד קין נו יו","baby_block":null,"tags":["souvenir","senbei","wafer","tansan senbei","sweets","מזכרת","סנבאי","ופלים","טנסאן סנבאי","ממתקים","crackers","קרקרים","gift","מתנה","omiyage"],"en":{"hype":"An old shop baking tansan senbei, thin crisp wafers made with Arima's carbonated spring water.","reality":"Arima's best-known souvenir: cheap, light and tasty. You can watch them bake behind the glass.","tip":"Grab a warm one from the tray by the till; they're best fresh.","baby_notes":null,"price":"Boxes from about ¥500","serves":null,"dishes":[],"todo":"Watch the baking through the window, taste a fresh one and buy a box to give.","special":"The fizzy spring water is what makes the wafer so light.","highlights":["Fresh tansan senbei","Baking behind glass","Gift boxes"],"time_needed":"10 minutes","kosher_note":null,"plan_line":"Grab a warm one straight off the line, right by Kin no Yu","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Kawakami Shoten","name_ja":"川上商店","city":"kobe","area":"Arima Onsen","category":"shopping","lat":34.7978,"lng":135.247,"coord_precision":"approx","hype":"חנות משפחתית ותיקה בארימה שמבשלת ״צוקודני״, פרפראות של סאנשו (פלפל יפני) ופטריות ברוטב סויה.","reality":"מזכרת מקומית אמיתית שהיפנים קונים. הטעם חזק ומלוח, טוב לאורז. למי שלא אוהב סאנשו זה פחות.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"צנצנות מ-¥600 בערך","tip":"נותנים לטעום. ״סאנשו קומבו״ (אצות עם סאנשו) הוא הקלאסי.","sources":["https://visit.arima-onsen.com/"],"audience":"baby","baby_notes":null,"local_pick":true,"maps_url":"https://www.google.com/maps/search/?api=1&query=Kawakami%20Shoten%20Kobe","website_url":"https://visit.arima-onsen.com/","serves":null,"dishes":[],"todo":"טועמים מהדוגמאות על הדלפק ובוחרים צנצנת או שתיים למתנה.","special":"מבשלים פה צוקודני עם סאנשו מקומי כבר יותר ממאה שנה.","highlights":["סאנשו קומבו","פטריות ברוטב סויה","דוגמאות לטעימה"],"time_needed":"10 דקות","kosher":null,"kosher_note":null,"address":"1175 Arimacho, Kita-ku, Kobe","opens":null,"closes":null,"closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"any","visit_mins":10,"booking":"no","plan_line":"לבקש לטעום לפני שקונים, הטעם חזק","baby_block":null,"tags":["souvenir","tsukudani","sansho","japanese pepper","condiment","מזכרת","צוקודני","סאנשו","פלפל יפני","תבלין","kombu","אצות","food gift","מתנת אוכל","local food","אוכל מקומי"],"en":{"hype":"An old family shop in Arima making tsukudani: sansho pepper and mushrooms simmered in soy sauce.","reality":"A real local souvenir that Japanese visitors buy. Strong and salty, great on rice. Less so if you don't like sansho.","tip":"They let you taste. Sansho kombu (kelp with sansho) is the classic.","baby_notes":null,"price":"Jars from about ¥600","serves":null,"dishes":[],"todo":"Taste the samples on the counter and pick a jar or two to give.","special":"Making sansho tsukudani here for over a century.","highlights":["Sansho kombu","Soy-simmered mushrooms","Tasting samples"],"time_needed":"10 minutes","kosher_note":null,"plan_line":"Ask to taste before buying; the flavour is strong","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Rokko-Arima Ropeway","name_ja":"六甲有馬ロープウェー","city":"kobe","area":"Arima Onsen","category":"experience","lat":34.794,"lng":135.243,"coord_precision":"approx","hype":"רכבל של 12 דקות מעל היער שמחבר את ארימה לפסגת הר רוקו, עם נוף על העמקים.","reality":"הדרך הכי יפה להגיע לארימה או לצאת ממנה, והופכת את הר רוקו וארימה ליום אחד. נסגר ברוח חזקה.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"¥1,400 כיוון אחד, ¥2,520 הלוך חזור","tip":"הסדר הנוח: עולים ברכבל הכבלים מרוקו, אוטובוס מעגלי בפסגה, ויורדים ברכבל לארימה לאונסן.","sources":["https://www.japan-guide.com/e/e3558.html","https://www.rokkosan.com/rokkoarima/index_eng.html"],"audience":"baby","baby_notes":"אפשר לעלות עם עגלה מקופלת, הקרונות מרווחים.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Rokko-Arima%20Ropeway%20Kobe","website_url":"https://koberope.jp/","serves":null,"dishes":[],"todo":"עולים לקרון בתחנת ארימה או בפסגה, נוסעים 12 דקות מעל היער ויורדים לצד השני.","special":"מחבר את פסגת רוקו ישירות לעיירת המעיינות, בלי לחזור לעיר.","highlights":["נוף על היער","חיבור רוקו לארימה","12 דקות באוויר"],"time_needed":"12 דקות נסיעה","kosher":null,"kosher_note":null,"address":"Arimacho, Kita-ku, Kobe","opens":null,"closes":null,"closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"midday","visit_mins":30,"booking":"no","plan_line":"לעלות לרוקו ולרדת ברכבל לארימה, כך עושים את שניהם ביום","baby_block":null,"tags":["ropeway","cable car","gondola","view","mountain","רכבל","קרון","נוף","הר","rokko","רוקו","arima","ארימה","forest","יער"],"en":{"hype":"A 12-minute ropeway over the forest linking Arima to the top of Mt Rokko, with views over the valleys.","reality":"The nicest way in or out of Arima, and it makes Mt Rokko plus Arima one day. Stops in strong wind.","tip":"Easiest order: Rokko cable car up, the summit loop bus, then the ropeway down to Arima for the onsen.","baby_notes":"A folded stroller fits; the cabins are roomy.","price":"¥1,400 one way, ¥2,520 return","serves":null,"dishes":[],"todo":"Board at Arima or at the summit, ride 12 minutes over the forest and get off on the other side.","special":"Connects Rokko's summit straight to the hot spring town without going back to the city.","highlights":["Forest views","Rokko to Arima link","12 minutes in the air"],"time_needed":"12-minute ride","kosher_note":null,"plan_line":"Go up Rokko and ride down to Arima; both in one day","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Rokko Cable Car","name_ja":"六甲ケーブル","city":"kobe","area":"Nada & Rokko","category":"experience","lat":34.7395,"lng":135.2395,"coord_precision":"approx","hype":"רכבל על פסים ישן ותלול שעולה בעשר דקות מהשכונות של קובה לפסגת הר רוקו.","reality":"נסיעה קצרה ונחמדה עם נוף פתוח לים בירידה. התחנה התחתונה רחוקה מהמרכז, צריך אוטובוס 16 מתחנת רוקו או רוקומיצ׳י.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"¥800 כיוון אחד, ¥1,550 הלוך חזור","tip":"לשבת בצד של הים בירידה. בפסגה יש תצפית טנראן חינמית ליד התחנה.","sources":["https://www.japan-guide.com/e/e3557.html","https://www.rokkosan.com/cable/"],"audience":"baby","baby_notes":"עגלה מקופלת עולה לקרון. בפסגה קר מאוד בדצמבר.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Rokko%20Cable%20Car%20Kobe","website_url":"https://www.rokkosan.com/cable/","serves":null,"dishes":[],"todo":"נוסעים באוטובוס 16 לתחנה התחתונה, עולים עשר דקות בקרון התלול, ובפסגה ממשיכים באוטובוס המעגלי לגן טראס או לרכבל של ארימה.","special":"קרונות בסגנון רטרו שעולים בשיפוע תלול מאוד מאז 1932.","highlights":["קרונות רטרו","נוף לים","תצפית טנראן בפסגה"],"time_needed":"10 דקות נסיעה","kosher":null,"kosher_note":null,"address":"Rokko Cable Shita Station, Nada-ku, Kobe","opens":null,"closes":null,"closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"midday","visit_mins":30,"booking":"no","plan_line":"אוטובוס 16 מתחנת JR רוקומיצ׳י לתחנה התחתונה","baby_block":null,"tags":["cable car","funicular","mountain","view","rokko","רכבל","פוניקולר","הר","נוף","רוקו","retro","רטרו","mt rokko","הר רוקו","train","רכבת"],"en":{"hype":"An old, steep funicular that climbs from Kobe's neighbourhoods to the top of Mt Rokko in ten minutes.","reality":"A short, nice ride with an open sea view on the way down. The bottom station is far from the centre; you need bus 16 from Rokko or Rokkomichi.","tip":"Sit on the sea side going down. At the top, the free Tenran lookout is right by the station.","baby_notes":"A folded stroller fits. It's very cold up top in December.","price":"¥800 one way, ¥1,550 return","serves":null,"dishes":[],"todo":"Take bus 16 to the bottom station, ride ten minutes up the steep track, then at the top take the loop bus to Garden Terrace or the Arima ropeway.","special":"Retro-style cars climbing a very steep grade since 1932.","highlights":["Retro cars","Sea view","Tenran lookout at the top"],"time_needed":"10-minute ride","kosher_note":null,"plan_line":"Bus 16 from JR Rokkomichi to the bottom station","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Rokko Tenran Observatory","name_ja":"六甲天覧台","city":"kobe","area":"Nada & Rokko","category":"sight","lat":34.7605,"lng":135.2385,"coord_precision":"approx","hype":"תצפית חינמית ליד התחנה העליונה של הרכבל, מעל קובה, אוסקה ומפרץ אוסקה.","reality":"נוף רחב מאוד בלי לשלם, ממש כשיוצאים מהרכבל. בלילה זה מהנופים המפורסמים ביפן, אבל קר ורוחני מאוד בדצמבר.","verdict":"gem","tabelog_score":null,"google_score":null,"price":"חינם","tip":"בקפה שליד התחנה אפשר לראות את הנוף מבפנים בחום.","sources":["https://www.rokkosan.com/","https://www.japan-guide.com/e/e3557.html"],"audience":"baby","baby_notes":"ליד התחנה ושטוח, אבל קר ורוח חזקה. להלביש את התינוק חם.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Rokko%20Tenran%20Observatory%20Kobe","website_url":"https://www.rokkosan.com/","serves":null,"dishes":[],"todo":"יוצאים מהתחנה העליונה של הרכבל, עומדים במרפסת מול העיר והמפרץ, ונכנסים לקפה להתחמם.","special":"אחד מ״נופי הלילה של עשרה מיליון דולר״ של קובה.","highlights":["נוף לאוסקה ולמפרץ","נוף לילה","הקפה ליד התחנה"],"time_needed":"20 דקות","kosher":null,"kosher_note":null,"address":"Rokko Sanjo Station, Rokkosancho, Nada-ku, Kobe","opens":null,"closes":null,"closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"evening","visit_mins":20,"booking":"no","plan_line":"חינם ליד תחנת הרכבל העליונה, לבוא עם מעיל חם","baby_block":null,"tags":["observatory","view","night view","free","mountain","תצפית","נוף","נוף לילה","חינם","הר","rokko","רוקו","osaka bay","מפרץ אוסקה","sunset","שקיעה"],"en":{"hype":"A free lookout by the cable car's top station, over Kobe, Osaka and Osaka Bay.","reality":"A huge view for nothing, right as you step off the cable car. At night it's one of Japan's famous views, but very cold and windy in December.","tip":"The cafe by the station lets you see the view from the warm inside.","baby_notes":"Right by the station and flat, but cold and windy. Dress the baby warm.","price":"Free","serves":null,"dishes":[],"todo":"Leave the top station, stand on the terrace facing the city and bay, then go into the cafe to warm up.","special":"One of Kobe's 'ten-million-dollar' night views.","highlights":["View to Osaka and the bay","Night view","Cafe by the station"],"time_needed":"20 minutes","kosher_note":null,"plan_line":"Free by the top cable station; bring a warm coat","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Rokko Garden Terrace","name_ja":"六甲ガーデンテラス","city":"kobe","area":"Nada & Rokko","category":"sight","lat":34.77,"lng":135.238,"coord_precision":"approx","hype":"מתחם חנויות, מסעדות ומרפסות תצפית על ראש הר רוקו, עם אחד הנופים הרחבים בקנסאי.","reality":"הכניסה חינם והנוף מעולה, בעיקר בשקיעה. המסעדות והחנויות תיירותיות, אבל זו הנקודה הכי נוחה בפסגה.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"כניסה חינם","tip":"אוטובוס מעגלי מתחנת הרכבל העליונה מגיע לכאן. אחרי השקיעה האוטובוסים מתמעטים, לבדוק את השעה האחרונה.","sources":["https://www.hyogo-tourism.jp/world/spot/detail_1029.html","https://www.rokkosan.com/"],"audience":"baby","baby_notes":"שבילים מרוצפים ומעט מדרגות, אפשר עם עגלה. קר מאוד בחורף.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Rokko%20Garden%20Terrace%20Kobe","website_url":"https://www.rokkosan.com/","serves":null,"dishes":[],"todo":"מסתובבים בין המרפסות עם הנוף, נכנסים לחנויות, ובשקיעה עומדים מול המפרץ ואוסקה.","special":"בימים בהירים רואים מכאן עד שדה התעופה קנסאי והאי אוואג׳י.","highlights":["מרפסות תצפית","נוף לשקיעה","חנויות ומסעדות בפסגה"],"time_needed":"שעה","kosher":null,"kosher_note":null,"address":"1877-9 Gotenyama, Rokkosancho, Nada-ku, Kobe","opens":null,"closes":null,"closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"evening","visit_mins":60,"booking":"no","plan_line":"להגיע לשקיעה ולבדוק מתי יוצא האוטובוס המעגלי האחרון","baby_block":null,"tags":["observation","view","sunset","mountain","shops","תצפית","נוף","שקיעה","הר","חנויות","rokko","רוקו","night view","נוף לילה","restaurants","מסעדות"],"en":{"hype":"A cluster of shops, restaurants and viewing terraces on top of Mt Rokko, with one of Kansai's widest views.","reality":"Free to enter and the view is great, especially at sunset. Restaurants and shops are touristy, but it's the handiest spot on the summit.","tip":"The loop bus from the top cable station gets you here. Buses thin out after sunset; check the last one.","baby_notes":"Paved paths and few steps, fine with a stroller. Very cold in winter.","price":"Free entry","serves":null,"dishes":[],"todo":"Wander between the viewing terraces, browse the shops, and at sunset face the bay and Osaka.","special":"On clear days you can see to Kansai Airport and Awaji Island.","highlights":["Viewing terraces","Sunset view","Summit shops and restaurants"],"time_needed":"1 hour","kosher_note":null,"plan_line":"Come for sunset and check the last loop bus time","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Rokko-Shidare Observatory","name_ja":"自然体感展望台 六甲枝垂れ","city":"kobe","area":"Nada & Rokko","category":"sight","lat":34.7695,"lng":135.2375,"coord_precision":"approx","hype":"מבנה תצפית בצורת עץ ענק מרשת עץ על ראש ההר, של האדריכל הירושי סמבוסוגי.","reality":"המבנה יפה לתמונה, אבל הנוף כמעט אותו נוף כמו מהמרפסות החינמיות של גן טראס שליד. ב-¥1,000 זה למי שאוהבים אדריכלות.","verdict":"overhyped","tabelog_score":null,"google_score":null,"price":"¥1,000 למבוגר","tip":"אפשר לצלם את המבנה מבחוץ מגן טראס בלי לשלם.","sources":["https://www.hyogo-tourism.jp/world/spot/detail_1029.html","https://www.rokkosan.com/"],"audience":"baby","baby_notes":"יש מדרגות למרפסת העליונה.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Rokko-Shidare%20Observatory%20Kobe","website_url":"https://www.rokkosan.com/","serves":null,"dishes":[],"todo":"נכנסים למרכז המבנה, מסתכלים למעלה דרך ה״ענפים״, ועולים למרפסת סביבו לנוף.","special":"המבנה עשוי רשת ברושים ומתוכנן לנשום עם הרוח והעונות.","highlights":["רשת העץ מבפנים","מרפסת התצפית","תאורה בערב"],"time_needed":"20 דקות","kosher":null,"kosher_note":null,"address":"1877-9 Gotenyama, Rokkosancho, Nada-ku, Kobe","opens":"10:00","closes":"20:30","closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"evening","visit_mins":20,"booking":"no","plan_line":"לצלם מבחוץ, הנוף מגן טראס החינמי כמעט זהה","baby_block":null,"tags":["observatory","architecture","view","wooden structure","design","תצפית","ארכיטקטורה","נוף","מבנה עץ","עיצוב","rokko","רוקו","sambuichi","night lights","תאורה"],"en":{"hype":"A viewing structure shaped like a giant tree of wooden lattice on the summit, by architect Hiroshi Sambuichi.","reality":"Pretty to photograph, but the view is nearly the same as from Garden Terrace's free terraces next door. At ¥1,000 it's for architecture fans.","tip":"You can photograph it from outside at Garden Terrace for free.","baby_notes":"Stairs up to the top terrace.","price":"¥1,000 adult","serves":null,"dishes":[],"todo":"Step into the centre, look up through the 'branches', and walk the terrace around it for the view.","special":"Made of a cypress lattice designed to breathe with the wind and the seasons.","highlights":["The lattice from inside","Viewing terrace","Evening lights"],"time_needed":"20 minutes","kosher_note":null,"plan_line":"Photo from outside; free Garden Terrace has nearly the same view","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"ROKKO Mori no Neiro Museum","name_ja":"ROKKO森の音ミュージアム","city":"kobe","area":"Nada & Rokko","category":"sight","lat":34.7715,"lng":135.242,"coord_precision":"approx","hype":"מוזיאון קופסאות נגינה ואורגני רחוב עתיקים ביער בפסגת רוקו (לשעבר מוזיאון קופסאות הנגינה), עם הופעות חיות של הכלים.","reality":"ההופעות של הכלים הגדולים מקסימות, אבל בלי הן זה מוזיאון קטן ויקר. בדצמבר יש קישוטי חג המולד ואירוע מיוחד.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"¥1,700 למבוגר, ¥850 לילד","tip":"לבדוק בכניסה את שעות ההופעה של הכלים, הן לב הביקור.","sources":["https://www.rokkosan.com/museum/operation/?lang=en","https://www.rokkosan.com/museum/?lang=en"],"audience":"baby","baby_notes":"מבנה נגיש ושקט, נעים עם תינוק, והמוזיקה עדינה.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=ROKKO%20Mori%20no%20Neiro%20Museum%20Kobe","website_url":"https://www.rokkosan.com/museum/?lang=en","serves":null,"dishes":[],"todo":"נכנסים לאולם ההופעות לשמוע את קופסאות הנגינה והאורגן הגדול, ואחר כך מסתובבים בגן היער ובקפה.","special":"אורגן ריקודים בלגי ענק וקופסאות נגינה מהמאה ה-19 שמנגנים בשבילכם.","highlights":["הופעות כלים חיות","האורגן הגדול","גן היער"],"time_needed":"שעה-שעה וחצי","kosher":null,"kosher_note":null,"address":"4750 Rokkosancho Kitarokko, Nada-ku, Kobe","opens":"10:00","closes":"17:00","closed_weekdays":[4],"closed_dates":[],"open_dates":[],"best_time":"midday","visit_mins":75,"booking":"no","plan_line":"סגור בימי חמישי מ-3 בדצמבר, חוץ מ-24 בדצמבר","baby_block":null,"tags":["museum","music box","organ","antique","christmas","מוזיאון","קופסת נגינה","אורגן","עתיקות","חג המולד","music","מוזיקה","rokko","רוקו","forest","יער"],"en":{"hype":"A museum of antique music boxes and street organs in the forest on top of Rokko (formerly the Music Box Museum), with live demonstrations.","reality":"The big instruments' performances are lovely, but without them it's a small pricey museum. In December there are Christmas decorations and an event.","tip":"Check the performance times at the entrance; they're the heart of the visit.","baby_notes":"Accessible and quiet, nice with a baby; the music is gentle.","price":"¥1,700 adult, ¥850 child","serves":null,"dishes":[],"todo":"Go into the performance hall to hear the music boxes and the big organ, then wander the forest garden and cafe.","special":"A huge Belgian dance organ and 19th-century music boxes played for you.","highlights":["Live instrument demos","The big organ","Forest garden"],"time_needed":"1-1.5 hours","kosher_note":null,"plan_line":"Closed Thursdays from 3 Dec, except 24 Dec","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Rokko Snow Park","name_ja":"六甲山スノーパーク","city":"kobe","area":"Nada & Rokko","category":"experience","lat":34.7745,"lng":135.235,"coord_precision":"approx","hype":"אתר שלג קטן עם שלג מלאכותי על הר רוקו, חצי שעה מהעיר, עם מגלשות שלג, סקי קטן ופארק שלג לילדים.","reality":"לא אתר סקי רציני, אבל המקום הכי קרוב לקובה ואוסקה לגעת בשלג. לילדים כיף, למבוגרים עם תינוק בעיקר לצילום.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":null,"tip":"העונה 2026-27 נפתחת ב-5 בדצמבר. אפשר לשכור בגדי שלג במקום.","sources":["https://www.haveagood-holiday.com/en/articles/rokko-snow-park-snow-making-2026-season","https://www.rokkosan.com/ski/"],"audience":"baby","baby_notes":"יש אזור משחק בשלג למשפחות וחדר מנוחה חם. קר מאוד לתינוק קטן.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Rokko%20Snow%20Park%20Kobe","website_url":"https://www.rokkosan.com/ski/","serves":null,"dishes":[],"todo":"שוכרים בגדים ומזחלות, משחקים באזור השלג או גולשים במגלשות, ונכנסים להתחמם בבית האוכל.","special":"שלג אמיתי שעה מאוסקה, בלי לנסוע לאלפים היפניים.","highlights":["מזחלות ומגלשות שלג","סקי וסנובורד למתחילים","אזור שלג לילדים"],"time_needed":"2-3 שעות","kosher":null,"kosher_note":null,"address":"Rokkosancho, Nada-ku, Kobe","opens":null,"closes":null,"closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"midday","visit_mins":150,"booking":"no","plan_line":"פתוח מ-5 בדצמבר, אפשר לשכור בגדי שלג במקום","baby_block":null,"tags":["snow","ski","sledding","snowboard","winter","שלג","סקי","מזחלות","סנובורד","חורף","kids","ילדים","snow play","משחקי שלג","rokko","רוקו"],"en":{"hype":"A small artificial-snow park on Mt Rokko, half an hour from the city, with snow slides, a little ski area and a kids' snow zone.","reality":"Not a serious ski area, but the closest place to Kobe and Osaka to touch snow. Fun for kids; with a baby, mostly for photos.","tip":"The 2026-27 season opens on 5 December. Snow clothes can be rented on site.","baby_notes":"There's a family snow play area and a warm rest room. Very cold for a small baby.","price":null,"serves":null,"dishes":[],"todo":"Rent clothes and sleds, play in the snow zone or ride the slides, then warm up in the food hall.","special":"Real snow an hour from Osaka without going to the Japanese Alps.","highlights":["Sleds and snow slides","Beginner ski and snowboard","Kids' snow zone"],"time_needed":"2-3 hours","kosher_note":null,"plan_line":"Open from 5 December; snow clothes for rent on site","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Rokkosan Pasture","name_ja":"六甲山牧場","city":"kobe","area":"Nada & Rokko","category":"experience","lat":34.779,"lng":135.227,"coord_precision":"approx","hype":"חוות הר עם כבשים חופשיות על הדשא, פרות, ארנבות וסוסי פוני, ומוצרי חלב טריים.","reality":"טוב למשפחות עם ילדים, הכבשים מסתובבות חופשי ממש לידכם. בחורף הדשא צהוב ופחות פעילויות, אבל זול יותר.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"¥400-600 למבוגר (זול יותר בחורף)","tip":"לנסות את הגלידה והגבינה שמייצרים בחווה.","sources":["https://www.hyogo-tourism.jp/world/spot/detail_1014.html","https://rokkosan.jp/english"],"audience":"baby","baby_notes":"שבילים רחבים, רובם סלולים. עגלה עוברת ברוב החווה.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Rokkosan%20Pasture%20Kobe","website_url":"https://rokkosan.jp/english","serves":null,"dishes":[],"todo":"מסתובבים בשטחי המרעה בין הכבשים, מלטפים ארנבות בפינת החי, ואוכלים גלידה או גבינה מהמחלבה.","special":"כבשים שמסתובבות חופשי בין המבקרים על צלע ההר.","highlights":["כבשים חופשיות","פינת ליטוף","גלידה מהחווה"],"time_needed":"שעה-שעתיים","kosher":null,"kosher_note":null,"address":"1-1 Nakaichirigayama, Rokkosancho, Nada-ku, Kobe","opens":"09:00","closes":"17:00","closed_weekdays":[2],"closed_dates":[],"open_dates":[],"best_time":"midday","visit_mins":90,"booking":"no","plan_line":"סגור בימי שלישי. האוטובוס המעגלי של רוקו עוצר בכניסה","baby_block":null,"tags":["farm","sheep","animals","petting zoo","ice cream","חווה","כבשים","חיות","פינת ליטוף","גלידה","cheese","גבינה","kids","ילדים","rokko","רוקו","family"],"en":{"hype":"A mountain farm with sheep roaming the grass, cows, rabbits and ponies, plus fresh dairy.","reality":"Good for families; the sheep wander right past you. In winter the grass is brown and there's less going on, but it's cheaper.","tip":"Try the ice cream and cheese made on the farm.","baby_notes":"Wide paths, mostly paved. A stroller handles most of the farm.","price":"¥400-600 adult (cheaper in winter)","serves":null,"dishes":[],"todo":"Walk the pastures among the sheep, pet rabbits in the petting area, and have ice cream or cheese from the dairy.","special":"Sheep roaming freely among visitors on the mountainside.","highlights":["Free-roaming sheep","Petting area","Farm ice cream"],"time_needed":"1-2 hours","kosher_note":null,"plan_line":"Closed Tuesdays. The Rokko loop bus stops at the gate","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Maya View Line & Kikuseidai","name_ja":"まやビューライン・掬星台","city":"kobe","area":"Nada & Rokko","category":"experience","lat":34.7315,"lng":135.2085,"coord_precision":"approx","hype":"רכבל על פסים ואחריו רכבל תלוי שעולים להר מאיה, לתצפית קיקוסייה-דאי, מנופי הלילה המפורסמים ביפן.","reality":"הנוף בלילה באמת מרשים ופחות עמוס מרוקו. הדרך לתחתית הרכבל באוטובוס ארוכה, ולמעלה אין כמעט כלום חוץ מהתצפית.","verdict":"gem","tabelog_score":null,"google_score":null,"price":null,"tip":"בלילה לבדוק מתי יורד הקרון האחרון, ולא להישאר בתצפית אחריו.","sources":["https://hyogo-tourism.jp/world/note/23","https://www.gltjp.com/en/directory/item/10732"],"audience":"baby","baby_notes":"שני קרונות ומעט מדרגות בתחנות. בפסגה חשוך, קר ורוחני.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Maya%20View%20Line%20%26%20Kikuseidai%20Kobe","website_url":"https://koberope.jp/maya/","serves":null,"dishes":[],"todo":"נוסעים באוטובוס 18 לתחנת הרכבל, עולים ברכבל ואחר כך ברכבל התלוי, ויוצאים לרחבת התצפית בפסגה. בשקיעה נשארים עד שהעיר נדלקת.","special":"השם קיקוסייה-דאי פירושו ״המקום שבו אוספים כוכבים ביד״, על נוף אורות העיר.","highlights":["נוף לילה על קובה ואוסקה","שני קרונות בדרך","שקיעה מעל המפרץ"],"time_needed":"שעתיים כולל הדרך","kosher":null,"kosher_note":null,"address":"Mayasancho, Nada-ku, Kobe","opens":null,"closes":null,"closed_weekdays":[2],"closed_dates":[],"open_dates":[],"best_time":"evening","visit_mins":120,"booking":"no","plan_line":"סגור בימי שלישי. לעלות לפני השקיעה ולבדוק את הקרון האחרון","baby_block":null,"tags":["night view","ropeway","cable car","observatory","mt maya","נוף לילה","רכבל","קרון","תצפית","הר מאיה","sunset","שקיעה","view","נוף","kikuseidai"],"en":{"hype":"A funicular then a ropeway up Mt Maya to Kikuseidai, one of Japan's famous night views.","reality":"The night view really is impressive and less crowded than Rokko. The bus to the bottom station is long, and up top there's little besides the view.","tip":"At night check the last car down and don't stay at the lookout past it.","baby_notes":"Two cars and a few steps at the stations. Dark, cold and windy up top.","price":null,"serves":null,"dishes":[],"todo":"Take bus 18 to the cable station, ride the funicular then the ropeway, and step out onto the summit lookout. At sunset stay until the city lights up.","special":"Kikuseidai means 'the place where you can scoop up stars', about the city lights.","highlights":["Night view over Kobe and Osaka","Two rides on the way","Sunset over the bay"],"time_needed":"2 hours with travel","kosher_note":null,"plan_line":"Closed Tuesdays. Go up before sunset; check the last car down","baby_block":null},"facts_at":"2026-11-09","facts_sure":true}]$cards$::jsonb) x
where not exists (select 1 from place_library p where p.city = x.city and lower(p.name) = lower(x.name));
insert into place_library (name, name_ja, city, area, category, lat, lng, coord_precision, hype, reality, verdict, tabelog_score, google_score, price, tip, sources, audience, baby_notes, local_pick, maps_url, website_url, serves, dishes, todo, special, highlights, time_needed, kosher, kosher_note, address, opens, closes, closed_weekdays, closed_dates, open_dates, best_time, visit_mins, booking, plan_line, baby_block, tags, en, facts_at, facts_sure, active)
select x.name, x.name_ja, x.city, x.area, x.category, x.lat, x.lng, x.coord_precision, x.hype, x.reality, x.verdict, x.tabelog_score, x.google_score, x.price, x.tip, x.sources, x.audience, x.baby_notes, x.local_pick, x.maps_url, x.website_url, x.serves, x.dishes, x.todo, x.special, x.highlights, x.time_needed, x.kosher, x.kosher_note, x.address, x.opens, x.closes, x.closed_weekdays, x.closed_dates, x.open_dates, x.best_time, x.visit_mins, x.booking, x.plan_line, x.baby_block, x.tags, x.en, x.facts_at, x.facts_sure, false from jsonb_populate_recordset(null::place_library, $cards$[{"name":"Hyogo Prefectural Museum of Art","name_ja":"兵庫県立美術館","city":"kobe","area":"Nada & Rokko","category":"sight","lat":34.6993,"lng":135.2185,"coord_precision":"approx","hype":"מוזיאון אמנות בבניין בטון גדול של טאדאו אנדו על הים, עם תערוכות מתחלפות גדולות.","reality":"הבניין עצמו שווה ביקור, עם מדרגות, חצרות ומרפסות לים. התצוגה הקבועה קטנה, והביקור תלוי בתערוכה שמוצגת.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"¥500 לתצוגה הקבועה, תערוכות מיוחדות במחיר נפרד","tip":"על המרפסת מול הים יש פסל תפוח ירוק ענק של אנדו, ואת החלקים הפתוחים של הבניין רואים גם בלי כרטיס.","sources":["https://www.japan-guide.com/e/e3562.html","https://www.artm.pref.hyogo.jp/"],"audience":"baby","baby_notes":"מעליות ומבנה נגיש, שקט ומרווח.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Hyogo%20Prefectural%20Museum%20of%20Art%20Kobe","website_url":"https://www.artm.pref.hyogo.jp/","serves":null,"dishes":[],"todo":"מסתובבים בחללי הבטון והמדרגות של אנדו, נכנסים לתערוכה, ויוצאים למרפסת מול הים.","special":"אחד הבניינים הגדולים של אנדו, שנבנה אחרי הרעידה כחלק משיקום העיר.","highlights":["האדריכלות של טאדאו אנדו","תערוכות מתחלפות","המרפסת מול הים"],"time_needed":"שעה וחצי","kosher":null,"kosher_note":null,"address":"1-1-1 Wakinohamakaigandori, Chuo-ku, Kobe","opens":"10:00","closes":"18:00","closed_weekdays":[1],"closed_dates":[],"open_dates":[],"best_time":"any","visit_mins":90,"booking":"no","plan_line":"סגור בימי שני. 10 דקות הליכה מתחנת האנשין איוואיה","baby_block":null,"tags":["art museum","museum","tadao ando","architecture","modern art","מוזיאון אמנות","מוזיאון","טאדאו אנדו","ארכיטקטורה","אמנות מודרנית","exhibition","תערוכה","sea","ים","rainy day","יום גשום"],"en":{"hype":"An art museum in Tadao Ando's big concrete building by the sea, with major rotating exhibitions.","reality":"The building itself is worth the visit, with stairways, courtyards and sea terraces. The permanent display is small; the visit depends on what's showing.","tip":"On the sea terrace there's Ando's giant green apple sculpture, and the open parts of the building can be seen without a ticket.","baby_notes":"Lifts and an accessible, quiet, spacious building.","price":"¥500 permanent display; special exhibitions extra","serves":null,"dishes":[],"todo":"Wander Ando's concrete spaces and stairways, see the exhibition, then step onto the sea terrace.","special":"One of Ando's largest buildings, built after the quake as part of the city's recovery.","highlights":["Tadao Ando architecture","Rotating exhibitions","Sea terrace"],"time_needed":"1.5 hours","kosher_note":null,"plan_line":"Closed Mondays; 10 min walk from Hanshin Iwaya Station","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Hakutsuru Sake Brewery Museum","name_ja":"白鶴酒造資料館","city":"kobe","area":"Nada & Rokko","category":"experience","lat":34.7135,"lng":135.2655,"coord_precision":"approx","hype":"מוזיאון הסאקה של אחת המבשלות הגדולות ביפן, במחסן עץ ישן עם בובות בגודל אמיתי שמראות איך בישלו סאקה פעם.","reality":"המוזיאון הכי טוב בנאדה, עם הסברים וסרטונים באנגלית, והכניסה חינם. בסוף טועמים בחנות, ושם רוב האנשים נשארים הכי הרבה זמן.","verdict":"gem","tabelog_score":null,"google_score":null,"price":"כניסה חינם, טעימות בחנות","tip":"5 דקות הליכה מתחנת האנשין סומיושי. מתחילים כאן ואז ממשיכים ברגל לקיקו-מסאמונה.","sources":["https://www.japan-guide.com/e/e3556.html","https://www.hakutsuru.co.jp/community/shiryokan/"],"audience":"baby","baby_notes":"בקומה השנייה מדרגות עץ תלולות. הקומה הראשונה והחנות נגישות.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Hakutsuru%20Sake%20Brewery%20Museum%20Kobe","website_url":"https://www.hakutsuru.co.jp/community/shiryokan/","serves":null,"dishes":[],"todo":"עוברים בין חביות העץ והבובות שמראות את שלבי הבישול, צופים בסרטון באנגלית, וטועמים כמה סוגי סאקה בחנות.","special":"מחסן בישול אמיתי מ-1920 שהפך למוזיאון.","highlights":["דגמים בגודל אמיתי","סרטון באנגלית","טעימות בחנות"],"time_needed":"45 דקות","kosher":null,"kosher_note":null,"address":"4-5-5 Sumiyoshiminamimachi, Higashinada-ku, Kobe","opens":"09:30","closes":"16:30","closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"midday","visit_mins":45,"booking":"no","plan_line":"להתחיל כאן את סיבוב הסאקה, 5 דקות מתחנת האנשין סומיושי","baby_block":null,"tags":["sake","brewery","museum","tasting","nada","סאקה","מבשלה","מוזיאון","טעימות","נאדה","rice wine","יין אורז","alcohol","אלכוהול","free","חינם","nihonshu"],"en":{"hype":"The sake museum of one of Japan's biggest brewers, in an old wooden brewhouse with life-size figures showing how sake was made.","reality":"The best museum in Nada, with English signs and videos, and free. You taste at the shop at the end, where most people linger longest.","tip":"5 min walk from Hanshin Sumiyoshi. Start here, then walk on to Kiku-Masamune.","baby_notes":"Steep wooden stairs to the upper floor. The ground floor and shop are accessible.","price":"Free entry; tasting at the shop","serves":null,"dishes":[],"todo":"Walk past the wooden vats and figures showing each brewing step, watch the English video, and taste a few sakes at the shop.","special":"A real 1920s brewhouse turned museum.","highlights":["Life-size models","English video","Shop tasting"],"time_needed":"45 minutes","kosher_note":null,"plan_line":"Start the sake walk here, 5 min from Hanshin Sumiyoshi","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Kiku-Masamune Sake Brewery Museum","name_ja":"菊正宗酒造記念館","city":"kobe","area":"Nada & Rokko","category":"experience","lat":34.7155,"lng":135.2615,"coord_precision":"approx","hype":"מוזיאון במבנה עץ של מבשלת קיקו-מסאמונה, עם כלי עבודה עתיקים ודלפק טעימות נדיב.","reality":"קטן מהאקוצורו, אבל הטעימות בחנות נדיבות וכוללות סאקה שקשה למצוא בחוץ. שווה לעשות את שניהם ביחד.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"כניסה וטעימות חינם","tip":"מול המוזיאון יש מפעל חביות עץ שאפשר לראות בהזמנה מראש באתר.","sources":["https://www.japan-guide.com/e/e3556.html","https://www.kikumasamune.co.jp/kinenkan/"],"audience":"baby","baby_notes":"קומה אחת עיקרית, נגיש ברובו.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Kiku-Masamune%20Sake%20Brewery%20Museum%20Kobe","website_url":"https://www.kikumasamune.co.jp/kinenkan/","serves":null,"dishes":[],"todo":"מסתכלים על הכלים והמכונות הישנים בתצוגה, טועמים כמה סוגים בדלפק, וקונים בקבוק בחנות.","special":"כלי הבישול כאן מוגדרים נכס תרבות של יפן.","highlights":["כלי עבודה עתיקים","דלפק טעימות","מפעל החביות"],"time_needed":"30-45 דקות","kosher":null,"kosher_note":null,"address":"1-9-1 Mikagehonmachi, Higashinada-ku, Kobe","opens":"09:30","closes":"16:30","closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"midday","visit_mins":40,"booking":"no","plan_line":"10 דקות הליכה מהאקוצורו, לעשות את שניהם ברצף","baby_block":null,"tags":["sake","brewery","museum","tasting","nada","סאקה","מבשלה","מוזיאון","טעימות","נאדה","barrel","חביות","rice wine","יין אורז","alcohol","אלכוהול","free","חינם"],"en":{"hype":"A museum in Kiku-Masamune's wooden brewhouse, with antique tools and a generous tasting counter.","reality":"Smaller than Hakutsuru, but the shop tasting is generous and includes sake that's hard to find elsewhere. Worth doing both together.","tip":"Across the road is a barrel workshop you can tour with an online booking.","baby_notes":"Mostly one floor, largely accessible.","price":"Free entry and tasting","serves":null,"dishes":[],"todo":"Look at the old tools and machines, taste several kinds at the counter, and buy a bottle at the shop.","special":"The brewing tools here are an Important Cultural Property.","highlights":["Antique tools","Tasting counter","Barrel workshop"],"time_needed":"30-45 minutes","kosher_note":null,"plan_line":"10 min walk from Hakutsuru; do both in a row","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Kobe Shushinkan Brewery","name_ja":"神戸酒心館","city":"kobe","area":"Nada & Rokko","category":"experience","lat":34.713,"lng":135.2575,"coord_precision":"approx","hype":"מבשלת ״פוקוג׳ו״, הסאקה שהוגש בארוחת פרס נובל, עם חנות, בר טעימות ומסעדה במבנה עץ יפה.","reality":"מקום נעים ומטופח עם טעימות טובות בתשלום קטן. סיורי המחסן לא מתקיימים בדצמבר, אז מגיעים בשביל הטעימות והחנות.","verdict":"gem","tabelog_score":null,"google_score":null,"price":"טעימות בתשלום, כמה מאות ין","tip":"בדצמבר אין סיורים, אבל בר הטעימות והחנות פתוחים כרגיל.","sources":["https://www.japan-guide.com/e/e3556.html","https://www.shushinkan.co.jp/"],"audience":"baby","baby_notes":"קומת קרקע נגישה, החנות מרווחת.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Kobe%20Shushinkan%20Brewery%20Kobe","website_url":"https://www.shushinkan.co.jp/","serves":null,"dishes":[],"todo":"טועמים כמה סוגי פוקוג׳ו בבר, קונים בקבוק או סאקה קאסו בחנות, ואפשר לאכול במסעדה שבמתחם.","special":"הסאקה של המבשלה הוגש בארוחה של טקס פרס נובל בשטוקהולם.","highlights":["בר טעימות","סאקה פוקוג׳ו","מבנה העץ"],"time_needed":"45 דקות","kosher":null,"kosher_note":null,"address":"1-8-17 Mikagetsukamachi, Higashinada-ku, Kobe","opens":"10:00","closes":"18:30","closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"afternoon","visit_mins":45,"booking":"no","plan_line":"בדצמבר אין סיורים, אבל בר הטעימות והחנות פתוחים","baby_block":null,"tags":["sake","brewery","tasting","fukuju","nada","סאקה","מבשלה","טעימות","פוקוג׳ו","נאדה","nobel","נובל","shop","חנות","rice wine","יין אורז","alcohol"],"en":{"hype":"The brewery behind Fukuju, the sake served at the Nobel Prize banquet, with a shop, tasting bar and restaurant in a lovely wooden building.","reality":"A pleasant, well-kept place with good tastings for a small fee. Warehouse tours don't run in December, so come for the tasting and shop.","tip":"No tours in December, but the tasting bar and shop are open as usual.","baby_notes":"Ground floor accessible; roomy shop.","price":"Paid tasting, a few hundred yen","serves":null,"dishes":[],"todo":"Taste several Fukuju sakes at the bar, buy a bottle or sake lees in the shop, and eat at the restaurant on site.","special":"Its sake was served at the Nobel Prize banquet in Stockholm.","highlights":["Tasting bar","Fukuju sake","Wooden building"],"time_needed":"45 minutes","kosher_note":null,"plan_line":"No tours in December, but the tasting bar and shop are open","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Sawanotsuru Sake Museum","name_ja":"沢の鶴資料館","city":"kobe","area":"Nada & Rokko","category":"experience","lat":34.7065,"lng":135.242,"coord_precision":"approx","hype":"מבשלה ישנה מתקופת אדו שהפכה למוזיאון, במערב נאדה, עם חלל בישול תת-קרקעי.","reality":"מוזיאון נאה וחינם, אבל רחוק מהשאר. שווה רק למי שעושים סיבוב סאקה מלא.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"חינם","tip":"סגור בימי רביעי. הכי קרוב לתחנת האנשין אוישי.","sources":["https://www.japan-guide.com/e/e3556.html","https://www.sawanotsuru.co.jp/"],"audience":"baby","baby_notes":"רוב התצוגה בקומה אחת.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Sawanotsuru%20Sake%20Museum%20Kobe","website_url":"https://www.sawanotsuru.co.jp/","serves":null,"dishes":[],"todo":"עוברים בין חביות העץ והכלים, יורדים לחלל התת-קרקעי, וטועמים בחנות.","special":"המבנה שוחזר אחרי שקרס ברעידה, ונשאר בו מרתף בישול מקורי.","highlights":["מרתף הבישול","חביות עץ","טעימה בחנות"],"time_needed":"30 דקות","kosher":null,"kosher_note":null,"address":"1-29-1 Oishiminamimachi, Nada-ku, Kobe","opens":"10:00","closes":"16:00","closed_weekdays":[3],"closed_dates":[],"open_dates":[],"best_time":"midday","visit_mins":30,"booking":"no","plan_line":"סגור בימי רביעי, רחוק משאר המבשלות","baby_block":null,"tags":["sake","brewery","museum","edo","nada","סאקה","מבשלה","מוזיאון","אדו","נאדה","tasting","טעימות","free","חינם","rice wine","יין אורז"],"en":{"hype":"An Edo-period brewhouse turned museum in western Nada, with an underground brewing space.","reality":"A nice free museum, but far from the others. Only worth it if you're doing a full sake walk.","tip":"Closed Wednesdays. Nearest is Hanshin Oishi Station.","baby_notes":"Most of the display is on one floor.","price":"Free","serves":null,"dishes":[],"todo":"Walk among the wooden vats and tools, go down to the underground space, and taste at the shop.","special":"Rebuilt after collapsing in the quake, keeping an original brewing cellar.","highlights":["Brewing cellar","Wooden vats","Shop tasting"],"time_needed":"30 minutes","kosher_note":null,"plan_line":"Closed Wednesdays; far from the other breweries","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Hamafukutsuru Ginjo Brewery","name_ja":"浜福鶴 吟醸工房","city":"kobe","area":"Nada & Rokko","category":"experience","lat":34.7158,"lng":135.2635,"coord_precision":"approx","hype":"מבשלה קטנה שבה רואים מבעד לחלונות את הבישול האמיתי, לא רק מוזיאון.","reality":"דצמבר הוא בדיוק עונת הבישול, אז רואים את הצוות עובד. קטן, ושווה כעצירה בין האקוצורו לקיקו-מסאמונה.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"חינם","tip":"סגור בימי שני. בחורף הבישול פעיל ורואים יותר.","sources":["https://www.japan-guide.com/e/e3556.html","https://www.hamafukutsuru.co.jp/"],"audience":"baby","baby_notes":"מסלול צפייה בקומה השנייה עם מדרגות.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Hamafukutsuru%20Ginjo%20Brewery%20Kobe","website_url":"https://www.hamafukutsuru.co.jp/","serves":null,"dishes":[],"todo":"עולים לקומה השנייה, מסתכלים מבעד לחלונות על מכונות הבישול והצוות, ויורדים לחנות.","special":"אחת המבשלות הבודדות בנאדה שבהן רואים בישול בזמן אמת.","highlights":["בישול בזמן אמת","הסברים באנגלית","חנות"],"time_needed":"30 דקות","kosher":null,"kosher_note":null,"address":"4-4-6 Uozakiminamimachi, Higashinada-ku, Kobe","opens":"10:00","closes":"17:00","closed_weekdays":[1],"closed_dates":[],"open_dates":[],"best_time":"midday","visit_mins":30,"booking":"no","plan_line":"סגור בימי שני. בדצמבר הבישול פעיל ורואים את העבודה","baby_block":null,"tags":["sake","brewery","ginjo","nada","tasting","סאקה","מבשלה","גינג׳ו","נאדה","טעימות","brewing","בישול","free","חינם","rice wine","יין אורז"],"en":{"hype":"A small brewery where you watch real brewing through windows, not just a museum.","reality":"December is brewing season, so you see the crew at work. Small, a good stop between Hakutsuru and Kiku-Masamune.","tip":"Closed Mondays. In winter brewing is running and there's more to see.","baby_notes":"Viewing route upstairs, reached by stairs.","price":"Free","serves":null,"dishes":[],"todo":"Go up to the second floor, watch the machines and crew through the windows, then down to the shop.","special":"One of the few Nada breweries where you watch brewing live.","highlights":["Live brewing","English info","Shop"],"time_needed":"30 minutes","kosher_note":null,"plan_line":"Closed Mondays. In December brewing is on and you see the work","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Sakuramasamune Sakuraen","name_ja":"櫻正宗記念館 櫻宴","city":"kobe","area":"Nada & Rokko","category":"experience","lat":34.7165,"lng":135.2705,"coord_precision":"approx","hype":"מבשלה ותיקה עם תצוגה קטנה, בר טעימות ומסעדה, פתוחה עד הערב.","reality":"התצוגה קטנה ומעט אנגלית, אבל זו המבשלה היחידה בנאדה שפתוחה עד 19:00, טובה לסיים בה את היום.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"כניסה חינם, טעימות בתשלום","tip":"סגור בימי שלישי. מסיימים כאן כי שאר המבשלות נסגרות ב-16:30.","sources":["https://www.japan-guide.com/e/e3556.html","https://www.sakuramasamune.co.jp/"],"audience":"baby","baby_notes":"קומת קרקע נגישה.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Sakuramasamune%20Sakuraen%20Kobe","website_url":"https://www.sakuramasamune.co.jp/","serves":null,"dishes":[],"todo":"מסתכלים על התצוגה הקטנה והסרטון, טועמים בבר וקונים בקבוק.","special":"המבשלה הראשונה שגילתה את מי ״מיאמיזו״ של נאדה, שהפכו את האזור לבירת הסאקה.","highlights":["בר טעימות","תצוגה היסטורית","פתוח עד הערב"],"time_needed":"30-45 דקות","kosher":null,"kosher_note":null,"address":"5-10-1 Uozakiminamimachi, Higashinada-ku, Kobe","opens":"10:00","closes":"19:00","closed_weekdays":[2],"closed_dates":[],"open_dates":[],"best_time":"afternoon","visit_mins":40,"booking":"no","plan_line":"פתוח עד 19:00, לסיים כאן את סיבוב הסאקה. סגור בשלישי","baby_block":null,"tags":["sake","brewery","tasting","miyamizu","nada","סאקה","מבשלה","טעימות","נאדה","restaurant","מסעדה","history","היסטוריה","rice wine","יין אורז","alcohol"],"en":{"hype":"An old brewery with a small exhibit, tasting bar and restaurant, open into the evening.","reality":"The exhibit is small with little English, but it's the only Nada brewery open until 19:00, good to end the day.","tip":"Closed Tuesdays. Finish here since the others close at 16:30.","baby_notes":"Ground floor accessible.","price":"Free entry; paid tasting","serves":null,"dishes":[],"todo":"Look at the small exhibit and video, taste at the bar and buy a bottle.","special":"The brewery that first found Nada's Miyamizu water, which made the area Japan's sake capital.","highlights":["Tasting bar","History exhibit","Open into the evening"],"time_needed":"30-45 minutes","kosher_note":null,"plan_line":"Open until 19:00; end the sake walk here. Closed Tuesdays","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Kobe Konan Muko no Sato","name_ja":"神戸・甲南 武庫の郷","city":"kobe","area":"Nada & Rokko","category":"shopping","lat":34.712,"lng":135.259,"coord_precision":"approx","hype":"מתחם על כבישת ירקות ביפנית (נארה-זוקה בסאקה קאסו), עם מוזיאון קטן וחנות אוכל גדולה.","reality":"חנות טובה למזכרות אוכל יפניות שלא רואים בכל מקום. המוזיאון קטן, אבל הטעימות בחנות נדיבות.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"כבושים מ-¥500 בערך","tip":"סגור בימי שישי. אפשר לטעום הרבה סוגי כבושים לפני שקונים.","sources":["https://www.japan-guide.com/e/e3556.html","https://hanshin.co.jp/global/en/nada/otherbreweries"],"audience":"baby","baby_notes":"מבנה נגיש ומרווח.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Kobe%20Konan%20Muko%20no%20Sato%20Kobe","website_url":null,"serves":null,"dishes":[],"todo":"טועמים כבושים בשאריות הסאקה בחנות, מציצים למוזיאון הכבישה, ואפשר לאכול במסעדות שבמקום.","special":"נארה-זוקה, ירקות שמשרים חודשים בשאריות התסיסה של הסאקה.","highlights":["כבושי נארה-זוקה","טעימות בחנות","מוזיאון כבישה"],"time_needed":"30 דקות","kosher":null,"kosher_note":null,"address":"4-4-8 Mikagetsukamachi, Higashinada-ku, Kobe","opens":"09:30","closes":"18:30","closed_weekdays":[5],"closed_dates":["2026-12-29","2026-12-30","2026-12-31"],"open_dates":[],"best_time":"midday","visit_mins":30,"booking":"no","plan_line":"סגור בימי שישי ומ-29 בדצמבר. לטעום לפני שקונים","baby_block":null,"tags":["pickles","tsukemono","narazuke","sake lees","food shop","כבושים","חמוצים","צוקמונו","נארה-זוקה","סאקה קאסו","חנות אוכל","souvenirs","מזכרות","japanese food","אוכל יפני"],"en":{"hype":"A complex about Japanese pickling (narazuke in sake lees), with a small museum and a big food shop.","reality":"A good shop for Japanese food souvenirs you don't see everywhere. The museum is small, but the shop tasting is generous.","tip":"Closed Fridays. You can taste many pickles before buying.","baby_notes":"Accessible, roomy building.","price":"Pickles from about ¥500","serves":null,"dishes":[],"todo":"Taste sake-lees pickles in the shop, peek into the pickling museum, and eat at the restaurants on site.","special":"Narazuke: vegetables steeped for months in the lees left from brewing sake.","highlights":["Narazuke pickles","Shop tasting","Pickling museum"],"time_needed":"30 minutes","kosher_note":null,"plan_line":"Closed Fridays and from 29 Dec. Taste before buying","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Kobe Nunobiki Herb Gardens & Ropeway","name_ja":"神戸布引ハーブ園／ロープウェイ","city":"kobe","area":"Kitano","category":"experience","lat":34.7065,"lng":135.1975,"coord_precision":"approx","hype":"רכבל מתחנת שין-קובה לגן צמחי תבלין ופרחים על ההר, עם נוף לעיר ולנמל.","reality":"הרכבל והנוף הם העיקר. בדצמבר הגן עצמו חשוף, אבל יש שוק חג מולד, קישוטים ושעות ערב בחלק מהימים, וזה הופך אותו לשווה.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"¥2,500 הלוך חזור כולל הגן, מחיר גבוה יותר בעונת חג המולד","tip":"אפשר לעלות ברכבל ולרדת ברגל דרך מפל נונוביקי, ירידה של כ-40 דקות.","sources":["https://www.japan-guide.com/e/e3563.html","https://www.hyogo-tourism.jp/world/spot/detail_1016.html"],"audience":"baby","baby_notes":"הרכבל לוקח עגלה, אבל הגן על מדרון עם עליות. מעלית בתחנה העליונה.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Kobe%20Nunobiki%20Herb%20Gardens%20%26%20Ropeway%20Kobe","website_url":"https://www.kobeherb.com/","serves":null,"dishes":[],"todo":"עולים 10 דקות ברכבל מעל היער, מסתובבים במרפסת התצפית ובבתי הזכוכית, ויורדים לאט דרך הגן לתחנת האמצע.","special":"בעונת חג המולד, עד 25 בדצמבר, יש שוק חג מולד אירופאי ותאורה על ההר.","highlights":["רכבל עם נוף לנמל","שוק חג המולד","בתי הזכוכית"],"time_needed":"שעתיים","kosher":null,"kosher_note":null,"address":"1-4-3 Kitanocho, Chuo-ku, Kobe","opens":"09:30","closes":"17:15","closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"afternoon","visit_mins":120,"booking":"no","plan_line":"לעלות ברכבל ולרדת ברגל דרך מפל נונוביקי","baby_block":null,"tags":["ropeway","herb garden","garden","view","christmas market","רכבל","גן צמחים","גן","נוף","שוק חג המולד","flowers","פרחים","greenhouse","חממה","shin-kobe","christmas"],"en":{"hype":"A ropeway from Shin-Kobe Station up to a herb and flower garden on the mountain, with views of the city and port.","reality":"The ropeway and view are the main thing. In December the garden is bare, but there's a Christmas market, decorations and evening hours on some days, which makes it worth it.","tip":"Ride up and walk down via Nunobiki Falls, about 40 minutes.","baby_notes":"The ropeway takes strollers, but the garden is on a slope. Lift at the top station.","price":"¥2,500 return including the garden; higher in Christmas season","serves":null,"dishes":[],"todo":"Ride 10 minutes up over the forest, take in the viewing terrace and glasshouses, then stroll down through the garden to the middle station.","special":"In the Christmas season, until 25 December, there's a European-style Christmas market and lights on the mountain.","highlights":["Ropeway with port view","Christmas market","Glasshouses"],"time_needed":"2 hours","kosher_note":null,"plan_line":"Ride up, then walk down past Nunobiki Falls","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Disaster Reduction and Human Renovation Institution","name_ja":"人と防災未来センター","city":"kobe","area":"Nada & Rokko","category":"sight","lat":34.699,"lng":135.2175,"coord_precision":"approx","hype":"מוזיאון רעידת האדמה של קובה מ-1995, עם סרט שמשחזר את הרגעים של הרעידה ותערוכה על השיקום.","reality":"קשה ומרגש, ומסביר טוב מה העיר עברה. הסרט בתחילת הביקור חזק מאוד ועלול להבהיל ילדים קטנים ותינוקות.","verdict":"gem","tabelog_score":null,"google_score":null,"price":"¥600","tip":"מתחילים בקומה הרביעית עם הסרט ויורדים למטה. לשלב עם מוזיאון האמנות של המחוז שליד.","sources":["https://www.japan-guide.com/e/e3555.html","https://www.dri.ne.jp/"],"audience":"adults","baby_notes":"מבנה נגיש עם מעליות, אבל הסרט רועש ומפחיד.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Disaster%20Reduction%20and%20Human%20Renovation%20Institution%20Kobe","website_url":"https://www.dri.ne.jp/","serves":null,"dishes":[],"todo":"צופים בסרט על המסך הענק שמשחזר את הרעידה, עוברים לסרט התיעודי על השיקום, ויורדים לתצוגות ולמשחקי מניעת אסונות.","special":"שחזור של רחוב הרוס בגודל אמיתי ועדויות של ניצולים.","highlights":["סרט הרעידה על מסך ענק","שחזור רחוב הרוס","עדויות ניצולים"],"time_needed":"שעה וחצי","kosher":null,"kosher_note":null,"address":"1-5-2 Wakinohamakaigandori, Chuo-ku, Kobe","opens":"09:30","closes":"17:30","closed_weekdays":[1],"closed_dates":["2026-12-31"],"open_dates":[],"best_time":"any","visit_mins":90,"booking":"no","plan_line":"סגור בימי שני. הסרט בהתחלה רועש ומפחיד לילדים","baby_block":"סרט רועש ומפחיד בתחילת הביקור","tags":["museum","earthquake","disaster","history","1995","מוזיאון","רעידת אדמה","אסון","היסטוריה","hanshin","memorial","זיכרון","rainy day","יום גשום","documentary","סרט"],"en":{"hype":"Kobe's museum of the 1995 earthquake, with a film recreating the moment it hit and an exhibit on the recovery.","reality":"Hard and moving, and it explains well what the city went through. The opening film is very intense and can frighten young kids and babies.","tip":"Start on the fourth floor with the film and work down. Pair it with the prefectural art museum next door.","baby_notes":"Accessible with lifts, but the film is loud and scary.","price":"¥600","serves":null,"dishes":[],"todo":"Watch the giant-screen film recreating the quake, then the documentary on recovery, then head down to the exhibits and disaster prevention games.","special":"A life-size recreation of a destroyed street and survivor testimonies.","highlights":["Giant-screen quake film","Destroyed street recreation","Survivor testimonies"],"time_needed":"1.5 hours","kosher_note":null,"plan_line":"Closed Mondays. The opening film is loud and scary for kids","baby_block":"Loud, frightening film at the start"},"facts_at":"2026-11-09","facts_sure":true},{"name":"Kobe Oji Zoo","name_ja":"神戸市立王子動物園","city":"kobe","area":"Nada & Rokko","category":"sight","lat":34.7105,"lng":135.2135,"coord_precision":"approx","hype":"גן החיות העירוני של קובה, זול ונוח, עם פילים, ג׳ירפות, קואלות ופינת ליטוף.","reality":"גן חיות ישן וקטן יחסית, אבל זול וקרוב לתחנה. לילדים זה בוקר טוב, למבוגרים בלי ילדים פחות.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"¥600 למבוגר, ילדים עד גיל חטיבה חינם","tip":"סגור בימי רביעי. 3 דקות הליכה מתחנת האנקיו אוג׳י-קואן.","sources":["https://www.kobe-ojizoo.jp/","https://www.feel-kobe.jp/en/"],"audience":"baby","baby_notes":"שבילים סלולים ושטוחים, שירותים וחדר הנקה, נוח מאוד לעגלה.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Kobe%20Oji%20Zoo%20Kobe","website_url":"https://www.kobe-ojizoo.jp/","serves":null,"dishes":[],"todo":"מסתובבים בין המתחמים של הפילים, הג׳ירפות והקואלות, עוצרים בפינת הליטוף, ומבקרים בבית הנטר ההיסטורי בתוך הגן.","special":"בתוך הגן עומד בית האנטר, בית סוחר מערבי ישן שהועבר לכאן מהעיר.","highlights":["קואלות","פילים וג׳ירפות","בית האנטר ההיסטורי"],"time_needed":"שעתיים","kosher":null,"kosher_note":null,"address":"3-1 Ojicho, Nada-ku, Kobe","opens":"09:00","closes":"16:30","closed_weekdays":[3],"closed_dates":[],"open_dates":[],"best_time":"morning","visit_mins":120,"booking":"no","plan_line":"סגור בימי רביעי. 3 דקות מתחנת האנקיו אוג׳י-קואן","baby_block":null,"tags":["zoo","animals","koala","elephant","giraffe","גן חיות","חיות","קואלה","פיל","ג׳ירפה","petting zoo","פינת ליטוף","kids","ילדים","family","משפחה"],"en":{"hype":"Kobe's city zoo: cheap and easy, with elephants, giraffes, koalas and a petting corner.","reality":"An old, fairly small zoo, but cheap and close to the station. A good morning with kids, less so for adults alone.","tip":"Closed Wednesdays. 3 min walk from Hankyu Oji-koen Station.","baby_notes":"Flat paved paths, toilets and a nursing room, very easy with a stroller.","price":"¥600 adult; kids up to middle school free","serves":null,"dishes":[],"todo":"Walk between the elephants, giraffes and koalas, stop at the petting corner, and visit the historic Hunter House inside the zoo.","special":"Inside the zoo stands Hunter House, an old Western merchant's home moved here from the city.","highlights":["Koalas","Elephants and giraffes","Historic Hunter House"],"time_needed":"2 hours","kosher_note":null,"plan_line":"Closed Wednesdays. 3 min from Hankyu Oji-koen Station","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Yokoo Tadanori Museum of Contemporary Art","name_ja":"横尾忠則現代美術館","city":"kobe","area":"Nada & Rokko","category":"sight","lat":34.71,"lng":135.215,"coord_precision":"approx","hype":"מוזיאון של טדנורי יוקואו, אמן הפוסטרים והפופ-ארט היפני הצבעוני והפרוע, ליד גן החיות אוג׳י.","reality":"למי שמכירים או אוהבים גרפיקה ופופ-ארט זה מעולה. מוזיאון קטן, והכל תלוי בתערוכה שמוצגת.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":null,"tip":"לשלב עם גן החיות אוג׳י שממול באותו בוקר.","sources":["https://ytmoca.jp/","https://www.feel-kobe.jp/en/"],"audience":"baby","baby_notes":"מעליות ומבנה נגיש.","local_pick":true,"maps_url":"https://www.google.com/maps/search/?api=1&query=Yokoo%20Tadanori%20Museum%20of%20Contemporary%20Art%20Kobe","website_url":"https://ytmoca.jp/","serves":null,"dishes":[],"todo":"עוברים בין שתי קומות התערוכה עם הפוסטרים והציורים הגדולים, ומציצים לארכיון של האמן בקומה העליונה.","special":"יוקואו, יליד המחוז, עיצב פוסטרים אייקוניים לתיאטרון ולמוזיקה בשנות ה-60.","highlights":["פוסטרים צבעוניים","ציורים גדולים","ארכיון האמן"],"time_needed":"שעה","kosher":null,"kosher_note":null,"address":"3-8-30 Haradadori, Nada-ku, Kobe","opens":"10:00","closes":"18:00","closed_weekdays":[1],"closed_dates":[],"open_dates":[],"best_time":"any","visit_mins":60,"bookin