select x.name, x.name_ja, x.city, x.area, x.category, x.lat, x.lng, x.coord_precision, x.hype, x.reality, x.verdict, x.tabelog_score, x.google_score, x.price, x.tip, x.sources, x.audience, x.baby_notes, x.local_pick, x.maps_url, x.website_url, x.serves, x.dishes, x.todo, x.special, x.highlights, x.time_needed, x.kosher, x.kosher_note, x.address, x.opens, x.closes, x.closed_weekdays, x.closed_dates, x.open_dates, x.best_time, x.visit_mins, x.booking, x.plan_line, x.baby_block, x.tags, x.en, x.facts_at, x.facts_sure, false from jsonb_populate_recordset(null::place_library, $cards$[{"name":"Misen Imaike Honten","name_ja":"中国台湾料理 味仙 今池本店","city":"nagoya","area":"Castle & Higashi","category":"food","lat":35.167915,"lng":136.935881,"coord_precision":"exact","hype":"המקום שבו נולד טאיוואן ראמן, ראמן חריף עם בשר טחון, צ׳ילי ושום.","reality":"חריף באמת ומשאיר ריח שום ליום, אבל זה אחד המאכלים הכי מזוהים עם נגויה. פתוח עד 1 בלילה.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"מ-¥1,000","tip":"להזמין 'אמריקן' לגרסה מתונה, או 'איטליאן' לפי שניים צ׳ילי.","sources":["https://www.gltjp.com/en/directory/item/11889/","https://www.gltjp.com/en/article/item/20952/"],"audience":"adults","baby_notes":null,"local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Misen%20Imaike%20Honten%20Nagoya","website_url":"http://www.misen.ne.jp/","serves":"טאיוואן ראמן בציר עוף עם בשר חזיר טחון מוקפץ בצ׳ילי ושום, ירקות מוקפצים, כנפיים וצ׳ימאקי.","dishes":["טאיוואן ראמן","ירקות ירוקים מוקפצים","כנפיים"],"todo":null,"special":null,"highlights":[],"time_needed":null,"kosher":"hard","kosher_note":"הבשר בראמן חזיר. יש ירקות מוקפצים וכנפיים.","address":"1-12-10 Imaike, Chikusa-ku, Nagoya","opens":"17:00","closes":"01:00","closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"night","visit_mins":50,"booking":"no","plan_line":"רק ערב, 17:00-01:00; תחנת אימאיקה","baby_block":null,"tags":["taiwan ramen","ramen","spicy","chili","garlic","late night","chinese","noodles","טאיוואן ראמן","ראמן","חריף","צ׳ילי","שום","לילה","סיני","אטריות"],"en":{"hype":"Where Taiwan ramen was born: spicy ramen with minced meat, chili and garlic.","reality":"Properly hot and you'll smell of garlic all day, but it's one of the most Nagoya dishes there is. Open until 1am.","tip":"Order 'American' for milder, or 'Italian' for double chili.","baby_notes":null,"price":"From ¥1,000","serves":"Taiwan ramen in chicken broth with minced pork stir-fried in chili and garlic, greens, wings and chimaki.","dishes":["Taiwan ramen","Stir-fried greens","Chicken wings"],"todo":null,"special":null,"highlights":[],"time_needed":null,"kosher_note":"The ramen meat is pork. Greens and wings are options.","plan_line":"Evenings only, 17:00-01:00; Imaike station","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Kadomaru","name_ja":"角丸","city":"nagoya","area":"Castle & Higashi","category":"food","lat":35.176396,"lng":136.911307,"coord_precision":"approx","hype":"מיסו ניקומי אודון במקום שכונתי בהיגאשי, ברשימת 100 האודון של Tabelog.","reality":"המיסו ניקומי שמקומיים בוחרים, בלי התור של הרשתות. שעות קצרות, סגור בערבי חמישי ושבת.","verdict":"gem","tabelog_score":3.6,"google_score":null,"price":"¥1,000-2,000","tip":"להגיע בצהריים, בערב פתוח רק עד 19:00.","sources":["https://tabelog.com/en/aichi/A2301/A230103/23000031/"],"audience":"baby","baby_notes":"ידידותי לילדים, אסור לעשן.","local_pick":true,"maps_url":"https://www.google.com/maps/search/?api=1&query=Kadomaru%20Nagoya","website_url":null,"serves":"מיסו ניקומי אודון בסיר חרס.","dishes":["מיסו ניקומי אודון"],"todo":null,"special":null,"highlights":[],"time_needed":null,"kosher":"options","kosher_note":"לבחור תוספת ביצה או עוף.","address":"1-18-33 Izumi, Higashi-ku, Nagoya","opens":"11:00","closes":"19:00","closed_weekdays":[0],"closed_dates":[],"open_dates":[],"best_time":"midday","visit_mins":45,"booking":"no","plan_line":"סגור בראשון ובחגים; בשבת רק עד 14:00","baby_block":null,"tags":["mis