select x.name, x.name_ja, x.city, x.area, x.category, x.lat, x.lng, x.coord_precision, x.hype, x.reality, x.verdict, x.tabelog_score, x.google_score, x.price, x.tip, x.sources, x.audience, x.baby_notes, x.local_pick, x.maps_url, x.website_url, x.serves, x.dishes, x.todo, x.special, x.highlights, x.time_needed, x.kosher, x.kosher_note, x.address, x.opens, x.closes, x.closed_weekdays, x.closed_dates, x.open_dates, x.best_time, x.visit_mins, x.booking, x.plan_line, x.baby_block, x.tags, x.en, x.facts_at, x.facts_sure, false from jsonb_populate_recordset(null::place_library, $cards$[{"name":"Okazaki Castle","name_ja":"岡崎城","city":"nagoya","area":"Around Nagoya","category":"sight","lat":34.9561,"lng":137.1594,"coord_precision":"approx","hype":"הטירה שבה נולד טוקוגאווה אייאסו, מייסד השושגונות, בפארק על נהר יאהאגי.","reality":"המגדל שוחזר בבטון והתצוגה בפנים צנועה. שווה רק כשילוב עם מפעל המיסו הסמוך, ולא כטיול בפני עצמו.","verdict":"overhyped","tabelog_score":null,"google_score":null,"price":null,"tip":"בפארק מסביב יש בדרך כלל מופעי שחקנים בתחפושות סמוראים בסופי שבוע.","sources":["https://okazaki-kanko.jp/"],"audience":"baby","baby_notes":"הפארק שטוח; בתוך המגדל מדרגות.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Okazaki%20Castle%20Okazaki%20Aichi","website_url":"https://okazaki-kanko.jp/","serves":null,"dishes":[],"todo":"מטיילים בפארק סביב החפיר, עולים למגדל לתצוגה על אייאסו ולתצפית, וממשיכים ברגל עשר דקות למפעל המיסו האצ׳ו.","special":null,"highlights":["הפארק והחפיר","תצוגת אייאסו","התצפית"],"time_needed":"כשעה","kosher":null,"kosher_note":null,"address":"561-1 Koseicho, Okazaki, Aichi","opens":"09:00","closes":"17:00","closed_weekdays":[],"closed_dates":["2026-12-29","2026-12-30","2026-12-31"],"open_dates":[],"best_time":"morning","visit_mins":60,"booking":"no","plan_line":"משלבים עם סיור במפעל המיסו קאקוקיו, עשר דקות הליכה","baby_block":null,"tags":["castle","tokugawa","ieyasu","samurai","park","history","moat","טירה","טוקוגאווה","אייאסו","סמוראים","פארק","היסטוריה","חפיר","okazaki","אוקאזאקי"],"en":{"hype":"The castle where Tokugawa Ieyasu, founder of the shogunate, was born, in a park by the Yahagi River.","reality":"The keep is a concrete rebuild with a modest display inside. Only worth it combined with the nearby miso brewery, not as a trip on its own.","tip":"The surrounding park usually has costumed samurai performers on weekends.","baby_notes":"The park is flat; stairs inside the keep.","price":null,"serves":null,"dishes":[],"todo":"Walk the park around the moat, climb the keep for the Ieyasu display and the view, then walk ten minutes to the Hatcho miso brewery.","special":null,"highlights":["Park and moat","Ieyasu display","The view"],"time_needed":"About an hour","kosher_note":null,"plan_line":"Pair it with the Kakukyu miso tour, a 10-minute walk away","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Ghibli Park","name_ja":"ジブリパーク","city":"nagoya","area":"Around Nagoya","category":"experience","lat":35.174,"lng":137.091,"coord_precision":"approx","hype":"פארק סטודיו ג׳יבלי בתוך פארק האקספו בנגאקוטה: הבית מטוטורו, עמק המכשפות של קיקי והמחסן הגדול עם תפאורות מהסרטים.","reality":"זה לא פארק שעשועים בלי מתקנים: הולכים בין תפאורות בגודל אמיתי בתוך פארק ענק. לאוהבי ג׳יבלי זה מרגש מאוד, לאחרים זה הרבה הליכה בשביל צילומים.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"כ-¥3,500-7,300 לפי סוג הכרטיס","tip":"כרטיסים נפתחים ב-10 לחודש, חודשיים מראש, ונגמרים מהר. בלי כרטיס מראש לא נכנסים.","sources":["https://ghibli-park.jp/en/","https://www.trvlogue.com/en/nagoya-ghibli-park-tickets-guide"],"audience":"baby","baby_notes":"שבילים סלולים בפארק עם עליות; בתוך הבתים חולצים נעליים ועגלות לא נכנסות, צריך מנשא.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Ghibli%20Park%20Nagakute%20Aichi","website_url":"https://ghibli-park.jp/en/","serves":null,"dishes":[],"todo":"מתחילים במחסן הגדול עם התפאורות והתערוכות, עוברים לעמק המכשפות ולבית של סאטסוקי ומיי מטוטורו, והולכים ברגל בין האזורים בתוך הפארק.","special":"הכול נבנה בקנה מידה אמיתי ובפרטים של הסרטים, עד הסירים במטבח.","highlights":["המחסן הגדול","עמק המכשפות","הבית של טוטורו","גבעת הנעורים"],"time_needed":"יום שלם","kosher":null,"kosher_note":null,"address":"1533-1 Ibaragabasama, Nagakute, Aichi","opens":"10:00","closes":"17:00","closed_weekdays":[2],"closed_dates":[],"open_dates":[],"best_time":"morning","visit_mins":360,"booking":"required","plan_line":"חובה כרטיס מראש; נפתחים ב-10 לחודש, חודשיים לפני","baby_block":"בבתים אין עגלות, רק מנשא","tags":["ghibli","totoro","kiki","spirited away","anime","theme park","studio ghibli","ג׳יבלי","טוטורו","קיקי","המסע המופלא","אנימה","פארק","סטודיו ג׳יבלי","miyazaki","מיאזאקי","movies","סרטים"],"en":{"hype":"The Studio Ghibli park inside the Expo park in Nagakute: Totoro's house, Kiki's Valley of Witches and the Grand Warehouse full of film sets.","reality":"It is not a ride park: you walk between life-size sets inside a huge park. Ghibli fans are thrilled; others find it a lot of walking for photos.","tip":"Tickets go on sale on the 10th, two months ahead, and sell out fast. No ticket, no entry.","baby_notes":"Paved paths with slopes; shoes off inside the houses and no strollers, bring a carrier.","price":"About ¥3,500-7,300 depending on ticket","serves":null,"dishes":[],"todo":"Start at the Grand Warehouse with its sets and exhibits, move on to the Valley of Witches and Satsuki and Mei's house from Totoro, walking between areas through the park.","special":"Everything is built life size with the films' details, down to the pots in the kitchen.","highlights":["Grand Warehouse","Valley of Witches","Totoro's house","Hill of Youth"],"time_needed":"Full day","kosher_note":null,"plan_line":"Tickets required; sales open on the 10th, two months ahead","baby_block":"No strollers in the houses, carrier only"},"facts_at":"2026-11-09","facts_sure":true},{"name":"Linimo","name_ja":"リニモ","city":"nagoya","area":"Around Nagoya","category":"experience","lat":35.1825,"lng":137.0218,"coord_precision":"approx","hype":"הרכבת המגנטית המסחרית היחידה ביפן, שמרחפת בלי גלגלים מתחנת פוג׳יגאוקה לפארק ג׳יבלי.","reality":"נסיעה רגילה ושקטה מאוד, לא משהו מסעיר, אבל זו הדרך לג׳יבלי ממילא. נחמד לשבת מקדימה ליד החלון של הנהג האוטומטי.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"כמה מאות ין לנסיעה","tip":"הרכבת אוטומטית בלי נהג, אז המושבים מקדימה נותנים נוף ישיר למסילה.","sources":["https://linimo.pref.aichi.jp/en/spot"],"audience":"baby","baby_notes":"תחנות עם מעליות, נוח לעגלה.","local_pick":true,"maps_url":"https://www.google.com/maps/search/?api=1&query=Fujigaoka%20Station%20Linimo%20Nagoya","website_url":"https://www.linimo.jp/","serves":null,"dishes":[],"todo":"עוברים מקו היגאשיאמה בתחנת פוג׳יגאוקה, תופסים מקום מקדימה ונוסעים לתחנת איי צ׳יקיוהאקו קינן קואן של ג׳יבלי.","special":"רכבת מגלב בריחוף מגנטי, בלי מגע עם המסילה.","highlights":["ריחוף מגנטי","מושבים מקדימה","נוף לגבעות"],"time_needed":"כרבע שעה","kosher":null,"kosher_note":null,"address":"Fujigaoka Station, Meito-ku, Nagoya","opens":null,"closes":null,"closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"any","visit_mins":15,"booking":"no","plan_line":"לשבת בקרון הראשון לנוף ישר על המסילה","baby_block":null,"tags":["maglev","train","monorail","transport","ghibli","ride","מגלב","רכבת","רכבת מגנטית","תחבורה","ג׳יבלי","נסיעה","levitation","ריחוף"],"en":{"hype":"Japan's only commercial maglev, floating without wheels from Fujigaoka Station to Ghibli Park.","reality":"A normal, very quiet ride, not a thrill, but it is the way to Ghibli anyway. Nice to sit up front where a driver would be.","tip":"It is driverless, so the front seats look straight down the track.","baby_notes":"Stations have lifts, easy with a stroller.","price":"A few hundred yen per ride","serves":null,"dishes":[],"todo":"Change from the Higashiyama line at Fujigaoka, grab a front seat and ride to Ai Chikyuhaku Kinen Koen for Ghibli.","special":"A magnetic-levitation train that never touches the track.","highlights":["Magnetic levitation","Front seats","Hill views"],"time_needed":"About 15 minutes","kosher_note":null,"plan_line":"Sit in the first car for a straight view down the track","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Nagashima Spa Land","name_ja":"ナガシマスパーランド","city":"nagoya","area":"Around Nagoya","category":"experience","lat":35.031,"lng":136.733,"coord_precision":"approx","hype":"פארק שעשועים גדול עם רכבות הרים מהמהירות ביפן, ובערבי חורף תאורה צבעונית.","reality":"לחובבי רכבות הרים זה אחד הטובים ביפן ובימי חול כמעט בלי תורים. עם תינוק אין כאן הרבה, ובדצמבר חלק מהמתקנים סגורים לתחזוקה.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":null,"tip":"בימי חול בחורף התורים קצרים מאוד, וסופי שבוע עמוסים.","sources":["https://www.japan-guide.com/e/e3313.html","https://www.tokyoweekender.com/location/nagashima-spa-land/"],"audience":"adults","baby_notes":"יש פינת ילדים קטנים, אבל רוב המתקנים אסורים לתינוקות.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Nagashima%20Spa%20Land%20Kuwana%20Mie","website_url":"https://www.nagashima-onsen.co.jp/","serves":null,"dishes":[],"todo":"עולים על רכבת ההרים הלבנה Steel Dragon 2000 ועל Hakugei מעץ, ונשארים לתאורה בערב או ממשיכים לאונסן יואמי נו שימה.","special":"Steel Dragon 2000 היא אחת מרכבות ההרים הארוכות בעולם.","highlights":["Steel Dragon 2000","Hakugei","תאורת החורף"],"time_needed":"יום שלם","kosher":null,"kosher_note":null,"address":"333 Nagashimacho Urayasu, Kuwana, Mie","opens":null,"closes":null,"closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"morning","visit_mins":360,"booking":"no","plan_line":"אוטובוס ישיר מתחנת האוטובוסים מייטטסו בנגויה, כ-50 דקות","baby_block":null,"tags":["theme park","roller coasters","rides","amusement park","thrill","illumination","פארק שעשועים","רכבות הרים","מתקנים","לונה פארק","אדרנלין","תאורה","steel dragon","nagashima","נגאשימה"],"en":{"hype":"A big amusement park with some of Japan's fastest roller coasters and colourful lights on winter evenings.","reality":"For coaster fans it is one of Japan's best, and on weekdays there are almost no queues. Little here for a baby, and in December some rides close for maintenance.","tip":"Winter weekdays have very short queues; weekends are busy.","baby_notes":"There is a small-kids area, but most rides do not allow babies.","price":null,"serves":null,"dishes":[],"todo":"Ride the white Steel Dragon 2000 and the wooden Hakugei, then stay for the evening lights or move on to Yuami no Shima onsen.","special":"Steel Dragon 2000 is one of the longest coasters in the world.","highlights":["Steel Dragon 2000","Hakugei","Winter lights"],"time_needed":"Full day","kosher_note":null,"plan_line":"Direct bus from Meitetsu Bus Center in Nagoya, about 50 minutes","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Yuami no Shima","name_ja":"湯あみの島","city":"nagoya","area":"Around Nagoya","category":"experience","lat":35.03,"lng":136.734,"coord_precision":"approx","hype":"מתחם אונסן ענק בנגאשימה עם בריכות חיצוניות בנוף של עמק הרים יפני משוחזר.","reality":"אחד האונסנים הגדולים באזור והבריכות החיצוניות יפות; בסופי שבוע צפוף. בלי קעקועים, וזה מתאים בדיוק אחרי יום בספא לנד.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":null,"tip":"מגיעים אחרי השקיעה, כשהבריכות החיצוניות מוארות והצפיפות יורדת.","sources":["https://www.japan-guide.com/e/e3313.html","https://japanuncharted.com/mie/theme-park"],"audience":"adults","baby_notes":"תינוקות בחיתולים לא נכנסים לבריכות.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Yuami%20no%20Shima%20Nagashima%20Kuwana","website_url":"https://www.nagashima-onsen.co.jp/","serves":null,"dishes":[],"todo":"מתקלחים, עוברים לבריכות הפנימיות ואז לבריכות החיצוניות בין הסלעים והמפלים, ונחים באזור המנוחה.","special":"גן אבנים ומפלים שבנוי כמו עמק בהרי