select x.name, x.name_ja, x.city, x.area, x.category, x.lat, x.lng, x.coord_precision, x.hype, x.reality, x.verdict, x.tabelog_score, x.google_score, x.price, x.tip, x.sources, x.audience, x.baby_notes, x.local_pick, x.maps_url, x.website_url, x.serves, x.dishes, x.todo, x.special, x.highlights, x.time_needed, x.kosher, x.kosher_note, x.address, x.opens, x.closes, x.closed_weekdays, x.closed_dates, x.open_dates, x.best_time, x.visit_mins, x.booking, x.plan_line, x.baby_block, x.tags, x.en, x.facts_at, x.facts_sure, false from jsonb_populate_recordset(null::place_library, $cards$[{"name":"Shogetsu Himuro","name_ja":"松月氷室","city":"nikko","area":"Around Nikko","category":"cafe","lat":36.722,"lng":139.6855,"coord_precision":"approx","hype":"חנות קקיגורי באימאיצ'י שמייצרת קרח טבעי במאגרים בחוץ בחורף, ונבחרה ל-Tabelog 100 של 2026.","reality":"הקקיגורי הכי טוב באזור, רך וקליל מקרח טבעי. בחורף פחות תור, אבל קר לאכול ברד.","verdict":"gem","tabelog_score":3.65,"google_score":null,"price":"¥1,000-2,000","tip":"לבוא בימי חול, בסופי שבוע של הקיץ יש תורים ארוכים.","sources":["https://tabelog.com/en/tochigi/A0903/A090302/9003227/","https://shogetsuhimuro.com/"],"audience":"baby","baby_notes":"ילדים ועגלות רצויים.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Shogetsu%20Himuro%20Nikko","website_url":"https://shogetsuhimuro.com/","serves":"קקיגורי מקרח טבעי עם סירופים של פירות עונתיים.","dishes":["קקיגורי אפרסק","קקיגורי עונתי"],"todo":null,"special":null,"highlights":[],"time_needed":null,"kosher":"friendly","kosher_note":null,"address":"379 Imaichi, Nikko, Tochigi","opens":"11:00","closes":"16:00","closed_weekdays":[1,2],"closed_dates":[],"open_dates":[],"best_time":"afternoon","visit_mins":40,"booking":"no","plan_line":"סגור בשני ושלישי; בלי כרטיס אשראי (PayPay מתקבל)","baby_block":null,"tags":["kakigori","shaved ice","natural ice","dessert","fruit syrup","ice","sweets","קקיגורי","ברד","קרח טבעי","קינוח","סירופ פירות","מתוקים"],"en":{"hype":"A kakigori shop in Imaichi that makes natural ice in outdoor ponds in winter, picked for Tabelog 100 in 2026.","reality":"The best kakigori around, soft and light from natural ice. Shorter lines in winter, but cold to eat shaved ice.","tip":"Come on a weekday; summer weekends mean long lines.","baby_notes":"Kids and strollers welcome.","price":"¥1,000-2,000","serves":"Natural-ice kakigori with seasonal fruit syrups.","dishes":["Peach kakigori","Seasonal kakigori"],"todo":null,"special":null,"highlights":[],"time_needed":null,"kosher_note":null,"plan_line":"Closed Mon and Tue; no credit cards (PayPay ok)","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Nikko Toshogu Shrine","name_ja":"日光東照宮","city":"nikko","area":"Shrines & Town","category":"sight","lat":36.758,"lng":139.5988,"coord_precision":"approx","hype":"המקדש המפואר של שוגון טוקוגאווה אייאסו, מכוסה זהב וגילופי עץ צבעוניים, אתר מורשת עולמית.","reality":"הכי מרשים ביפן מבחינת עושר פרטים, ושווה את המחיר. בשעות הצהריים ובסופי שבוע עמוס מאוד ותורים לחתול הישן ולקבר.","verdict":"gem","tabelog_score":null,"google_score":null,"price":"¥1,600 למקדש, ¥2,400 כולל המוזיאון","tip":"להגיע בפתיחה ב-9:00, לפני שהאוטובוסים מטוקיו מגיעים.","sources":["https://www.japan-guide.com/e/e3801.html","https://www.toshogu.jp/"],"audience":"baby","baby_notes":"הרבה מדרגות, בעיקר 207 המדרגות לקבר של אייאסו. עדיף מנשא ולא עגלה.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Nikko%20Toshogu%20Shrine%20Nikko","website_url":"https://www.toshogu.jp/","serves":null,"dishes":[],"todo":"עוברים דרך שער יומיימון המגולף, מחפשים את שלושת הקופים ואת החתול הישן, ועולים במדרגות בין עצי ארז עד הקבר. אסור לצלם בתוך המבנה הראשי.","special":"מאות גילופים צבועים בכל קיר ושער, ברמת פירוט שאין באף מקדש אחר ביפן.","highlights":["שער יומיימון","שלושת הקופים","החתול הישן","הקבר של אייאסו"],"time_needed":"שעה וחצי-שעתיים","kosher":null,"kosher_note":null,"address":"2301 Sannai, Nikko, Tochigi","opens":"09:00","closes":"16:00","closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"morning","visit_mins":120,"booking":"no","plan_line":"בחורף נסגר ב-16:00, כניסה אחרונה 15:30. להגיע מוקדם","baby_block":null,"tags":["shrine","shinto","tokugawa","ieyasu","three monkeys","sleeping cat","yomeimon","unesco","world heritage","carvings","מקדש","שינטו","שלושת הקופים","החתול הישן","מורשת עולמית","גילופים","שוגון"],"en":{"hype":"The lavish shrine of shogun Tokugawa Ieyasu, covered in gold and painted carvings. A World Heritage site.","reality":"The most detailed and ornate shrine in Japan, and worth the ticket. Midday and weekends get very crowded, with lines at the sleeping cat and the tomb.","tip":"Arrive at the 9:00 opening, before the tour buses from Tokyo.","baby_notes":"Lots of stairs, especially the 207 steps up to the tomb. Bring a carrier, not a stroller.","price":"¥1,600 shrine, ¥2,400 with the museum","serves":null,"dishes":[],"todo":"Walk through the carved Yomeimon gate, find the three monkeys and the sleeping cat, then climb through the cedars to the tomb. No photos inside the main hall.","special":"Hundreds of painted carvings on every wall and gate, more detail than any other shrine in Japan.","highlights":["Yomeimon gate","Three monkeys","Sleeping cat","Ieyasu's tomb"],"time_needed":"1.5-2 hours","kosher_note":null,"plan_line":"Winter closing 16:00, last entry 15:30. Come early","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Taiyuin","name_ja":"輪王寺 大猷院","city":"nikko","area":"Shrines & Town","category":"sight","lat":36.7589,"lng":139.5962,"coord_precision":"approx","hype":"המאוזוליאום של איימיצו, הנכד של אייאסו, בנוי כמו גרסה קטנה ואפלה יותר של טושוגו.","reality":"שקט הרבה יותר מטושוגו ולא פחות יפה. רוב התיירים מדלגים עליו, וזו טעות.","verdict":"gem","tabelog_score":null,"google_score":null,"price":"¥550, ¥900 כולל אולם סנבוצודו","tip":"לבוא אחרי טושוגו, כשההמונים כבר יורדים לעיר.","sources":["https://www.japan-guide.com/e/e3802.html"],"audience":"baby","baby_notes":"מדרגות אבן רבות בין השערים, עגלה לא מתאימה.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Taiyuin%20Nikko","website_url":null,"serves":null,"dishes":[],"todo":"עולים במדרגות דרך כמה שערים מעוטרים, נכנסים לאולם התפילה ומסתכלים על האולם הראשי מבחוץ.","special":"שחור וזהב בתוך יער ארזים, בלי הדוחק של טושוגו.","highlights":["שער ניאומון","שער יאשה","אולם התפילה"],"time_needed":"כ-45 דקות","kosher":null,"kosher_note":null,"address":"2300 Sannai, Nikko, Tochigi","opens":"08:00","closes":"16:00","closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"afternoon","visit_mins":45,"booking":"no","plan_line":"כרטיס משולב עם סנבוצודו ב-¥900 חוסך כסף","baby_block":"מדרגות אבן, בלי עגלה","tags":["mausoleum","temple","buddhist","iemitsu","tokugawa","gates","unesco","מאוזוליאום","מקדש","בודהיסטי","שערים","מורשת עולמית","קבר"],"en":{"hype":"The mausoleum of Iemitsu, Ieyasu's grandson, built like a smaller, darker Toshogu.","reality":"Much quieter than Toshogu and just as beautiful. Most tourists skip it, which is a mistake.","tip":"Go after Toshogu, when the crowds head back to town.","baby_notes":"Many stone steps between the gates, not for strollers.","price":"¥550, ¥900 with Sanbutsudo Hall","serves":null,"dishes":[],"todo":"Climb through several decorated gates, enter the prayer hall, and see the main hall from outside.","special":"Black and gold in a cedar forest, without the Toshogu crush.","highlights":["Niomon gate","Yashamon gate","Prayer hall"],"time_needed":"About 45 minutes","kosher_note":null,"plan_line":"Combo ticket with Sanbutsudo for ¥900 saves money","baby_block":"Stone steps, no stroller"},"facts_at":"2026-11-09","facts_sure":true},{"name":"Rinnoji Temple","name_ja":"日光山輪王寺","city":"nikko","area":"Shrines & Town","category":"sight","lat":36.7547,"lng":139.6006,"coord_precision":"approx","hype":"המקדש הבודהיסטי הוותיק של ניקו, עם אולם סנבוצודו ושלושה פסלי בודהה מוזהבים בגובה 8 מטר.","reality":"הפסלים מרשימים, אבל אסור לצלם בפנים והאולם עצמו פחות עוצר נשימה מטושוגו. גן שויואן הקטן מאחור שווה את התוספת.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"¥400 לאולם, ¥300 לגן ולאוצר","tip":"גן שויואן הכי יפה בתחילת נובמבר, עם מוארים בערב בעונת השלכת.","sources":["https://www.japan-guide.com/e/e3803.html","https://www.japan-guide.com/e/e3817.html"],"audience":"baby","baby_notes":"האולם והגן במישור, אפשר עם עגלה ברוב השטח.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Rinnoji%20Temple%20Nikko","website_url":null,"serves":null,"dishes":[],"todo":"נכנסים לסנבוצודו לראות את שלושת הבודהות, ואז עוברים לבית האוצר ולגן שויואן עם הבריכה והאדרים.","special":"שלושת הפסלים המוזהבים הם מהגדולים במזרח יפן.","highlights":["אולם סנבוצודו","שלושת הבודהות","גן שויואן"],"time_needed":"כ-45 דקות","kosher":null,"kosher_note":null,"address":"2300 Sannai, Nikko, Tochigi","opens":"08:00","closes":"16:00","closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"any","visit_mins":45,"booking":"no","plan_line":"ליד טושוגו, אפשר לשלב באותו בוקר","baby_block":null,"tags":["temple","buddhist","sanbutsudo","buddha statues","garden","shoyoen","maple","autumn leaves","מקדש","בודהיסטי","פסלי בודהה","גן יפני","אדר","שלכת"],"en":{"hype":"Nikko's oldest Buddhist temple, with Sanbutsudo Hall and three gilded 8-meter Buddhas.","reality":"The statues are impressive, but no photos inside and the hall is less striking than Toshogu. The small Shoyoen garden behind is worth the extra fee.","tip":"Shoyoen garden is best in early November, lit up in the evening during leaf season.","baby_notes":"Hall and garden are mostly flat, fine with a stroller.","price":"¥400 hall, ¥300 garden and treasure house","serves":null,"dishes":[],"todo":"See the three Buddhas in Sanbutsudo, then the treasure house and Shoyoen's pond and maples.","special":"The three gilded statues are among the largest in eastern Japan.","highlights":["Sanbutsudo Hall","Three Buddhas","Shoyoen garden"],"time_needed":"About 45 minutes","kosher_note":null,"plan_line":"Next to Toshogu, easy to do the same morning","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Futarasan Shrine","name_ja":"日光二荒山神社","city":"nikko","area":"Shrines & Town","category":"sight","lat":36.7592,"lng":139.5975,"coord_precision":"approx","hype":"המקדש השינטואיסטי הקדום של ניקו, מוקדש לשלושת ההרים הקדושים, ידוע בתור מקדש של קשרים וזוגיות.","reality":"פשוט יותר מהשכנים, אבל רגוע ונעים. רוב השטח בחינם, והגן הקטן בתשלום שקט במיוחד.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"חינם, ¥300 לגן הפנימי","tip":"הגן הפנימי בתשלום נמצא משמאל לאולם התפילה, עם עצים קדושים ומעיין.","sources":["https://www.japan-guide.com/e/e3804.html"],"audience":"baby","baby_notes":"שבילי חצץ, עגלה עוברת בקושי.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Futarasan%20Shrine%20Nikko","website_url":null,"serves":null,"dishes":[],"todo":"עוברים בין עצי הארז בשביל אל המקדש, קונים קמע, ונכנסים לגן הפנימי עם המעיין והעץ הקדוש.","special":null,"highlights":["עץ הקשרים","הגן הפנימי","המעיין"],"time_needed":"כחצי שעה","kosher":null,"kosher_note":null,"address":"2307 Sannai, Nikko, Tochigi","opens":"09:00","closes":"16:00","closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"any","visit_mins":30,"booking":"no","plan_line":"200 מטר מערבית לטושוגו, בדרך לטאיוּאִין","baby_block":null,"tags":["shrine","shinto","sacred trees","omamori","matchmaking","cedar","מקדש","שינטו","עצים קדושים","קמע","זוגיות","ארז"],"en":{"hype":"Nikko's ancient Shinto shrine, dedicated to its three sacred mountains and known for matchmaking.","reality":"Plainer than its neighbours, but calm and pleasant. Most of it is free, and the small paid garden is very quiet.","tip":"The paid inner garden is left of the prayer hall, with sacred trees and a spring.","baby_notes":"Gravel paths, hard going with a stroller.","price":"Free, ¥300 inner garden","serves":null,"dishes":[],"todo":"Walk the cedar path to the shrine, pick up a charm, and go into the inner garden with the spring and sacred tree.","special":null,"highlights":["Sacred tree","Inner garden","Spring"],"time_needed":"About 30 minutes","kosher_note":null,"plan_line":"200 m west of Toshogu, on the way to Taiyuin","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Shinkyo Bridge","name_ja":"神橋","city":"nikko","area":"Shrines & Town","category":"sight","lat":36.7533,"lng":139.6036,"coord_precision":"approx","hype":"הגשר האדום המפורסם מעל נהר דאיה, השער לאזור המקדשים ואחד משלושת הגשרים היפים ביפן.","reality":"הצילום מהכביש בחינם נותן את רוב היופי. לחצות ברגל עולה ¥300 ולוקח שתי דקות, ולא חוצים לצד השני אלא חוזרים.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"¥300 לחצייה, חינם לצפייה מהכביש","tip":"הזווית הטובה לצילום היא מהגשר של הכביש שליד, בלי לשלם.","sources":["https://www.japan-guide.com/e/e3814.html"],"audience":"baby","baby_notes":"הגשר מקושת עם עליה, עם עגלה עדיף רק לצלם מבחוץ.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Shinkyo%20Bridge%20Nikko","website_url":null,"serves":null,"dishes":[],"todo":"מצלמים מגשר הכביש, ואם רוצים משלמים ועולים על הגשר עד האמצע וחזרה.","special":"הגשר הנוכחי מ-1636, והיה סגור לציבור עד 1973.","highlights":["צילום מגשר הכביש","שלכת מעל הנהר"],"time_needed":"15 דקות","kosher":null,"kosher_note":null,"address":"Kamihatsuishimachi, Nikko, Tochigi","opens":"09:00","closes":"16:00","closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"morning","visit_mins":15,"booking":"no","plan_line":"לצלם מהגשר של הכביש בחינם, לחצות רק אם רוצים","baby_block":null,"tags":["bridge","red bridge","vermilion","river","daiya river","photo spot","גשר","גשר אדום","נהר","צילום","שלכת"],"en":{"hype":"The famous red bridge over the Daiya River, gateway to the shrines and one of Japan's three finest bridges.","reality":"The free view from the road bridge gives you most of it. Walking on costs ¥300, takes two minutes, and you come back the same way.","tip":"The best photo angle is from the road bridge next to it, for free.","baby_notes":"The bridge arches up, so with a stroller just photograph it from outside.","price":"¥300 to cross, free to view","serves":null,"dishes":[],"todo":"Photograph it from the road bridge, and if you want, pay to walk out to the middle and back.","special":"This bridge dates from 1636 and was closed to the public until 1973.","highlights":["View from the road bridge","Autumn leaves over the river"],"time_needed":"15 minutes","kosher_note":null,"plan_line":"Photograph it free from the road bridge, cross only if you want","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Kanmangafuchi Abyss","name_ja":"憾満ヶ淵","city":"nikko","area":"Shrines & Town","category":"sight","lat":36.7485,"lng":139.5867,"coord_precision":"approx","hype":"ערוץ נהר קטן עם שורה של כ-70 פסלי ג׳יזו אבן עם כובעים אדומים, הנקראים \"ג׳יזו הרפאים\".","reality":"אחת ההליכות היפות והשקטות בניקו, ובחינם. קצר, אבל אווירה מיוחדת בין האבנים המכוסות טחב.","verdict":"gem","tabelog_score":null,"google_score":null,"price":"חינם","tip":"משלבים עם וילת טאמוזאווה, 10-15 דקות הליכה משם.","sources":["https://www.japan-guide.com/e/e3810.html"],"audience":"baby","baby_notes":"שביל אבן לא אחיד ליד הנהר, עגלה קשה. מנשא עדיף.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Kanmangafuchi%20Abyss%20Nikko","website_url":null,"serves":null,"dishes":[],"todo":"הולכים לאורך הנהר הסוער בשביל של כמה מאות מטרים, עוברים לאורך שורת הג׳יזו ומגיעים לגשר קטן.","special":"אומרים שאי אפשר לספור את הפסלים פעמיים ולקבל אותו מספר.","highlights":["שורת הג׳יזו","הנהר בתוך סלעי לבה"],"time_needed":"30-45 דקות","kosher":null,"kosher_note":null,"address":"2411 Nikko, Tochigi","opens":null,"closes":null,"closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"morning","visit_mins":40,"booking":"no","plan_line":"אוטובוס לתחנת Tamozawa ומשם 10-15 דקות ברגל","baby_block":"שביל אבן לא אחיד, בלי עגלה","tags":["gorge","jizo","statues","river walk","moss","free","ghost jizo","walk","ערוץ","ג׳יזו","פסלים","הליכה","טחב","נהר","חינם"],"en":{"hype":"A small river gorge lined with about 70 stone Jizo statues in red caps, called the Ghost Jizo.","reality":"One of the nicest quiet walks in Nikko, and free. Short, but special among the mossy rocks.","tip":"Pair it with Tamozawa Villa, a 10-15 minute walk away.","baby_notes":"Uneven stone path by the river, hard with a stroller. Carrier is better.","price":"Free","serves":null,"dishes":[],"todo":"Follow the rushing river for a few hundred meters past the row of Jizo to a small bridge.","special":"Legend says you never count the same number of statues twice.","highlights":["Row of Jizo","River through lava rock"],"time_needed":"30-45 minutes","kosher_note":null,"plan_line":"Bus to Tamozawa stop, then a 10-15 minute walk","baby_block":"Uneven stone path, no stroller"},"facts_at":"2026-11-09","facts_sure":true},{"name":"Nikko Tamozawa Imperial Villa Memorial Park","name_ja":"日光田母沢御用邸記念公園","city":"nikko","area":"Shrines & Town","category":"sight","lat":36.7495,"lng":139.5893,"coord_precision":"approx","hype":"ארמון הקיץ של המשפחה הקיסרית מ-1899, עם עשרות חדרי טאטאמי וגן אדרים.","reality":"מבנה עץ ענק ומטופח, שקט ומעניין, עם הסברים באנגלית. משעמם קצת למי שלא אוהב ארכיטקטורה.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"¥600","tip":"החדרים קרים בחורף, כדאי לבוא עם גרביים עבות כי הולכים בלי נעליים.","sources":["https://www.japan-guide.com/e/e3808.html"],"audience":"baby","baby_notes":"מסלול מקורה ושטוח ברובו, עגלות נשארות בכניסה.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Nikko%20Tamozawa%20Imperial%20Villa%20Memorial%20Park%20Nikko","website_url":null,"serves":null,"dishes":[],"todo":"מורידים נעליים ועוברים בין חדרי הקיסר, המטבח וחדר הקבלה, ומסיימים בטיול קצר בגן.","special":"אחד מבתי העץ הגדולים ביפן מתקופת מייג׳י, חלקו הועבר מטוקיו.","highlights":["חדר הקבלה","הגן עם האדרים"],"time_needed":"כשעה","kosher":null,"kosher_note":null,"address":"8-27 Honcho, Nikko, Tochigi","opens":"09:00","closes":"16:30","closed_weekdays":[2],"closed_dates":["2026-12-29","2026-12-30","2026-12-31"],"open_dates":[],"best_time":"any","visit_mins":60,"booking":"no","plan_line":"סגור בימי שלישי, כניסה אחרונה 15:45 בחורף","baby_block":null,"tags":["imperial villa","palace","tatami","garden","maple","architecture","meiji","museum","וילה קיסרית","ארמון","טאטאמי","גן","אדר","ארכיטקטורה","מוזיאון"],"en":{"hype":"The imperial family's summer palace from 1899, with dozens of tatami rooms and a maple garden.","reality":"A huge, well-kept wooden building, quiet and interesting, with English signs. A bit dull if architecture is not your thing.","tip":"The rooms are cold in winter and you go shoeless, so wear thick socks.","baby_notes":"Covered and mostly flat route, strollers stay at the entrance.","price":"¥600","serves":null,"dishes":[],"todo":"Take off your shoes and walk through the emperor's rooms, kitchen and audience hall, then a short garden loop.","special":"One of Japan's largest Meiji-era wooden residences, part of it moved from Tokyo.","highlights":["Audience hall","Maple garden"],"time_needed":"About an hour","kosher_note":null,"plan_line":"Closed Tuesdays, last entry 15:45 in winter","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Nikko Botanical Garden","name_ja":"東京大学大学院理学系研究科附属植物園 日光分園","city":"nikko","area":"Shrines & Town","category":"sight","lat":36.7472,"lng":139.5839,"coord_precision":"approx","hype":"הגן הבוטני של אוניברסיטת טוקיו, עם צמחי הרים, ביצות ופריחה באביב ובקיץ.","reality":"נעים לחובבי טבע באביב ובקיץ. סגור כל החורף, מדצמבר עד מרץ.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"¥500","tip":"אי אפשר להגיע אליו מתוך ערוץ קנמנגאפוצ׳י, הכניסה מהכביש הראשי.","sources":["https://www.japan-guide.com/e/e3809.html"],"audience":"baby","baby_notes":"שבילים רחבים ושטוחים ברובם, טוב לעגלה.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Nikko%20Botanical%20Garden%20Nikko","website_url":null,"serves":null,"dishes":[],"todo":"מסתובבים בשבילים בין צמחי הרים, בריכות ושטחי ביצה.","special":null,"highlights":["צמחי הרים","פריחת אביב"],"time_needed":"כשעה","kosher":null,"kosher_note":null,"address":"1842 Hanaishimachi, Nikko, Tochigi","opens":"09:00","closes":"16:30","closed_weekdays":[1],"closed_dates":["2026-12-12","2026-12-13","2026-12-14","2026-12-15","2026-12-16","2026-12-17","2026-12-18","2026-12-19","2026-12-20","2026-12-21","2026-12-22","2026-12-23","2026-12-24","2026-12-25","2026-12-26","2026-12-27","2026-12-28","2026-12-29","2026-12-30","2026-12-31"],"open_dates":[],"best_time":"morning","visit_mins":60,"booking":"no","plan_line":"סגור מ-1 בדצמבר עד סוף מרץ, ובימי שני","baby_block":null,"tags":["botanical garden","plants","flowers","alpine plants","nature","gan botani","גן בוטני","צמחים","פרחים","טבע","צמחי הרים"],"en":{"hype":"University of Tokyo's botanical garden, with mountain plants, wetlands and spring and summer blooms.","reality":"Nice for nature lovers in spring and summer. Closed all winter, December to March.","tip":"You can't reach it from Kanmangafuchi, the entrance is on the main road.","baby_notes":"Wide, mostly flat paths, good for a stroller.","price":"¥500","serves":null,"dishes":[],"todo":"Walk the paths among mountain plants, ponds and wetland.","special":null,"highlights":["Mountain plants","Spring blooms"],"time_needed":"About an hour","kosher_note":null,"plan_line":"Closed December 1 to end of March, and Mondays","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Kanaya Hotel History House","name_ja":"金谷ホテル歴史館","city":"nikko","area":"Shrines & Town","category":"sight","lat":36.7503,"lng":139.599,"coord_precision":"approx","hype":"בית הסמוראי שבו נפתח ב-1873 הפונדק הראשון לזרים בניקו, ושם התארחה הנוסעת איזבלה בירד.","reality":"מוזיאון קטן וחמוד בבית עץ ישן, מתאים למי שאוהב היסטוריה. לא חובה בביקור קצר.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"¥550","tip":"הכרטיסים נמכרים במאפייה שליד הבית.","sources":["https://www.japan-guide.com/e/e3823.html"],"audience":"baby","baby_notes":"בית יפני עם מדרגות פנימיות, עגלה נשארת בחוץ.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Kanaya%20Hotel%20History%20House%20Nikko","website_url":null,"serves":null,"dishes":[],"todo":"מורידים נעליים ומסתובבים בחדרי הבית המקורי, עם תמונות ומכתבים של האורחים הזרים הראשונים.","special":"מכאן התחיל מלון קנאיה, מלון הנופש הוותיק ביפן.","highlights":["חדרי הפונדק הראשון","הגן"],"time_needed":"כחצי שעה","kosher":null,"kosher_note":null,"address":"1-25 Honcho, Nikko, Tochigi","opens":"10:00","closes":"16:00","closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"any","visit_mins":30,"booking":"no","plan_line":"בדצמבר עד פברואר 2-3 ימי סגירה לא קבועים בחודש","baby_block":null,"tags":["history","museum","samurai house","old house","isabella bird","kanaya","היסטוריה","מוזיאון","בית סמוראי","בית עתיק"],"en":{"hype":"The samurai house where Nikko's first inn for foreigners opened in 1873. Isabella Bird stayed here.","reality":"A small, charming museum in an old wooden house, for history fans. Skippable on a short visit.","tip":"Tickets are sold at the bakery next door.","baby_notes":"Japanese house with inside stairs, strollers stay outside.","price":"¥550","serves":null,"dishes":[],"todo":"Take off your shoes and walk the original rooms, with photos and letters from the first foreign guests.","special":"This is where the Kanaya Hotel, Japan's oldest resort hotel, began.","highlights":["First inn rooms","Garden"],"time_needed":"About 30 minutes","kosher_note":null,"plan_line":"Dec to Feb it closes 2-3 irregular days a month","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Nikko Kanaya Hotel","name_ja":"日光金谷ホテル","city":"nikko","area":"Shrines & Town","category":"sight","lat":36.7523,"lng":139.6058,"coord_precision":"approx","hype":"מלון הנופש הוותיק ביפן, מ-1873, בבניין עץ בסגנון מערבי-יפני מעל הגשר האדום.","reality":"אפשר להיכנס ללובי ולמסדרונות הישנים גם בלי ללון, ולשבת לקפה או ארוחה. אווירה של פעם, מחירים של מלון.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"כניסה חופשית, קפה או ארוחה בתשלום","tip":"כדאי לשלב עם הגשר האדום, דקה הליכה במעלה הגבעה.","sources":["https://www.kanayahotel.co.jp/"],"audience":"baby","baby_notes":"יש מדרגות בכניסה, הלובי עצמו נוח.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Nikko%20Kanaya%20Hotel%20Nikko","website_url":"https://www.kanayahotel.co.jp/","serves":null,"dishes":[],"todo":"עולים מהגשר האדום, מסתובבים בלובי ובמסדרונות עם הריהוט מתקופת מייג׳י, ואם רוצים יושבים לקפה.","special":"בניין משנות ה-1890 שבו התארחו דיפלומטים ואורחים מפורסמים מכל העולם.","highlights":["הלובי הישן","חדר האוכל ההיסטורי"],"time_needed":"כחצי שעה","kosher":null,"kosher_note":null,"address":"1300 Kamihatsuishimachi, Nikko, Tochigi","opens":null,"closes":null,"closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"afternoon","visit_mins":30,"booking":"no","plan_line":"מעל הגשר האדום, עצירה קצרה בדרך מהתחנה למקדשים","baby_block":null,"tags":["historic hotel","hotel","meiji","architecture","lobby","classic hotel","מלון היסטורי","מלון","ארכיטקטורה","מייג׳י","לובי"],"en":{"hype":"Japan's oldest resort hotel, from 1873, in a Western-Japanese wooden building above the red bridge.","reality":"You can walk into the lobby and old halls without staying, and sit for coffee or a meal. Old-world feel, hotel prices.","tip":"Pair it with the red bridge, a minute's walk up the hill.","baby_notes":"Steps at the entrance, the lobby itself is easy.","price":"Free to enter, coffee or meals extra","serves":null,"dishes":[],"todo":"Walk up from the red bridge, look around the lobby and 