select x.name, x.name_ja, x.city, x.area, x.category, x.lat, x.lng, x.coord_precision, x.hype, x.reality, x.verdict, x.tabelog_score, x.google_score, x.price, x.tip, x.sources, x.audience, x.baby_notes, x.local_pick, x.maps_url, x.website_url, x.serves, x.dishes, x.todo, x.special, x.highlights, x.time_needed, x.kosher, x.kosher_note, x.address, x.opens, x.closes, x.closed_weekdays, x.closed_dates, x.open_dates, x.best_time, x.visit_mins, x.booking, x.plan_line, x.baby_block, x.tags, x.en, x.facts_at, x.facts_sure, false from jsonb_populate_recordset(null::place_library, $cards$[{"name":"Jakko Falls","name_ja":"寂光の滝","city":"nikko","area":"Around Nikko","category":"sight","lat":36.762,"lng":139.581,"coord_precision":"approx","hype":"מפל של שבעה מדרגות ביער מערבית לעיר, ליד מקדש קטן ונטוש למחצה.","reality":"שקט מאוד וכמעט בלי תיירים, הליכה יפה ביער. השביל האחרון לא מסומן היטב.","verdict":"gem","tabelog_score":null,"google_score":null,"price":"חינם","tip":"מתחנת Tamozawa הולכים כ-30 דקות בעלייה בכביש צדדי.","sources":["https://www.japan-guide.com/e/e3800.html"],"audience":"adults","baby_notes":null,"local_pick":true,"maps_url":"https://www.google.com/maps/search/?api=1&query=Jakko%20Falls%20Nikko","website_url":null,"serves":null,"dishes":[],"todo":"עולים מהכביש הראשי בדרך צדדית ביער, עוברים את המקדש הקטן ומגיעים למפל.","special":null,"highlights":["שבע מדרגות המפל","מקדש ביער"],"time_needed":"שעה וחצי הלוך וחזור","kosher":null,"kosher_note":null,"address":"Tokorono, Nikko, Tochigi","opens":null,"closes":null,"closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"morning","visit_mins":90,"booking":"no","plan_line":"לא ללכת לבד בחושך, שביל יער שקט מאוד","baby_block":"שביל יער לא סלול","tags":["waterfall","falls","forest walk","hike","quiet","shrine","מפל","הליכה ביער","טיול","שקט","מקדש"],"en":{"hype":"A seven-step waterfall in the forest west of town, by a small, half-forgotten shrine.","reality":"Very quiet with almost no tourists, a nice forest walk. The last stretch isn't well signed.","tip":"From Tamozawa bus stop it's about 30 minutes uphill on a side road.","baby_notes":null,"price":"Free","serves":null,"dishes":[],"todo":"Head up a side road into the forest from the main road, pass the small shrine and reach the falls.","special":null,"highlights":["Seven-step falls","Forest shrine"],"time_needed":"1.5 hours round trip","kosher_note":null,"plan_line":"Don't go alone after dark, very quiet forest path","baby_block":"Unpaved forest path"},"facts_at":"2026-11-09","facts_sure":true},{"name":"Urami Falls","name_ja":"裏見の滝","city":"nikko","area":"Around Nikko","category":"sight","lat":36.766,"lng":139.572,"coord_precision":"approx","hype":"מפל של 19 מטר בין סלעים ירוקים, שהשם שלו פירושו \"נראה מאחור\".","reality":"מפל קטן ויפה בסוף הליכה קצרה ביער, טוב לשלב עם ג׳אקו. לא שווה נסיעה מיוחדת.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"חינם","tip":"מהחניה 15 דקות הליכה בשביל עם מדרגות.","sources":["https://www.japan-guide.com/e/e3800.html"],"audience":"adults","baby_notes":null,"local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Urami%20Falls%20Nikko","website_url":null,"serves":null,"dishes":[],"todo":"הולכים מהחניה בשביל לאורך הנחל עד התצפית מול המפל.","special":null,"highlights":["המפל בין הסלעים","הנחל"],"time_needed":"45 דקות","kosher":null,"kosher_note":null,"address":"Tokorono, Nikko, Tochigi","opens":null,"closes":null,"closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"morning","visit_mins":45,"booking":"no","plan_line":"קשה בלי רכב, אין אוטובוס צמוד","baby_block":"שביל עם מדרגות","tags":["waterfall","falls","forest","hike","stream","מפל","יער","טיול","נחל","waterfalls","nature","טבע"],"en":{"hype":"A 19 m waterfall among green rocks, its name means seen from behind.","reality":"A small, pretty falls at the end of a short forest walk, good to pair with Jakko. Not worth a special trip.","tip":"It's a 15-minute walk from the car park on a path with steps.","baby_notes":null,"price":"Free","serves":null,"dishes":[],"todo":"Walk from the car park along the stream to the deck facing the falls.","special":null,"highlights":["Falls between the rocks","The stream"],"time_needed":"45 minutes","kosher_note":null,"plan_line":"Hard without a car, no bus nearby","baby_block":"Path with steps"},"facts_at":"2026-11-09","facts_sure":true},{"name":"Ashio Copper Mine","name_ja":"足尾銅山観光","city":"nikko","area":"Around Nikko","category":"experience","lat":36.638,"lng":139.442,"coord_precision":"approx","hype":"מכרה נחושת היסטורי שנכנסים אליו ברכבת קטנה, עם בובות שמראות איך עבדו הכורים.","reality":"מעניין והחלק ברכבת כיף, אבל הבובות קצת מיושנות. רחוק מניקו, מתאים בעיקר עם רכב או בשילוב רכבת ואטארסה.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":null,"tip":"בתוך המכרה קר גם בקיץ, להביא שכבה נוספת.","sources":["https://ja.wikipedia.org/wiki/足尾銅山"],"audience":"baby","baby_notes":"הרכבת והמנהרות שטוחות, אבל קר וחשוך בפנים.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Ashio%20Copper%20Mine%20Nikko","website_url":null,"serves":null,"dishes":[],"todo":"עולים לרכבת הקטנה לתוך המנהרה, הולכים במנהרות עם תצוגות של עבודת הכורים לאורך מאות שנים, ויוצאים למוזיאון קטן.","special":"אחד המכרות הגדולים ביפן, וגם מקור לאסון הזיהום התעשייתי הראשון של יפן.","highlights":["הרכבת למנהרה","המנהרות"],"time_needed":"כשעה","kosher":null,"kosher_note":null,"address":"Ashiomachi Tsudo, Nikko, Tochigi","opens":null,"closes":null,"closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"midday","visit_mins":60,"booking":"no","plan_line":"כשעה ברכב מניקו, ליד תחנת Tsudo של רכבת ואטארסה","baby_block":null,"tags":["mine","copper mine","tunnel","history","industrial heritage","mine train","family","מכרה","מכרה נחושת","מנהרה","היסטוריה","תעשייה","רכבת","משפחה"],"en":{"hype":"A historic copper mine you enter by a little train, with figures showing how the miners worked.","reality":"Interesting and the train part is fun, but the figures are dated. Far from Nikko, best by car or with the Watarase railway.","tip":"It's cold inside the mine even in summer, bring a layer.","baby_notes":"Train and tunnels are flat, but cold and dark inside.","price":null,"serves":null,"dishes":[],"todo":"Ride the little train into the tunnel, walk through displays of centuries of mining, and finish at a small museum.","special":"One of Japan's biggest mines, and the source of its first industrial pollution disaster.","highlights":["Train into the tunnel","The tunnels"],"time_needed":"About an hour","kosher_note":null,"plan_line":"An hour's drive from Nikko, by Tsudo station on the Watarase line","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Watarase Keikoku Railway","name_ja":"わたらせ渓谷鐵道","city":"nikko","area":"Around Nikko","category":"experience","lat":36.6355,"lng":139.4485,"coord_precision":"approx","hype":"קו רכבת מקומי לאורך עמק נהר ווטארסה עד אשיו, עם קרונות פתוחים בעונה.","reality":"נסיעה יפה ואיטית, בעיקר בשלכת. הקרונות הפתוחים רצים רק בעונה, ובחורף נשארת רכבת מקומית רגילה.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":null,"tip":"משלבים עם מכרה אשיו, יורדים בתחנת Tsudo.","sources":["https://www.watetsu.com/"],"audience":"baby","baby_notes":"רכבת רגילה עם מקום לעגלה מתקפלת. הקרונות הפתוחים רועשים וקרים.","local_pick":true,"maps_url":"https://www.google.com/maps/search/?api=1&query=Watarase%20Keikoku%20Railway%20Nikko","website_url":"https://www.watetsu.com/","serves":null,"dishes":[],"todo":"נוסעים לאורך הנהר בין הרים, יורדים באשיו למכרה ולעיירה הישנה.","special":null,"highlights":["נוף העמק","קרונות פתוחים בעונה"],"time_needed":"כמה שעות","kosher":null,"kosher_note":null,"address":"Tsudo Station, Ashiomachi, Nikko, Tochigi","opens":null,"closes":null,"closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"morning","visit_mins":120,"booking":"recommended","plan_line":"הקרונות הפתוחים רק בעונה, לבדוק לוח זמנים באתר","baby_block":null,"tags":["train","railway","scenic train","open car","torokko","valley","autumn","רכבת","נסיעה ברכבת","נוף","עמק","שלכת","קרון פתוח"],"en":{"hype":"A local line up the Watarase River valley to Ashio, with open-air cars in season.","reality":"A slow, pretty ride, best in autumn. The open cars only run in season; in winter it's a regular local train.","tip":"Pair it with Ashio Copper Mine, get off at Tsudo station.","baby_notes":"Regular train with room for a folded stroller. Open cars are noisy and cold.","price":null,"serves":null,"dishes":[],"todo":"Ride along the river between the mountains and get off in Ashio for the mine and old town.","special":null,"highlights":["Valley views","Open cars in season"],"time_needed":"A few hours","kosher_note":null,"plan_line":"Open cars run only in season, check the timetable online","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Yashio no Yu","name_ja":"やしおの湯","city":"nikko","area":"Around Nikko","category":"experience","lat":36.747,"lng":139.556,"coord_precision":"approx","hype":"מרחץ ציבורי של העירייה בדרך לאירוהאזקה, עם אמבטיות פנים וחוץ במחיר זול.","reality":"האונסן הזול והנוח ביותר ליד מרכז ניקו, מקומי ופשוט. מקום טוב לסיים יום של טיולים.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"¥700 למבוגר, מגבת ¥300","tip":"מגבת עולה כסף, כדאי לבוא עם מגבת משלהם.","sources":["https://www.visit-tochigi.com/plan-your-trip/things-to-do/1993","https://www.visitnikko.jp/en/spots/day-trip-onsen-in-nikko/"],"audience":"adults","baby_notes":null,"local_pick":true,"maps_url":"https://www.google.com/maps/search/?api=1&query=Yashio%20no%20Yu%20Nikko","website_url":null,"serves":null,"dishes":[],"todo":"משלמים במכונה, מתקלחים, טובלים באמבטיות הפנים ובאמבטיה בחוץ מול היער, ונחים באולם המנוחה.","special":null,"highlights":["אמבטיה בחוץ","אולם המנוחה"],"time_needed":"שעה-שעה וחצי","kosher":null,"kosher_note":null,"address":"Kiyotaki, Nikko, Tochigi","opens":"10:00","close