select x.name, x.name_ja, x.city, x.area, x.category, x.lat, x.lng, x.coord_precision, x.hype, x.reality, x.verdict, x.tabelog_score, x.google_score, x.price, x.tip, x.sources, x.audience, x.baby_notes, x.local_pick, x.maps_url, x.website_url, x.serves, x.dishes, x.todo, x.special, x.highlights, x.time_needed, x.kosher, x.kosher_note, x.address, x.opens, x.closes, x.closed_weekdays, x.closed_dates, x.open_dates, x.best_time, x.visit_mins, x.booking, x.plan_line, x.baby_block, x.tags, x.en, x.facts_at, x.facts_sure, false from jsonb_populate_recordset(null::place_library, $cards$[{"name":"Cafe ichara","name_ja":"Cafe ichara","city":"okinawa","area":"North Okinawa","category":"cafe","lat":26.635,"lng":127.945,"coord_precision":"approx","hype":"בית קפה בתוך יער ביאזומי שבמוטובו, עם ישיבה מול הירוק ואוכל עונתי.","reality":"שקט ויפה, הדרך אליו בכבישים צרים. מתאים לעצירה רגועה בין צ׳ורראומי לנאגו.","verdict":"gem","tabelog_score":null,"google_score":null,"price":null,"tip":null,"sources":["https://rurubu.jp/andmore/spot/80043180","https://savorjapan.com/0004050116"],"audience":"adults","baby_notes":null,"local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Cafe%20ichara%20Okinawa","website_url":null,"serves":"ארוחות צהריים קלות עונתיות, עוגות וקפה.","dishes":["מגש צהריים עונתי","עוגה","קפה"],"todo":null,"special":null,"highlights":[],"time_needed":"כשעה","kosher":"options","kosher_note":"לשאול על רכיבי המנה העונתית.","address":"2416-1 Izumi, Motobu, Okinawa","opens":"11:30","closes":"16:00","closed_weekdays":[2,3],"closed_dates":[],"open_dates":[],"best_time":"midday","visit_mins":60,"booking":"no","plan_line":"סגור בימי ג׳ וד׳. הזמנה אחרונה 15:15","baby_block":null,"tags":["cafe","coffee","breakfast","קפה","בית קפה","ארוחת בוקר","forest","nature","lunch","cake","motobu","יער","טבע","צהריים","עוגה"],"en":{"hype":"Cafe in the Izumi forest in Motobu, with seats facing the green and seasonal food.","reality":"Quiet and pretty, reached on narrow roads. A calm stop between Churaumi and Nago.","tip":null,"baby_notes":null,"price":null,"serves":"Light seasonal lunches, cakes and coffee.","dishes":["Seasonal lunch set","Cake","Coffee"],"todo":null,"special":null,"highlights":[],"time_needed":"About an hour","kosher_note":"Ask what is in the seasonal set.","plan_line":"Closed Tue and Wed. Last order 15:15","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Kokusai-dori","name_ja":"国際通り","city":"okinawa","area":"Kokusai-dori & Makishi","category":"sight","lat":26.2155,"lng":127.688,"coord_precision":"approx","hype":"הרחוב הראשי של נאהה, 1.6 ק\"מ של חנויות מזכרות, אוכל ובארים, והמקום שכולם עוברים בו ביום הראשון.","reality":"רוב החנויות מוכרות את אותן מזכרות, אבל זה בסיס נוח, והסמטאות והשווקים המקורים שיוצאים ממנו שווים יותר מהרחוב עצמו.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"כניסה חופשית","tip":"כדאי לרדת לשווקים המקורים שיוצאים מאמצע הרחוב, שם יותר מקומי וזול יותר.","sources":["https://www.japan-guide.com/e/e7114.html","https://en.japantravel.com/places/japan/kokusai-street/791"],"audience":"baby","baby_notes":"מדרכות רחבות ושטוחות, נוח עם עגלה. בערב מתמלא אנשים.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Kokusai-dori%20Okinawa","website_url":null,"serves":null,"dishes":[],"todo":"הולכים לאורך הרחוב מצד תחנת קנצ'ו-מאה עד מקישי, נכנסים לחנויות ולשווקים המקורים בצד. בערב יושבים באחד הבארים או אוכלים משהו בדרך.","special":"זה הרחוב היחיד באוקינאווה שחי עד מאוחר, וממנו יוצאים השווקים הישנים של נאהה.","highlights":["השווקים המקורים בצד","סמטת יאצ'ימון בקצה","חנויות מזכרות של אוקינאווה"],"time_needed":"שעה-שעתיים","kosher":null,"kosher_note":null,"address":"Kokusai-dori, Matsuo, Naha, Okinawa","opens":null,"closes":null,"closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"evening","visit_mins":90,"booking":"no","plan_line":"בימי ראשון אחה\"צ חלק מהרחוב נסגר לרכבים והופך למדרחוב","baby_block":null,"tags":["shopping street","souvenirs","walk","night","main street","arcade","רחוב קניות","מזכרות","טיול רגלי","ערב","רחוב ראשי","קניות","street","שוק","market"],"en":{"hype":"Naha's main street, 1.6 km of souvenir shops, food and bars, and where everyone goes on day one.","reality":"Most shops sell the same souvenirs, but it is a handy base, and the side lanes and covered markets beat the street itself.","tip":"Head into the covered markets off the middle of the street, more local and cheaper.","baby_notes":"Wide flat sidewalks, easy with a stroller. Crowded in the evening.","price":"Free","serves":null,"dishes":[],"todo":"Walk the street from Kencho-mae station end to Makishi and duck into the shops and covered markets on the side. In the evening sit in a bar or grab food on the way.","special":"The one street in Okinawa that stays lively late, and the old Naha markets branch off it.","highlights":["Covered side markets","Yachimun street at the end","Okinawan souvenir shops"],"time_needed":"1-2 hours","kosher_note":null,"plan_line":"On Sunday afternoons part of the street closes to cars","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Tsuboya Yachimun Street","name_ja":"壺屋やちむん通り","city":"okinawa","area":"Kokusai-dori & Makishi","category":"shopping","lat":26.213,"lng":127.692,"coord_precision":"approx","hype":"רחוב אבן קטן של סדנאות קרמיקה (יאצ'ימון) שפועלות מהמאה ה-17, עשר דקות הליכה מקוקוסאי-דורי.","reality":"שקט ויפה, הרבה יותר אותנטי מהרחוב הראשי. קערות וספלים בעבודת יד במחירים סבירים.","verdict":"gem","tabelog_score":null,"google_score":null,"price":"ספל או קערה בערך ¥1,500-5,000","tip":"כדאי לטפס לסמטאות מאחור, שם נמצא תנור הטיפוס הישן ושקט לגמרי.","sources":["https://www.japan-guide.com/e/e7115.html","https://www.gltjp.com/en/directory/item/13362/"],"audience":"baby","baby_notes":"הרחוב הראשי מרוצף ושטוח, הסמטאות שמאחור תלולות עם מדרגות.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Tsuboya%20Yachimun%20Street%20Okinawa","website_url":null,"serves":null,"dishes":[],"todo":"עוברים בין החנויות לאורך הרחוב, מסתכלים על כלים של כמה סדנאות וקונים כמה. אפשר לקפוץ למוזיאון הקרמיקה בתחילת הרחוב.","special":"רוב החנויות הן של סדנאות שמייצרות במקום, לא סחורה מיובאת.","highlights":["כלי אריה שיסא","קערות בצבעי כחול וירוק","התנור הישן בסמטה"],"time_needed":"שעה-שעתיים","kosher":null,"kosher_note":null,"address":"Tsuboya 1-chome, Naha, Okinawa","opens":null,"closes":null,"closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"afternoon","visit_mins":75,"booking":"no","plan_line":"הרבה חנויות נסגרות סביב 18:00, כדאי להגיע אחה\"צ","baby_block":null,"tags":["pottery","ceramics","yachimun","bowls","cups","shisa","craft","קרמיקה","כלי חרס","קערות","ספלים","שיסא","מלאכת יד","yachimun street","סדנאות"],"en":{"hype":"A small stone street of pottery (yachimun) workshops working since the 1600s, a 10 minute walk from Kokusai-dori.","reality":"Quiet and pretty, far more real than the main street. Handmade bowls and cups at fair prices.","tip":"Climb into the back lanes, where the old climbing kiln is and it is totally quiet.","baby_notes":"The main street is paved and flat, the back lanes are steep with steps.","price":"A cup or bowl about ¥1,500-5,000","serves":null,"dishes":[],"todo":"Browse the shops along the street, compare a few workshops and buy some pieces. The pottery museum is at the start of the street.","special":"Most shops belong to workshops that make the pieces on site, not imported stock.","highlights":["Shisa lion pieces","Blue and green bowls","The old kiln in the lane"],"time_needed":"1-2 hours","kosher_note":null,"plan_line":"Many shops close around 18:00, come in the afternoon","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Naha Municipal Tsuboya Pottery Museum","name_ja":"那覇市立壺屋焼物博物館","city":"okinawa","area":"Kokusai-dori & Makishi","category":"sight","lat":26.2133,"lng":127.6908,"coord_precision":"approx","hype":"מוזיאון קטן על הקרמיקה של אוקינאווה, בכניסה לרחוב יאצ'ימון.","reality":"קטן ומסודר, עם הסבר טוב באנגלית. שווה חצי שעה לפני הקניות ברחוב, לא יותר.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"¥350","tip":null,"sources":["https://www.japan-guide.com/e/e7115.html","https://thegate12.com/spot/1852"],"audience":"baby","baby_notes":"יש מעלית.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Naha%20Municipal%20Tsuboya%20Pottery%20Museum%20Okinawa","website_url":null,"serves":null,"dishes":[],"todo":"עוברים על התצוגה של כלים ישנים ותהליך העבודה, ויוצאים לרחוב לקנות עם עין קצת יותר מבינה.","special":"בתוך הבניין יש שרידים של תנור ישן שנמצא במקום.","highlights":["תנור ישן בתוך הבניין","כלים מתקופת הממלכה"],"time_needed":"חצי שעה-שעה","kosher":null,"kosher_note":null,"address":"1-9-32 Tsuboya, Naha, Okinawa","opens":"10:00","closes":"18:00","closed_weekdays":[1],"closed_dates":["2026-12-28","2026-12-29","2026-12-30","2026-12-31"],"open_dates":[],"best_time":"afternoon","visit_mins":40,"booking":"no","plan_line":"סגור בימי שני ומ-28 בדצמבר, כדאי לבדוק לפני","baby_block":null,"tags":["museum","pottery","ceramics","history","kiln","מוזיאון","קרמיקה","כלי חרס","היסטוריה","תנור","yachimun","craft","מלאכת יד"],"en":{"hype":"A small museum on Okinawan pottery at the start of Yachimun street.","reality":"Small and well laid out with good English. Worth half an hour before shopping the street, not more.","tip":null,"baby_notes":"There is an elevator.","price":"¥350","serves":null,"dishes":[],"todo":"Walk the displays of old pieces and how they are made, then shop the street with a better eye.","special":"An old kiln found on the site sits inside the building.","highlights":["Old kiln inside","Pieces from the kingdom era"],"time_needed":"30-60 minutes","kosher_note":null,"plan_line":"Closed Mondays and from 28 December, check before going","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Ikutouen","name_ja":"育陶園","city":"okinawa","area":"Kokusai-dori & Makishi","category":"shopping","lat":26.2128,"lng":127.6925,"coord_precision":"approx","hype":"אחת הסדנאות הוותיקות ברחוב יאצ'ימון, עם חנות וסדנה שבה מכינים כלי בעצמם.","reality":"החנות יפה והכלים איכותיים, והסדנה היא הדרך הקלה לעשות משהו בידיים בנאהה.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":null,"tip":"את הכלים שמכינים בסדנה שולחים אחרי שריפה, לכן כדאי לשאול על משלוח לחו\"ל.","sources":["https://www.gltjp.com/en/directory/item/13453/"],"audience":"adults","baby_notes":null,"local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Ikutouen%20Okinawa","website_url":null,"serves":null,"dishes":[],"todo":"מסתכלים בחנות על הכלים של הסדנה, ומי שרוצה נרשם לסדנת צביעה או עבודה על אובניים.","special":"הסדנה פועלת ברחוב כבר דורות, ואת הכלים מייצרים באותה שכונה.","highlights":["סדנת צביעת שיסא","סדנת אובניים","כלים בדוגמאות קלאסיות"],"time_needed":"שעה","kosher":null,"kosher_note":null,"address":"1-22-33 Tsuboya, Naha, Okinawa","opens":null,"closes":null,"closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"afternoon","visit_mins":60,"booking":"recommended","plan_line":"לסדנה כדאי להזמין יום-יומיים מראש","baby_block":null,"tags":["pottery","workshop","ceramics","class","shisa","painting","wheel","קרמיקה","סדנה","כלי חרס","שיסא","צביעה","אובניים","חוג"],"en":{"hype":"One of the oldest workshops on Yachimun street, with a shop and a class where you make your own piece.","reality":"Nice shop with good pieces, and the class is the easy way to make something by hand in Naha.","tip":"Class pieces are shipped after firing, so ask about shipping abroad.","baby_notes":null,"price":null,"serves":null,"dishes":[],"todo":"Browse the workshop's pieces in the shop, and sign up for a painting or wheel class if you want.","special":"The workshop has been on the street for generations and makes its pieces in the same neighbourhood.","highlights":["Shisa painting class","Wheel class","Classic patterns"],"time_needed":"1 h