select x.name, x.name_ja, x.city, x.area, x.category, x.lat, x.lng, x.coord_precision, x.hype, x.reality, x.verdict, x.tabelog_score, x.google_score, x.price, x.tip, x.sources, x.audience, x.baby_notes, x.local_pick, x.maps_url, x.website_url, x.serves, x.dishes, x.todo, x.special, x.highlights, x.time_needed, x.kosher, x.kosher_note, x.address, x.opens, x.closes, x.closed_weekdays, x.closed_dates, x.open_dates, x.best_time, x.visit_mins, x.booking, x.plan_line, x.baby_block, x.tags, x.en, x.facts_at, x.facts_sure, false from jsonb_populate_recordset(null::place_library, $cards$[{"name":"Ramen Senju","name_ja":"らぁめん 千寿","city":"sapporo","area":"Odori & Susukino","category":"food","lat":43.0592,"lng":141.3477,"coord_precision":"approx","hype":"מסעדת ראמן מיסו במרתף ליד פארק אודורי, בסגנון של סומירה, שעובדי משרדים באים אליה בצהריים.","reality":"ראמן מיסו קלאסי וטוב במחיר נמוך, בלי תיירים. פתוח רק בצהרי ימי חול, אז צריך לתכנן.","verdict":"worth_it","tabelog_score":3.67,"google_score":null,"price":"עד ¥1,200 לסועד","tip":null,"sources":["https://tabelog.com/en/hokkaido/A0101/A010102/1000011/"],"audience":"adults","baby_notes":null,"local_pick":true,"maps_url":"https://www.google.com/maps/search/?api=1&query=Ramen%20Senju%20Sapporo","website_url":null,"serves":"ראמן מיסו בסגנון סומירה: מרק חם מאוד עם שכבת שומן שומרת חום ואטריות צהובות מסולסלות.","dishes":["ראמן מיסו","ראמן שויו"],"todo":null,"special":null,"highlights":[],"time_needed":null,"kosher":"hard","kosher_note":"המרק על בסיס עצמות חזיר, וגם הצ׳שו חזיר.","address":"Kita Odori Bldg B1F, 8-2-39 Odori Nishi, Chuo-ku, Sapporo","opens":"11:00","closes":"14:00","closed_weekdays":[0,6],"closed_dates":[],"open_dates":[],"best_time":"midday","visit_mins":40,"booking":"no","plan_line":"רק בימי חול 11:00-14:00. מגיעים לפני 12:00 לפני עובדי המשרדים","baby_block":"במרתף, מקום קטן","tags":["ramen","ראמן","noodles","נודלס","noodle soup","מרק נודלס","sapporo ramen","ראמן סאפורו","miso ramen","ראמן מיסו","miso","מיסו","shoyu ramen","ראמן שויו","lunch","ארוחת צהריים","local favorite","אהוב על מקומיים"],"en":{"hype":"A basement miso ramen shop near Odori Park in the Sumire style, packed with office workers at lunch.","reality":"Classic, good miso ramen at a low price, no tourists. Open only for weekday lunch, so plan around it.","tip":null,"baby_notes":null,"price":"Up to ¥1,200 per person","serves":"Sumire-style miso ramen: very hot broth under a layer of lard that keeps the heat, with curly yellow noodles.","dishes":["Miso ramen","Shoyu ramen"],"todo":null,"special":null,"highlights":[],"time_needed":null,"kosher_note":"The broth is made from pork bones and the chashu is pork.","plan_line":"Weekdays 11:00-14:00 only. Get there before noon","baby_block":"Basement, small space"},"facts_at":"2026-11-09","facts_sure":true},{"name":"Sumire Susukino","name_ja":"すみれ 札幌すすきの店","city":"sapporo","area":"Odori & Susukino","category":"food","lat":43.0567,"lng":141.3545,"coord_precision":"approx","hype":"הסניף המרכזי של סומירה, אחד משני השמות הגדולים של ראמן מיסו בסאפורו, דקה מתחנת סוסוקינו.","reality":"אותו מרק כמו בסניף הראשי הרחוק: חם מאוד, שומני ועשיר. מפורסם ובצדק, אבל בערבים יש תור ארוך.","verdict":"worth_it","tabelog_score":3.59,"google_score":null,"price":"¥1,000-1,600 לסועד","tip":"המרק מגיע רותח מתחת לשכבת שומן, כדאי לחכות רגע לפני הלגימה הראשונה.","sources":["https://tabelog.com/en/hokkaido/A0101/A010103/1009050/"],"audience":"baby","baby_notes":"יש שני שולחנות ל-4, ומותר להגיע עם תינוקות. בקומה השנייה.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Sumire%20Susukino%20Sapporo","website_url":null,"serves":"ראמן מיסו בסגנון סומירה, וגם ראמן מלח וראמן שויו.","dishes":["ראמן מיסו","ראמן מלח","ראמן שויו"],"todo":null,"special":null,"highlights":[],"time_needed":null,"kosher":"hard","kosher_note":"המרק על בסיס עצמות חזיר, וגם הצ׳שו חזיר.","address":"Pixis Bldg 2F, 3-9-2 Minami 3-jo Nishi, Chuo-ku, Sapporo","opens":"17:30","closes":"00:30","closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"evening","visit_mins":60,"booking":"no","plan_line":"נפתח רק ב-17:30. אין אשראי, אבל אפשר לשלם בסואיקה","baby_block":null,"tags":["ramen","ראמן","noodles","נודלס","noodle soup","מרק נודלס","sapporo ramen","ראמן סאפורו","miso ramen","ראמן מיסו","miso","מיסו","shio ramen","ראמן מלח","shoyu ramen","ראמן שויו","dinner","ארוחת ערב","famous","מפורסם"],"en":{"hype":"The central branch of Sumire, one of the two big names in Sapporo miso ramen, a minute from Susukino station.","reality":"Same broth as the far-off main shop: very hot, oily and rich. Famous for a reason, but expect a long line in the evening.","tip":"The broth arrives scalding under a layer of lard, so wait a moment before the first sip.","baby_notes":"Two tables for 4, and babies are welcome. Second floor.","price":"¥1,000-1,600 per person","serves":"Sumire-style miso ramen, plus salt and shoyu ramen.","dishes":["Miso ramen","Salt ramen","Shoyu ramen"],"todo":null,"special":null,"highlights":[],"time_needed":null,"kosher_note":"The broth is made from pork bones and the chashu is pork.","plan_line":"Opens only at 17:30. No credit cards, but Suica works","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Ebisoba Ichigen Sohonten","name_ja":"えびそば一幻 総本店","city":"sapporo","area":"Odori & Susukino","category":"food","lat":43.0511,"lng":141.3478,"coord_precision":"approx","hype":"ראמן שהמרק שלו עשוי מראשי שרימפס, מקום שמתחיל לו תור כבר בצהריים.","reality":"הטעם של השרימפס חזק ומיוחד ולא דומה לשום ראמן אחר בעיר. מי שלא אוהב טעם של פירות ים יתאכזב.","verdict":"worth_it","tabelog_score":3.59,"google_score":null,"price":"¥1,000-1,500 לסועד","tip":"בוחרים בסיס (מיסו, מלח או שויו) ועוצמה של טעם השרימפס.","sources":["https://tabelog.com/en/hokkaido/A0101/A010103/1025072/"],"audience":"baby","baby_notes":"מותר להיכנס עם עגלה, אבל יש רק דלפק.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Ebisoba%20Ichigen%20Sohonten%20Sapporo","web