select x.name, x.name_ja, x.city, x.area, x.category, x.lat, x.lng, x.coord_precision, x.hype, x.reality, x.verdict, x.tabelog_score, x.google_score, x.price, x.tip, x.sources, x.audience, x.baby_notes, x.local_pick, x.maps_url, x.website_url, x.serves, x.dishes, x.todo, x.special, x.highlights, x.time_needed, x.kosher, x.kosher_note, x.address, x.opens, x.closes, x.closed_weekdays, x.closed_dates, x.open_dates, x.best_time, x.visit_mins, x.booking, x.plan_line, x.baby_block, x.tags, x.en, x.facts_at, x.facts_sure, false from jsonb_populate_recordset(null::place_library, $cards$[{"name":"Takayama Festival Floats Exhibition Hall","name_ja":"高山祭屋台会館","city":"takayama","area":"Old Town","category":"sight","lat":36.15,"lng":137.2625,"coord_precision":"approx","hype":"אולם שמציג ארבע מתוך אחת-עשרה עגלות הפסטיבל של סתיו, בנות מאות שנים, עם גילופים ולכה.","reality":"העגלות מרשימות מקרוב, והכרטיס כולל אולם שני עם דגמים גדולים של מקדש ניקו. מי שלא מגיע לפסטיבל עצמו מקבל כאן את הטעימה הכי טובה.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"¥1,000","tip":"יש מדריך שמע באנגלית.","sources":["https://www.japan-guide.com/e/e5905.html"],"audience":"baby","baby_notes":"אולמות רחבים ושטוחים.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Takayama%20Festival%20Floats%20Exhibition%20Hall%20Takayama","website_url":null,"serves":null,"dishes":[],"todo":"מסתכלים על העגלות מאחורי זכוכית, שומעים את ההסבר, ועוברים לאולם ניקוקאן עם הדגמים. בסוף נכנסים למקדש סאקוראיאמה שצמוד.","special":"העגלות מתחלפות כמה פעמים בשנה, כך שכל ביקור מראה עגלות קצת אחרות.","highlights":["עגלות הפסטיבל","דגמי ניקו טושוגו","מקדש סאקוראיאמה"],"time_needed":"כ-45 דקות","kosher":null,"kosher_note":null,"address":"178 Sakuramachi, Takayama, Gifu","opens":"09:00","closes":"16:30","closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"any","visit_mins":45,"booking":"no","plan_line":"לשלב עם מקדש סאקוראיאמה הצמוד, בצפון העיר העתיקה","baby_block":null,"tags":["festival floats","yatai","takayama festival","museum","lacquer","carvings","nikko","עגלות פסטיבל","פסטיבל","מוזיאון","גילופים","לכה","יאטאי","matsuri","מצורי"],"en":{"hype":"A hall showing four of the eleven autumn festival floats, centuries old, with carvings and lacquer.","reality":"The floats are impressive up close, and the ticket also covers a second hall with large models of Nikko's shrine. If you miss the festival itself, this is the best taste of it.","tip":"English audio guide available.","baby_notes":"Wide, flat halls.","price":"¥1,000","serves":null,"dishes":[],"todo":"Look at the floats behind glass with the audio guide, then go to the Nikkokan hall with the models. Finish at Sakurayama Hachimangu next door.","special":"The floats rotate a few times a year, so each visit shows slightly different ones.","highlights":["Festival floats","Nikko Toshogu models","Sakurayama Hachimangu"],"time_needed":"About 45 minutes","kosher_note":null,"plan_line":"Pair with Sakurayama Hachimangu next door, north end of the old town","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Sakurayama Hachimangu Shrine","name_ja":"櫻山八幡宮","city":"takayama","area":"Old Town","category":"sight","lat":36.1503,"lng":137.263,"coord_precision":"approx","hype":"המקדש של פסטיבל הסתיו של טקאיאמה, בין עצי ארז גבוהים בקצה הצפוני של העיר העתיקה.","reality":"מקדש שקט ויפה, לא יותר מעשר דקות לבד; שווה בעיקר בשילוב עם אולם העגלות הצמוד.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"הכניסה חינם","tip":"הפסטיבל עצמו ב-9-10 באוקטובר, לא בחורף.","sources":["https://www.japan-guide.com/e/e5903.html"],"audience":"baby","baby_notes":"יש מדרגות בכניסה לאזור המקדש.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Sakurayama%20Hachimangu%20Shrine%20Takayama","website_url":null,"serves":null,"dishes":[],"todo":"עולים בשדרת העצים, עוברים בשער הטורי ומסתכלים על המבנה הראשי.","special":null,"highlights":["שדרת הארזים","השער הראשי"],"time_needed":"כ-15 דקות","kosher":null,"kosher_note":null,"address":"178 Sakuramachi, Takayama, Gifu","opens":null,"closes":null,"closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"any","visit_mins":15,"booking":"no","plan_line":"עשר דקות, רק בשילוב עם אולם העגלות","baby_block":null,"tags":["shrine","shinto","torii","cedar trees","festival","autumn festival","מקדש","שינטו","טורי","עצי ארז","פסטיבל","פסטיבל סתיו","hachiman","האצ׳ימאן"],"en":{"hype":"The shrine of Takayama's autumn festival, among tall cedars at the north end of the old town.","reality":"A quiet, pretty shrine, no more than ten minutes on its own; mainly worth it with the floats hall next door.","tip":"The festival itself is 9-10 October, not in winter.","baby_notes":"Some steps up to the shrine grounds.","price":"Free","serves":null,"dishes":[],"todo":"Walk up the tree-lined approach, pass the torii and look at the main hall.","special":null,"highlights":["Cedar approach","Main gate"],"time_needed":"About 15 minutes","kosher_note":null,"plan_line":"Ten minutes, best paired with the floats hall","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Kusakabe Folk Museum","name_ja":"日下部民藝館","city":"takayama","area":"Old Town","category":"sight","lat":36.1455,"lng":137.26,"coord_precision":"approx","hype":"בית סוחרים מ-1879 של משפחת מלווים עשירה, עם תקרת עץ גבוהה וקורות ענק, נכס תרבות חשוב.","reality":"החלל הפנימי עם הקורות החשופות הוא מהיפים בעיר, אבל הכרטיס יקר לביקור של חצי שעה.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"¥1,000","tip":"יש חנות קטנה של כלי מלאכה עממית מכל יפן.","sources":["https://www.kusakabe-mingeikan.com/","https://www.japan-guide.com/e/e5903.html"],"audience":"baby","baby_notes":"חולצים נעליים; בתוך הבית אין מקום לעגלה.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Kusakabe%20Folk%20Museum%20Takayama","website_url":"https://www.kusakabe-mingeikan.com/","serves":null,"dishes":[],"todo":"עוברים בין החדרים, מסתכלים למעלה אל מבנה הקורות, ונכנסים למחסן שבו מוצגים כלי שיבוקוסה ומלאכות עממיות.","special":"אטריום עץ גבוה ופתוח, שלפעמים משמש גם להופעות מוזיקה.","highlights":["תקרת הקורות","מחסן התצוגה","חנות המלאכות"],"time_needed":"כחצי שעה","kosher":null,"kosher_note":null,"address":"1-52 Oshinmachi, Takayama, Gifu","opens":"10:00","closes":"16:00","closed_weekdays":[2],"closed_dates":[],"open_dates":[],"best_time":"midday","visit_mins":30,"booking":"no","plan_line":"סגור בימי שלישי, פתוח רק 10:00-16:00","baby_block":null,"tags":["merchant house","heritage house","folk crafts","museum","wooden beams","architecture","mingei","בית סוחרים","בית מורשת","מלאכה עממית","מוזיאון","אדריכלות","קורות עץ","kusakabe","קוסאקבה"],"en":{"hype":"An 1879 merchant house of a wealthy moneylending family, with a tall wooden ceiling and huge beams; an Important Cultural Property.","reality":"The open beamed interior is one of the most beautiful in town, but the ticket is pricey for a 30-minute visit.","tip":"A small shop sells folk crafts from around Japan.","baby_notes":"Shoes off; no room for a stroller inside.","price":"¥1,000","serves":null,"dishes":[],"todo":"Walk the rooms, look up at the beam structure, and step into the storehouse showing Shibukusa ware and folk crafts.","special":"A tall open wooden atrium that sometimes hosts music events.","highlights":["Beamed ceiling","Storehouse gallery","Craft shop"],"time_needed":"About 30 minutes","kosher_note":null,"plan_line":"Closed Tuesdays, open only 10:00-16:00","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Yoshijima Heritage House","name_ja":"吉島家住宅","city":"takayama","area":"Old Town","category":"sight","lat":36.1458,"lng":137.2603,"coord_precision":"approx","hype":"בית מבשלת סאקה מ-1908 ליד בית קוסאקבה, עם גרם מדרגות סביב עמוד מרכזי וחלון גג שמכניס אור.","reality":"עדין ובהיר יותר מקוסאקבה, וזול בחצי. מי שבוחר רק אחד מהשניים ורוצה אור יפה, שיבחר בזה.","verdict":"gem","tabelog_score":null,"google_score":null,"price":"¥500","tip":"האור דרך חלון הגג הכי יפה בבוקר עד הצהריים.","sources":["https://www.hida.jp/english/touristattractions/takayamacity/historyandculture/4000168.html","https://www.japan-guide.com/e/e5903.html"],"audience":"baby","baby_notes":"חולצים נעליים; את העגלה משאירים בחוץ.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Yoshijima%20Heritage%20House%20Takayama","website_url":null,"serves":null,"dishes":[],"todo":"נכנסים לבית, מסתכלים על מבנה הקורות והעמודים, ויושבים רגע מול החצר הפנימית.","special":"זר עלי ארז גדול תלוי מתחת לגג, סימן של מבשלת סאקה.","highlights":["חלון הגג","גרם המדרגות","החצר הפנימית"],"time_needed":"כחצי שעה","kosher":null,"kosher_note":null,"address":"1-51 Oshinmachi, Takayama, Gifu","opens":"09:00","closes":"16:30","closed_weekdays":[2],"closed_dates":["2026-12-29","2026-12-30","2026-12-31"],"open_dates":[],"best_time":"morning","visit_mins":30,"booking":"no","plan_line":"בחורף סגור בימי שלישי ו-29-31 בדצמבר","baby_block":null,"tags":["heritage house","merchant house","sake brewery","architecture","wooden house","skylight","בית מורשת","בית סוחרים","מבשלת סאקה","אדריכלות","בית עץ","חלון גג","yoshijima","יושיג׳ימה"],"en":{"hype":"A 1908 sake brewer's house next to Kusakabe, with a staircase around a central pillar and a skylight.","reality":"Lighter and more delicate than Kusakabe, at half the price. If you pick one of the two and want nice light, pick this.","tip":"The skylight light is best from morning to midday.","baby_notes":"Shoes off; strollers stay outside.","price":"¥500","serves":null,"dishes":[],"todo":"Walk in, look at the beams and pillars, and sit a moment facing the inner courtyard.","special":"A big cedar ball hangs under the eaves, the sign of a sake brewery.","highlights":["Skylight","Staircase","Inner courtyard"],"time_needed":"About 30 minutes","kosher_note":null,"plan_line":"Winter: closed Tuesdays and 29-31 December","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Takayama Museum of History and Art","name_ja":"飛騨高山まちの博物館","city":"takayama","area":"Old Town","category":"sight","lat":36.1425,"lng":137.2612,"coord_precision":"approx","hype":"מוזיאון עירוני חינמי בשני מחסנים של משפחות סוחרים, על ההיסטוריה, הפסטיבל והבתים של טקאיאמה.","reality":"חינם, חם ונקי, ועם הגן הקטן הוא עצירה טובה בין רחובות. אין צורך יותר מ-45 דקות.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"הכניסה חינם","tip":"פתוח עד 19:00, טוב לשעה שהחנויות כבר סגורות.","sources":["https://www.hida.jp/english/touristattractions/takayamacity/historyandculture/4000115.html","https://www.japan-guide.com/e/e5903.html"],"audience":"baby","baby_notes":"מקום חם ושקט לעצירה עם התינוק.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Takayama%20Museum%20of%20History%20and%20Art%20Takayama","website_url":null,"serves":null,"dishes":[],"todo":"עוברים בין 14 חדרי התצוגה על הפסטיבל, בתי העיר והסופרים המקומיים, ויוצאים לגן.","special":null,"highlights":["חדרי הפסטיבל","הגן","המחסנים הישנים"],"time_needed":"כ-45 דקות","kosher":null,"kosher_note":null,"address":"75 Kamiichinomachi, Takayama, Gifu","opens":"09:00","closes":"19:00","closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"evening","visit_mins":45,"booking":"no","plan_line":"חינם ופתוח עד 19:00, עצירה טובה אחרי שהחנויות נסגרות","baby_block":null,"tags":["museum","history","free","local history","festival","storehouse","garden","מוזיאון","היסטוריה","חינם","היסטוריה מקומית","פסטיבל","מחסן","גן","museum of history","מוזיאון עירוני"],"en":{"hype":"A free city museum in two merchant storehouses, on Takayama's history, festival and houses.","reality":"Free, warm and clean, and with the small garden it is a good stop between streets. 45 minutes is plenty.","tip":"Open until 19:00, handy once the shops have closed.","baby_notes":"A warm, quiet place to stop with the baby.","price":"Free","serves":null,"dishes":[],"todo":"Walk through 14 rooms on the festival, town houses and local writers, then step out to the garden.","special":null,"highlights":["Festival rooms","Garden","Old storehouses"],"time_needed":"About 45 minutes","kosher_note":null,"plan_line":"Free and open until 19:00, good after the shops close","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Takayama Showa-kan","name_ja":"高山昭和館","city":"takayama","area":"Old Town","category":"sight","lat":36.144,"lng":137.2598,"coord_precision":"approx","hype":"רחוב שלם משוחזר של שנות ה-50 ביפן, עם חנות ממתקים, מספרה, צלמניה וקונסולות משחק ישנות.","reality":"כיף וצבעוני, מלא פרטים, אבל בלי קשר לטקאיאמה ההיסטורית. טוב ליום גשום או שלג.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"¥1,200","tip":null,"sources":["https://www.japan-guide.com/e/e5903.html","https://www.hida.jp/english/touristattractions/takayamacity/historyandculture/4000159.html"],"audience":"baby","baby_notes":"מסדרונות צרים וצפופים בחפצים, עם עגלה צריך זהירות.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Takayama%20Showa-kan%20Takayama","website_url":null,"serves":null,"dishes":[],"todo":"הולכים בסמטאות המשוחזרות, נכנסים לכיתה, לקולנוע ולמספרה, ומשחקים בקונסולות הישנות.","special":null,"highlights":["חנות הממתקים","הכיתה הישנה","משחקי וידאו ישנים"],"time_needed":"45 דקות-שעה","kosher":null,"kosher_note":null,"address":"6 Shimoichinomachi, Takayama, Gifu","opens":"09:00","closes":"17:00","closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"any","visit_mins":50,"booking":"no","plan_line":"מתאים ליום שלג או גשם, חם בפנים","baby_block":null,"tags":["retro","showa era","1950s","museum","nostalgia","toys","video games","רטרו","שנות החמישים","מוזיאון","נוסטלגיה","צעצועים","משחקי וידאו","יום גשום","showa","שוואה"],"en":{"hype":"A whole recreated 1950s Japanese street, with a candy shop, barber, photo studio and old game consoles.","reality":"Fun and colourful, packed with detail, but unrelated to historic Takayama. Good for a rainy or snowy day.","tip":null,"baby_notes":"Narrow, crowded aisles, careful with a stroller.","price":"¥1,200","serves":null,"dishes":[],"todo":"Walk the recreated alleys, step into the classroom, cinema and barber, and play the old consoles.","special":null,"highlights":["Candy shop","Old classroom","Retro video games"],"time_needed":"45-60 minutes","kosher_note":null,"plan_line":"Good for a snowy or rainy day, warm inside","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Higashiyama Walking Course","name_ja":"東山遊歩道","city":"takayama","area":"Old Town","category":"sight","lat":36.145,"lng":137.268,"coord_precision":"approx","hype":"שביל של כ-3.5 ק״מ על הגבעה במזרח העיר, עובר על פני יותר מתריסר מקדשים ועד חורבות הטירה בפארק שירויאמה.","reality":"שקט לגמרי לעומת סאנמאצ׳י, והמקדשים קטנים וחינמיים. בשלג חלק מהקטעים חלקלקים.","verdict":"gem","tabelog_score":null,"google_score":null,"price":"חינם","tip":"מתחילים במקדש ריואונג׳י ומסיימים בפארק שירויאמה, ומשם יורדים ישר לעיר העתיקה.","sources":["https://www.japan-guide.com/e/e5906.html","https://www.hida.jp/english/touristattractions/takayamacity/historyandculture/4000177.html"],"audience":"adults","baby_notes":"הרבה מדרגות ושבילי עפר, רק עם מנשא.","local_pick":true,"maps_url":"https://www.google.com/maps/search/?api=1&query=Higashiyama%20Walking%20Course%20Takayama","website_url":null,"serves":null,"dishes":[],"todo":"הולכים לאט בין המקדשים של טראמאצ׳י, נכנסים לחצרות השקטות, וממשיכים ביער אל פארק שירויאמה.","special":"מקדשים שהועברו לגבעה במאה ה-16, עם נוף של גגות העיר בין העצים.","highlights":["טראמאצ׳י","פארק שירויאמה","חורבות הטירה"],"time_needed":"שעה-שעתיים","kosher":null,"kosher_note":null,"address":"Tenshojimachi, Takayama, Gifu","opens":null,"closes":null,"closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"morning","visit_mins":100,"booking":"no","plan_line":"נעליים טובות, בשלג יש קטעים חלקים","baby_block":"מדרגות ושבילי עפר, רק עם מנשא","tags":["walking trail","temples","shrines","hike","castle ruins","quiet","nature","מסלול הליכה","מקדשים","מקדשים בודהיסטים","טיול","חורבות טירה","שקט","טבע","teramachi","טראמאצ׳י"],"en":{"hype":"A trail of about 3.5 km on the hill east of town, past more than a dozen temples to the castle ruins in Shiroyama Park.","reality":"Totally quiet next to Sanmachi, and the temples are small and free. Some parts get slippery in snow.","tip":"Start at Ryuunji Temple and end at Shiroyama Park, then walk straight down to the old town.","baby_notes":"Lots of steps and dirt paths, carrier only.","price":"Free","serves":null,"dishes":[],"todo":"Stroll slowly past the Teramachi temples, step into the quiet grounds, and continue through the woods to Shiroyama Park.","special":"Temples moved to the hill in the 1500s, with views of the town roofs through the trees.","highlights":["Teramachi","Shiroyama Park","Castle ruins"],"time_needed":"1-2 hours","kosher_note":null,"plan_line":"Good shoes, some parts get slippery in snow","baby_block":"Steps and dirt paths, carrier only"},"facts_at":"2026-11-09","facts_sure":true},{"name":"Shiroyama Park","name_ja":"城山公園","city":"takayama","area":"Old Town","category":"sight","lat":36.1365,"lng":137.264,"coord_precision":"approx","hype":"גבעה מיוערת מעל העיר במקום שבו עמדה טירת טקאיאמה.","reality":"מהטירה עצמה כמעט לא נשאר כלום, אבל זה יער שקט עם נוף קטן על העיר, עשר דקות מהעיר העתיקה.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"חינם","tip":"הכי טוב כסוף של מסלול היגאשיאמה.","sources":["https://www.japan-guide.com/e/e5906.html"],"audience":"adults","baby_notes":"עלייה תלולה, עגלה קשה.","local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Shiroyama%20Park%20Takayama","website_url":null,"serves":null,"dishes":[],"todo":"עולים ביער אל אתר הטירה, מסתכלים על העיר ויורדים חזרה לכיוון גשר נאקאבאשי.","special":null,"highlights":["אתר הטירה","נוף על העיר"],"time_needed":"כ-45 דקות","kosher":null,"kosher_note":null,"address":"Shiroyama, Takayama, Gifu","opens":null,"closes":null,"closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"morning","visit_mins":45,"booking":"no","plan_line":"לשלב כסוף מסלול היגאשיאמה, לא שווה נסיעה בפני עצמו","baby_block":null,"tags":["park","castle ruins","hill","forest","viewpoint","walk","פארק","חורבות טירה","גבעה","יער","תצפית","טיול רגלי","castle","טירה"],"en":{"hype":"A wooded hill above town where Takayama Castle once stood.","reality":"Almost nothing is left of the castle, but it is a quiet forest with a small view over town, ten minutes from the old town.","tip":"Best as the end of the Higashiyama walk.","baby_notes":"Steep climb, hard with a stroller.","price":"Free","serves":null,"dishes":[],"todo":"Walk up through the woods to the castle site, look over the town, and head back down toward Nakabashi Bridge.","special":null,"highlights":["Castle site","View over town"],"time_needed":"About 45 minutes","kosher_note":null,"plan_line":"End of the Higashiyama walk, not worth a trip on its own","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Nakabashi Bridge","name_ja":"中橋","city":"takayama","area":"Old Town","category":"sight","lat":36.1395,"lng":137.2597,"coord_precision":"approx","hype":"הגשר האדום מעל נהר מיאגאווה, התמונה הכי מוכרת של טקאיאמה.","reality":"שתי דקות של צילום, לא יותר; יפה במיוחד עם שלג על המעקות.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"חינם","tip":"הצילום הכי טוב מהגדה, לא מהגשר עצמו.","sources":["https://www.japan-guide.com/e/e5902.html"],"audience":"baby","baby_notes":null,"local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Nakabashi%20Bridge%20Takayama","website_url":null,"serves":null,"dishes":[],"todo":"עוברים על הגשר בדרך בין ג׳ינייה לסאנמאצ׳י ומצלמים מהגדה.","special":null,"highlights":["הגשר האדום","נהר מיאגאווה"],"time_needed":"כמה דקות","kosher":null,"kosher_note":null,"address":"Nakabashi, Takayama, Gifu","opens":null,"closes":null,"closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"any","visit_mins":10,"booking":"no","plan_line":"נמצא בדרך בין ג׳ינייה לסאנמאצ׳י, אין צורך לתכנן","baby_block":null,"tags":["bridge","red bridge","river","photo spot","miyagawa","snow","גשר","גשר אדום","נהר","מקום לצילום","מיאגאווה","שלג","nakabashi","נאקאבאשי"],"en":{"hype":"The red bridge over the Miyagawa, Takayama's best-known photo.","reality":"Two minutes for a photo, no more; extra pretty with snow on the railings.","tip":"The best shot is from the riverbank, not from the bridge.","baby_notes":null,"price":"Free","serves":null,"dishes":[],"todo":"Cross it between the Jinya and Sanmachi and take a photo from the bank.","special":null,"highlights":["Red bridge","Miyagawa River"],"time_needed":"A few minutes","kosher_note":null,"plan_line":"On the way from the Jinya to Sanmachi, no need to plan","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Shimoninomachi-Ojinmachi Preservation Area","name_ja":"下二之町大新町伝統的建造物群保存地区","city":"takayama","area":"Old Town","category":"sight","lat":36.146,"lng":137.2592,"coord_precision":"approx","hype":"הרחובות הצפוניים של העיר העתיקה, עם אותם בתי עץ כמו סאנמאצ׳י אבל עם חנויות מקומיות ולא תיירותיות.","reality":"כמעט ריק מתיירים: חנויות מוצ׳י, עתיקות, טאטאמי ודואר ישן. טוב למי שרוצה לראות את העיר כמו שהיא.","verdict":"gem","tabelog_score":null,"google_score":null,"price":"חינם","tip":"עוברים כאן בדרך מסאנמאצ׳י לבית קוסאקבה ולאולם העגלות.","sources":["https://www.hida.jp/english/touristattractions/takayamacity/historyandculture/4001666.html"],"audience":"baby","baby_notes":"רחובות שטוחים ושקטים, נוח עם עגלה.","local_pick":true,"maps_url":"https://www.google.com/maps/search/?api=1&query=Shimoninomachi-Ojinmachi%20Preservation%20Area%20Takayama","website_url":null,"serves":null,"dishes":[],"todo":"הולכים לאט ברחובות שימונינומאצ׳י ואוג׳ינמאצ׳י, מציצים לחנויות הקטנות ועוצרים בחנות ממתקים מקומית.","special":"אזור שימור שלא הפך לרחוב מז