select x.name, x.name_ja, x.city, x.area, x.category, x.lat, x.lng, x.coord_precision, x.hype, x.reality, x.verdict, x.tabelog_score, x.google_score, x.price, x.tip, x.sources, x.audience, x.baby_notes, x.local_pick, x.maps_url, x.website_url, x.serves, x.dishes, x.todo, x.special, x.highlights, x.time_needed, x.kosher, x.kosher_note, x.address, x.opens, x.closes, x.closed_weekdays, x.closed_dates, x.open_dates, x.best_time, x.visit_mins, x.booking, x.plan_line, x.baby_block, x.tags, x.en, x.facts_at, x.facts_sure, false from jsonb_populate_recordset(null::place_library, $cards$[{"name":"Hida Furukawa Festival Hall","name_ja":"飛騨古川まつり会館","city":"takayama","area":"Hida-Furukawa","category":"sight","lat":36.2378,"lng":137.1862,"coord_precision":"approx","hype":"מוזיאון של פסטיבל פורוקאווה, עם עגלות פסטיבל אמיתיות ותוף הענק של הפסטיבל.","reality":"קטן אבל מסביר טוב את הפסטיבל הלילי של אפריל, והעגלות מקרוב יפות. הכרטיס המשולב עם טאקומיקאן זול.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"¥700, ¥800 משולב עם טאקומיקאן","tip":null,"sources":["https://www.japan-guide.com/e/e5978.html"],"audience":"baby","baby_notes":null,"local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Hida%20Furukawa%20Festival%20Hall%20Hida%20Furukawa","website_url":null,"serves":null,"dishes":[],"todo":"מסתכלים על העגלות ועל התוף, קוראים על הפסטיבל הלילי של אפריל, וחוצים את הכיכר לטאקומיקאן.","special":null,"highlights":["עגלות הפסטיבל","תוף אוקושי דאיקו"],"time_needed":"30-45 דקות","kosher":null,"kosher_note":null,"address":"14-5 Ichinomachi, Furukawa-cho, Hida, Gifu","opens":"09:00","closes":"16:30","closed_weekdays":[],"closed_dates":["2026-12-29","2026-12-30","2026-12-31"],"open_dates":[],"best_time":"any","visit_mins":40,"booking":"no","plan_line":"לקנות כרטיס משולב עם טאקומיקאן, ¥800","baby_block":null,"tags":["festival","festival floats","museum","drum","taiko","furukawa festival","פסטיבל","עגלות פסטיבל","מוזיאון","תוף","טאיקו","מצורי","okoshi daiko","אוקושי דאיקו"],"en":{"hype":"A museum of the Furukawa Festival, with real floats and the festival's giant drum.","reality":"Small but explains the April night festival well, and the floats look great up close. The combo ticket with Takumikan is cheap.","tip":null,"baby_notes":null,"price":"¥700, ¥800 with Takumikan","serves":null,"dishes":[],"todo":"See the floats and the drum, read about the April night festival, and cross the square to Takumikan.","special":null,"highlights":["Festival floats","Okoshi daiko drum"],"time_needed":"30-45 minutes","kosher_note":null,"plan_line":"Buy the ¥800 combo ticket with Takumikan","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Hida no Takumi Bunkakan","name_ja":"飛騨の匠文化館","city":"takayama","area":"Hida-Furukawa","category":"sight","lat":36.2376,"lng":137.1866,"coord_precision":"approx","hype":"מוזיאון קטן לנגרים של הידה, עם חיבורי עץ בלי מסמרים שאפשר לפרק ולהרכיב ביד.","reality":"קטן וזול, והבניין עצמו בנוי בלי מסמרים. הפאזלים של חיבורי העץ כיפיים גם למבוגרים.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"¥300","tip":"בימי שישי נסגר מוקדם, ב-15:30.","sources":["https://www.japan-guide.com/e/e5979.html"],"audience":"baby","baby_notes":null,"local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Hida%20no%20Takumi%20Bunkakan%20Hida%20Furukawa","website_url":null,"serves":null,"dishes":[],"todo":"מסתכלים על כלי הנגרות, ומנסים לפרק ולהרכיב את דגמי חיבורי העץ.","special":"הבניין עצמו נבנה בשיטות הנגרות המסורתיות.","highlights":["חיבורי עץ להרכבה","כלי נגרות ישנים"],"time_needed":"כחצי שעה","kosher":null,"kosher_note":null,"address":"10-1 Ichinomachi, Furukawa-cho, Hida, Gifu","opens":"09:00","closes":"16:30","closed_weekdays":[4],"closed_dates":[],"open_dates":[],"best_time":"any","visit_mins":25,"booking":"no","plan_line":"סגור בימי חמישי, ובשישי נסגר ב-15:30","baby_block":null,"tags":["carpentry","woodwork","joinery","museum","crafts","wood","נגרות","עבודת עץ","חיבורי עץ","מוזיאון","מלאכות","עץ","takumikan","טאקומיקאן"],"en":{"hype":"A small museum on Hida carpenters, with nail-free wood joints you can take apart and put back by hand.","reality":"Small and cheap, and the building itself has no nails. The joinery puzzles are fun for adults too.","tip":"On Fridays it closes early, at 15:30.","baby_notes":null,"price":"¥300","serves":null,"dishes":[],"todo":"Look at the carpentry tools and try taking apart and rebuilding the joint models.","special":"The building itself was made with traditional carpentry methods.","highlights":["Hands-on wood joints","Old carpentry tools"],"time_needed":"About 30 minutes","kosher_note":null,"plan_line":"Closed Thursdays, closes 15:30 on Fridays","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Enkoji Temple","name_ja":"円光寺","city":"takayama","area":"Hida-Furukawa","category":"sight","lat":36.2383,"lng":137.1876,"coord_precision":"approx","hype":"מקדש על תעלת סטו, עם גילוף של ״צב שקורא למים״ שלפי המסורת הציל אותו משריפה גדולה.","reality":"עצירה של כמה דקות בדרך לאורך התעלה, יפה בעיקר כחלק מהנוף.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"חינם","tip":"ב-15 בינואר בערב, בטקס שלושת המקדשים, התעלה מוארת באלף נרות.","sources":["https://hugkum.sho.jp/561682"],"audience":"baby","baby_notes":null,"local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Enkoji%20Temple%20Hida%20Furukawa","website_url":null,"serves":null,"dishes":[],"todo":"מחפשים את גילוף הצב בגמלון של האולם הראשי וממשיכים לאורך התעלה.","special":null,"highlights":["גילוף הצב"],"time_needed":"כעשר דקות","kosher":null,"kosher_note":null,"address":"Furukawa-cho, Hida, Gifu","opens":null,"closes":null,"closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"any","visit_mins":10,"booking":"no","plan_line":"בדרך לאורך התעלה, לחפש את גילוף הצב","baby_block":null,"tags":["temple","buddhist temple","carving","canal","candles","מקדש","מקדש בודהיסטי","גילוף","תעלה","נרות","sandera mairi","סאנדרה מאירי"],"en":{"hype":"A temple on the Seto canal with a \"water-calling turtle\" carving said to have saved it from a great fire.","reality":"A few minutes' stop along the canal, nice mainly as part of the view.","tip":"On the evening of 15 January, at the three-temples rite, the canal is lit by a thousand candles.","baby_notes":null,"price":"Free","serves":null,"dishes":[],"todo":"Find the turtle carving on the main hall gable and keep walking along the canal.","special":null,"highlights":["Turtle carving"],"time_needed":"About 10 minutes","kosher_note":null,"plan_line":"On the canal walk, look for the turtle carving","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Honkoji Temple","name_ja":"本光寺","city":"takayama","area":"Hida-Furukawa","category":"sight","lat":36.2395,"lng":137.1858,"coord_precision":"approx","hype":"מקדש עץ גדול שלוש דקות מתחנת הידה-פורוקאווה, אחד משלושת המקדשים של טקס סאנדרה מאירי.","reality":"אולם עץ גדול ושקט, כמעט בלי מבקרים; טוב לכמה דקות בדרך מהתחנה.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"חינם","tip":null,"sources":["https://hugkum.sho.jp/561682"],"audience":"baby","baby_notes":null,"local_pick":true,"maps_url":"https://www.google.com/maps/search/?api=1&query=Honkoji%20Temple%20Hida%20Furukawa","website_url":null,"serves":null,"dishes":[],"todo":"נכנסים לחצר, מסתכלים על האולם הראשי וממשיכים לרחובות העתיקים.","special":null,"highlights":["האולם הראשי"],"time_needed":"כעשר דקות","kosher":null,"kosher_note":null,"address":"Furukawa-cho, Hida, Gifu","opens":null,"closes":null,"closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"any","visit_mins":10,"booking":"no","plan_line":"שלוש דקות מהתחנה, עצירה קצרה בדרך","baby_block":null,"tags":["temple","buddhist temple","wooden hall","quiet","מקדש","מקדש בודהיסטי","אולם עץ","שקט","sandera mairi","סאנדרה מאירי"],"en":{"hype":"A large wooden temple three minutes from Hida-Furukawa Station, one of the three temples of the Sandera Mairi rite.","reality":"A big, quiet wooden hall with almost no visitors; good for a few minutes on the way from the station.","tip":null,"baby_notes":null,"price":"Free","serves":null,"dishes":[],"todo":"Walk into the grounds, look at the main hall and continue to the old streets.","special":null,"highlights":["Main hall"],"time_needed":"About 10 minutes","kosher_note":null,"plan_line":"Three minutes from the station, a short stop on the way","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Mishima Japanese Candle Shop","name_ja":"三嶋和ろうそく店","city":"takayama","area":"Hida-Furukawa","category":"shopping","lat":36.239,"lng":137.1869,"coord_precision":"approx","hype":"חנות נרות יפניים בעבודת יד, מנר צמחי ופתיל נייר, שעובדת כבר דורות.","reality":"חנות קטנה, ולפעמים רואים את הכנת הנרות בזמן אמת. מזכרת שונה וקלה לסחוב.","verdict":"gem","tabelog_score":null,"google_score":null,"price":"נרות מכמה מאות ין","tip":null,"sources":["https://www.japan-guide.com/e/e5980.html","https://www.mapple.net/spot/21000899/"],"audience":"baby","baby_notes":"חנות קטנה, עגלה נכנסת בקושי.","local_pick":true,"maps_url":"https://www.google.com/maps/search/?api=1&query=Mishima%20Japanese%20Candle%20Shop%20Hida%20Furukawa","website_url":null,"serves":null,"dishes":[],"todo":"מסתכלים על הנרות הצבועים ביד, ואם יש הדגמה צופים בטבילת הפתיל בשעווה.","special":"נרות משעווה צמחית עם פתיל נייר ועשב, בשיטה הישנה.","highlights":["נרות צבועים ביד","הדגמת הכנה"],"time_needed":"כרבע שעה","kosher":null,"kosher_note":null,"address":"3-12 Ichinomachi, Furukawa-cho, Hida, Gifu","opens":"09:30","closes":"17:00","closed_weekdays":[3],"closed_dates":[],"open_dates":[],"best_time":"any","visit_mins":15,"booking":"no","plan_line":"סגור בימי רביעי","baby_block":null,"tags":["candles","japanese candles","warosoku","crafts","handmade","souvenir","נרות","נרות יפניים","מלאכת יד","עבודת יד","מזכרת","שעווה","candle shop"],"en":{"hype":"A shop of hand-made Japanese candles, of plant wax with paper wicks, run for generations.","reality":"A small shop, and sometimes you can watch candles being made. A different souvenir that is light to carry.","tip":null,"baby_notes":"Small shop, a stroller barely fits.","price":"Candles from a few hundred yen","serves":null,"dishes":[],"todo":"Look at the hand-painted candles and, if there is a demo, watch the wick dipped in wax.","special":"Plant-wax candles with paper and rush wicks, the old way.","highlights":["Hand-painted candles","Making demo"],"time_needed":"About 15 minutes","kosher_note":null,"plan_line":"Closed Wednesdays","baby_block":null},"facts_at":"2026-11-09","facts_sure":true},{"name":"Kaba Sake Brewery","name_ja":"蒲酒造場","city":"takayama","area":"Hida-Furukawa","category":"shopping","lat":36.2392,"lng":137.1874,"coord_precision":"approx","hype":"מבשלה ותיקה ברחוב איצ׳ינומאצ׳י, יצרנית ״שיראמאיומי״, ליד מבשלת וואטאנבה.","reality":"חנות מבשלה יפה עם בניין עץ ישן. טובה לקניית בקבוק; סיור המבשלה לא פועל באוקטובר-דצמבר.","verdict":"worth_it","tabelog_score":null,"google_score":null,"price":"בקבוק 720 מ״ל מ-¥1,650","tip":"יש גם סאקה מבעבע ״ג׳אנפאן״, מתנה טובה.","sources":["https://www.kankou-gifu.jp/spot/detail_3836.html"],"audience":"adults","baby_notes":null,"local_pick":false,"maps_url":"https://www.google.com/maps/search/?api=1&query=Kaba%20Sake%20Brewery%20Hida%20Furukawa","website_url":null,"serves":null,"dishes":[],"todo":"נכנסים לחנות, בוחרים בקבוק ג׳ונמאי גינג׳ו או סאקה מבעבע, ומצלמים את חזית העץ.","special":null,"highlights":["שיראמאיומי","סאקה מבעבע ג׳אנפאן"],"time_needed":"כעשר דקות","kosher":null,"kosher_note":null,"address":"6-6 Ichinomachi, Furukawa-cho, Hida, Gifu","opens":"09:00","closes":"17:00","closed_weekdays":[],"closed_dates":[],"open_dates":[],"best_time":"any","visit_mins":10,"booking":"no","plan_line":"לקנות בקבוק, סיורים לא פועלים בדצמבר","baby_block":null,"tags":["sake","sake brewery","souvenir","sparkling sake","alcohol","junmai ginjo","סאקה","מבשלת סא